window.__D("text/likkutei-sichot/c017",{"p":[[1301550298,"ולפלא קצת שלא הזכיר זה (ככל הדרוש) בשער הגאולה בספר אהל ישרים הנ\"ל.\nבכבוד ובברכה ולבשו\"ט מביאת מבשר טוב שאז יהפכו ימים אלו לששון ולשמחה ולימים טובים.\n<span data-k=\"q\">(ממכתב ח' מנ\"א תשכ\"א)</span>\n<hr>\n... בראותי הרגש לבו ואהבתו לכפר חב\"ד, בתוככי אהבת ישראל בכלל, הרי ההתחזקות בזה היא דבר בעתו בפרט בימים אלו שבין המצרים דחורבן בית שני שקרה מפני שנאת חינם, כהודעת חכמינו ז\"ל. ופשוט שזה שנצטוינו לעשות זכר לחורבן, בימים אלו ביחוד, הכוונה היא בשביל התיקון, שהרי החורבן הוא כנוסח התפלה ומפני חטאינו גלינו מארצנו, ואי אפשר לביטול המסובב כי אם על ידי ביטול הסיבה, וכל גרעון וחלישות בסיבה מביאה גרעון וחלישות בהמסובב, אפילו הוא — כמבואר בתורת החסידות — לעת עתה רק בעולמות העליונים. וכיון שעיקר החטא הי' שנאת חינם, הרי תיקונו באהבת חינם.\nויהי רצון שבקרוב ממש נזכה לקץ גלותנו ולגאולה האמתית והשלימה על ידי משיח צדקנו, ויהפכו ימים אלו לששון ולשמחה.\n<span data-k=\"q\">(ממכתב ה' מנ\"א תשכ\"ד)</span>\n<hr>\n... אין די נייען טעג, דערמאָנען זיך אַלע אויף דעם מאמר רז\"ל, אַז דער חורבן איז געווען פאַר דעם חטא פון שנאת חנם, דאָס הייסט ניט ליב האָבן דעם צווייטן אָן קיין שום פאַרוואָס, און אָן קיין שום יסוד, מיר אַלע אידן ווילן דאָך אַרויס פון גלות וואָס פריער, במילא דאַרפמען אַראָפּנעמען די סיבה וואָס האָט מיטגעבראַכט דעם גלות, וואָס דער תיקון אויף דעם איז \"אהבת חנם\" דאָס הייסט האָלט האָבן אַ אידן אָן אַ פאַרוואָס, און אפילו אַזאַ אידן, וואָס דער עם ישראל האָט פון אים קיין טובה ניט, און מען ווייסט ניט צי האָט בכלל וועלכער איד פון אים אַ טובה, און עס איז אפילו אַ ספק צי מען קאָן אויף אים אָנווענדען דעם ואהבת לרעך"],[1301550299,"כמוך, ווייל ער איז ניט קיין רעך ר\"ל, ער לערנט ניט קיין תורה און איז ניט מקיים קיין מצות, קומט אָבער \"אהבת חנם\" אַז אויך אַזאַ אידן זאָל מען האָלט האָבן, און אַז מען פירט זיך אַזוי, נעמט [מען] דערמיט אַראָפּ די סיבה וואָס האָט מיטגעבראַכט דעם חורבן און גלות, און דערמיט מאַכט דער איד ליכטיג זיין ווינקעל, במילא ווערט ליכטיג בחלקו בעולם און עס קומט צו מער ליכטיגקייט, ביז סוף כל סוף וועט מען באַלייכטן דעם גלות און מיר וועלן זוכה זיין צו דער גאולה השלימה והאמיתית בעגלא דידן דורך משיח צדקנו.\n<span data-k=\"q\">(ממכתב ד' מנ\"א, תשי\"א)</span>\n<hr>"],[1301550300,"<h3>ה' מנחם--אב</h3>\nב\"ה, יום ועש\"ק<sup data-n=\"1766\">1</sup>, פ' איכה אשא לבדי<sup data-n=\"1767\">2</sup>, פ' חזון<sup data-n=\"1768\">4</sup><sup data-n=\"1769\">3</sup>,\nה' מנחם אב, יום הסתלקות האר\"י ז\"ל<sup data-n=\"1770\">5</sup>,\nה'תשמ\"ז, שנת השמיטה. ברוקלין, נ.י.\nאל כל בני ובנות ישראל\nבכל מקום שהם\nה' עליהם יחיו\nשלום וברכה!\nביום זה, יום הסתלקות האריז\"ל החי,\nשעת הכושר היא במיוחד להתבונן בדרכים הישרים אשר — בל' רבנו הזקן באגרת הקודש<sup data-n=\"1771\">6</sup> שלו — הורנו מדרכיו (שלו) ונלכה באורחותיו<sup data-n=\"1772\">7</sup> (שלו),\nשהרי ודאי זהו אחד הטעמים שדוקא דרכים ואורחות אלו גילה וגילו תלמידיו ונתפרסמו בכל תפוצות ישראל.\nואף כי \"מי הוא זה ואיזהו אשר ערב לבו<sup data-n=\"1773\">8</sup>\" לאמר שיעבוד עבודת הקודש של \"עיר וקדיש מן שמייא נחית<sup data-n=\"1774\">10</sup> הרב הגדול האלקי החסיד<sup data-n=\"1775\">9</sup>\" האריז\"ל,\n\"מ\"מ הרי אפס קצהו ושמץ מנהו מרוב טובו ואורו מאיר לכללות ישראל בכל",[["1766","1","<b>ועש\"ק</b>: שהוכפל בו טוב, ועוד יותר, בפעם הב' — טוב מאד (בראשית א, כה. שם, לא)."],["1767","2","<b>איכה אשא לבדי</b>: פרשתנו א, יב. וראה איכ\"ר (פתיחתא יא בסופה. פ\"א א) שייכותה לאיכה ישבה דירמי'. וי\"ל שהוא ע\"ד הקדמת רפואה למכה. ובפרט שירמי' משבט לוי וכהן (ירמי' בתחלתו) וניצוץ דנשמת משה (מג\"ע אופן פה. קה\"י בערכו)."],["1768","4","<b>חזון</b>: ראה תקו\"ז תל\"ט בסופו (ובתניא פי\"ד מהקדמת תקו\"ז דילג חוזים). ולהעיר מל\"ת להאריז\"ל לך עה\"פ ותרדמה."],["1769","3","<b>פ' חזון</b>: ראה אוה\"ת (להצ\"צ) לאיכה בסופו: ומחזון ותחזינה עינינו כו'; ושם בהערה תורת הגה\"צ וכו' הרב מברדיטשוב נבג\"מ בענין שבת חזון."],["1770","5","<b>ה' מנחם אב. . האר\"י ז\"ל</b>: בשנת של\"ב (שה\"ג להחיד\"א בערכו. ובכ\"מ). וראה תענית (כו, א): בה' באב בני פרעוש בן יודא."],["1771","6","<b>באגרת הקודש</b>: סי' זך — לנחמם בכפליים לתושי' על פטירת כו' מוהר\"ר מ\"מ נ\"ע (מהאראדאק)."],["1772","7","<b>מדרכיו. . באורחותיו</b>: החילוק — ראה זח\"ב רטו, א. לקו\"ת שה\"ש יב, ב."],["1773","8","<b>ואף. . לבו</b>: ראה תניא פמ\"ד."],["1774","10","<b>עיר. . נחית</b>: ראה דניאל ד, י. ובל\"ת להאריז\"ל ובס' הליקוטים (שם ד, יד). פסחים לג, א."],["1775","9","<b>עיר וקדיש. . החסיד</b>: הרח\"ו בהקדמתו לשער ההקדמות הקדמה א."]]],[1301550301,"דור ודור<sup data-n=\"1776\">11</sup>\", וביחד עם גילוי ופרסום הנהגות אלו וההוראות — ה\"ז ג\"כ נתינת כח וסיוע רב ללכת בדרכים ואורחות אלו<sup data-n=\"1777\">12</sup>, מעין עבודת הקודש האמורה.\nוהעיקר — שתביא ההתבוננות למעשה בפועל, שהמעשה הוא העיקר<sup data-n=\"1778\">13</sup>.\nואבינו שבשמים ימלא משאלות לבב כאו\"א שי' לטובה בגו\"ר,\nבתוך בקשות ותפלות כאחבנ\"י שליט\"א בכ\"מ שהם, בחו\"ל ובאה\"ק, \"אשר נשבע ה' לאברהם ליצחק וליעקב לתת להם<sup data-n=\"1779\">15</sup> ולזרעם אחריהם<sup data-n=\"1780\">14</sup>\", ארץ אשר \"תמיד עיני ה' אלקיך בה מרשית השנה<sup data-n=\"1781\">16</sup> ועד אחרית שנה\",\nכאחבנ\"י כולנו כאחד, שהרי הקדמת התפלה<sup data-n=\"1782\">33</sup> היא, כהוראת האר\"י, קבלת מצות עשה של ואהבת<sup data-n=\"1783\">18</sup> לרעך כמוך<sup data-n=\"1784\">17</sup>,\nובפרט ובמיוחד התפלה שלש פעמים ביום זה (ובכל ימי החול דכל השנה כולה): את צמח דוד עבדך מהרה תצמיח כו' (אשר לזה) קווינו כל היום, ובהמשך אלי' (ובפ\"ע — בשויו\"ט):\nרצה ה' אלקינו בעמך ישראל כו' והשב העבודה לדביר ביתך כו' ותחזינה עינינו בשובך לציון ברחמים —\nויהפכו ימים אלה<sup data-n=\"1785\">19</sup> \"להיות ימים טובים<sup data-n=\"1786\">21</sup> וימי ששון ושמחה<sup data-n=\"1787\">20</sup>\".\nוזריזות במעשינו (תורה ומצוות — ובזה גמ\"ח<sup data-n=\"1788\">24</sup>) ועבודתנו<sup data-n=\"1789\">22</sup> (תפלה<sup data-n=\"1790\">23</sup>) בכלל, ובלימוד",[["1776","11","<b>מ\"מ. . ודור</b>: תניא שם (בנוגע למשה רבנו. וידוע שהאר\"י הי' ניצוץ מרע\"ה — שה\"ג שם. ובכ\"מ)."],["1777","12","<b>ללכת בדרכים ואורחות אלו</b>: ראה ע\"ד ב-ג מדרכים אלו המובאים בכתהאריז\"ל — מכתב אור ליום ה' מנ\"א ה'תשל\"ב (לקו\"ש ח\"ט ע' 252)."],["1778","13","<b>שהמעשה הוא העיקר</b>: אבות פ\"א מי\"ז. תקו\"ז תנ\"ב (פז, סע\"א). ת\"ס (צג, ב). ת\"ע (קלג, ב. קלד, א)."],["1779","15","<b>לתת להם</b>: מכאן לתחה\"מ מן התורה (סנהדרין צ, ב ובפרש\"י שם). וי\"ל דכיון שממשיך \"ולזרעם אחריהם\" — מוכח שע\"י הנתינה להם לעת\"ל איגלאי מילתא למפרע שקבלוה קודם לזרעם."],["1780","14","<b>אשר נשבע. . אחריהם</b>: פרשתנו דברים א, ח."],["1781","16","<b>ארץ. . שנה</b>: עקב יא, יב. וראה או\"ת להה\"מ (הוצאת קה\"ת) הוספות סי' קסד-קסה."],["1782","33","<b>התפלה</b>: תהלים פו, ג-יז."],["1783","18","<b>ואהבת לרעך כמוך</b>: קדושים יט, יח."],["1784","17","<b>הקדמת התפלה. . כמוך</b>: מג\"א ואדה\"ז שו\"ע או\"ח רסמ\"ו (סי\"א) בשם ס' הכוונות. אדה\"ז בסידורו. נתבאר בס' מאמרי אדה\"ז על פרשיות התורה (כרך ב) ע' תקצא ואילך. סה\"ש ת\"ש ע' 157. וראה מקומות המצויינים בסו\"ס מאמרי אדה\"ז הנ\"ל (ע' תתקמא טור ב' ד\"ה קודם). וראה לקו\"ש חכ\"ה ע' 374."],["1785","19","<b>ויהפכו ימים אלה</b>: ע\"פ ירמי' לא, יב."],["1786","21","<b>ימים טובים</b>: כן הוא ברמב\"ם דפוס רומי וכו' (מתאים לההמשך: וימי ששון), ולא כבדפוסים הרגילים \"יום טוב\"."],["1787","20","<b>להיות. . ושמחה</b>: רמב\"ם סוף הל' תעניות. וחותם (ומעתיק גם): והאמת והשלום אהבו."],["1788","24","<b>ומצוות — ובזה גמ\"ח</b>: ראה מפרשי המשנה לאבות שם. ובירושלמי פאה פ\"א ה\"א דצדקה וגמ\"ח שקולות כנגד כל מצוותי' של תורה. תניא פל\"ז."],["1789","22","<b>במעשינו. . ועבודתנו</b>: תניא רפל\"ז. וראה לקוטי לוי\"צ לתניא שם."],["1790","23","<b>תורה. . גמ\"ח. . תפלה</b>: ג' דברים שעליהם העומד עומד (אבות פ\"א מ\"ב)."]]],[1301550302,"פנימיות התורה: זוה\"ק<sup data-n=\"1791\">26</sup> כו' כתבי האריז\"ל וכו' בפרט (וכפי שהאריך<sup data-n=\"1792\">27</sup> תלמידו הרח\"ו),\nובמיוחד בשנה זו שנת השמיטה, אשר ע\"י \"עשו את השמיטין\" (בכל זמן ובכל מקום, ע\"פ המבואר בשו\"ע) מתקיים: רצית השם ארצך<sup data-n=\"1793\">28</sup> שבת שבית יעקב,\nתזרז ותביא הגאולה<sup data-n=\"1794\">25</sup> האמיתית והשלימה — גאולת העם בשלימותו, הארץ בשלימותה והתומ\"צ בשלימותן<sup data-n=\"1795\">29</sup> — באופן דאחישנה<sup data-n=\"1796\">30</sup>, וארו עם ענני<sup data-n=\"1797\">32</sup> שמיא<sup data-n=\"1798\">31</sup>,\nותקויים התפלה: הושע עבדך, שמח נפש עבדך, פנה אלי וחנני, עזרתני ונחמתני.\nותחזינה עינינו — עם הנבחר — בבית הבחירה, מקדש אדנ-י כוננו ידיך<sup data-n=\"1799\">34</sup>, ביהמ\"ק הנצחי.\nבברכה\nנ.ב.\nמובן וגם פשוט אשר הנ\"ל, השייך במיוחד ליום ההסתלקות<sup data-n=\"1800\">35</sup> דהאריז\"ל, בתקפו",[["1791","26","<b>ובלימוד. . זוה\"ק</b>: ובאופן דמיני' יתפרנסון בהבנה והשגה (תקו\"ז ת\"ו בסופו. ובהקדמת מקדש מלך לזהר: יתפרנסון. . כשיפורש להם אמיתות מאמריו כו'. בכסא מלך לתקו\"ז שם)."],["1792","27","<b>שהאריך</b>: בהקדמתו על שער ההקדמות הקדמה א' (נדפסה גם בע\"ח ווארשא תרנ\"א. בקונטרס עץ החיים לכ\"ק אדמו\"ר (מהורש\"ב) נ\"ע בסופו. ועוד). — וראה אגה\"ק סכ\"ו (קמב, ב). וראה קונטרס עה\"ח הנ\"ל ע' 49 ואילך."],["1793","28","<b>עשו את השמיטין. . רצית השם ארצך</b>: תהלים פה, ב ובמדרש תהלים עה\"פ."],["1794","25","<b>ובלימוד פנימיות התורה. . הגאולה</b>: להעיר ממענת משיח להבעש\"ט על שאלתו אימתי אתי מר, בעת שיתפרסם למודך ויתגלה בעולם ויפוצו מעיינותיך חוצה כו' (אגה\"ק דהבעש\"ט — נדפסה בס' בן פורת יוסף. התחלת כש\"ט)."],["1795","29","<b>והתומ\"צ בשלימותן</b>: כי אז דוקא יהי' הלימוד והקיום בשלימות (רמב\"ם בסופו. תו\"ח ר\"פ ויחי. המשך וככה תרל\"ז פי\"ז ואילך. ועוד)."],["1796","30","<b>דאחישנה</b>: ישעי' ס, כב. סנהדרין צח, א. ירושלמי תענית פ\"א ה\"א. זח\"א קטז, ב ואילך. שערי אורה ד\"ה יביאו לבוש מלכות פצ\"ו."],["1797","32","<b>וארו. . שמיא</b>: דניאל ז, יג. סנהדרין שם."],["1798","31","<b>דאחישנה. . ענני שמיא</b>: ע\"ד פתגם הידוע דאדמו\"ר מהר\"ש (אג\"ק כ\"ק אדמו\"ר מהוריי\"צ נ\"ע ח\"א ע' תריז): מלכתחילה אַריבער."],["1799","34","<b>מקדש. . ידיך</b>: בשלח טו, יז ובפרש\"י שם. וראה פרש\"י סוכה מא, סע\"א. ועוד. יל\"ש תהלים רמז תתמח בסופו."],["1800","35","<b>במיוחד ליום ההסתלקות</b>: ראה אגה\"ק סכ\"ז-כ\"ח."]]],[1301550303,"הוא בכל ימות השנה, אלא שיום סגולה הוא, ראש ומוסיף כח בהם וכו' — ובדוגמת זכר ליצי\"מ ביום צאתם מארמ\"צ (יום א' דחה\"פ<sup data-n=\"1801\">36</sup>) וחיובו הוא בכל ימות השנה.\n<hr>\nב\"ה, אור ליום ג' שהוכפל בו כי טוב<sup data-n=\"1802\">1</sup>,\nפ' אלה הדברים<sup data-n=\"1803\">2</sup> אשר דבר משה<sup data-n=\"1804\">3</sup>,\nיום חמישי לחודש מנחם-אב<sup data-n=\"1805\">4</sup>,\nשנת ה'תשמח, שנת הקהל,\nברוקלין, נ.י.\nאל כל בני ובנות ישראל\nבכל מקום שהם\nה' עליהם יחיו\nשלום וברכה!\nמצו\"ב העתק המכ'<sup data-n=\"1806\">6</sup> מאור ליום האמור משנת ה'תשל\"ב,",[["1801","36","<b>יום א' דחה\"פ</b>: ובו עצמו בלילה ההוא נגלה עליהם ממה\"מ הקב\"ה בכבודו ובעצמו וגאלם (הגש\"פ פיסקא ויוציאנו ומצה זו). וי\"ל שהוא ע\"ד הקדמת רפואה למכה — ויבכו העם בלילה ההוא (שלח יד, א) שגרמה בכיית ליל תשעה באב<sup data-n=\"e200\">*</sup> (תענית כט, א) ולעת\"ל יהפכו לימים טובים וימי ששון ושמחה. וי\"ל שההקדמה מאפשרת ומביאה \"אחישנה\"."],["1802","1","<b>שהוכפל בו כי טוב</b>: פרש\"י בראשית א, ז (מב\"ר פ\"ד, ו). ובאוה\"ת (בראשית לג, א ואילך. ועוד) מקשר זה עם טוב לשמים וטוב לבריות (קידושין מ, א)."],["1803","2","<b>אלה הדברים</b>: פרשתנו א, א."],["1804","3","<b>משה</b>: גואל ראשון הוא גואל אחרון (ראה שמו\"ר פ\"ב, ד. זח\"א רנג, א. שעה\"פ להאריז\"ל פ' ויחי. תו\"א ר\"פ משפטים), גאולה באופן דה' אלקיכם ההולך לפניכם גו' כאשר ישא איש את בנו (שיעור היומי בחומש — דברים א, ל-לא)."],["1805","4","<b>יום חמישי לחודש מנחם אב</b>: יום הסתלקות האר\"י ז\"ל."],["1806","6","<b>העתק המכתב. . ה'תשל\"ב</b>: נדפס בלקו\"ש ח\"ט ע' 251 ואילך. וראה ג\"כ מכתב יום ועש\"ק פ' חזון, ה' מנחם אב ה'תשמ\"ז (לעיל ע' 231)."],["e200","*","וכידוע ה\"סימן לקביעות המועדים מימות הפסח. . א\"ת כו' ביום א' של פסח יהי' לעולם ט' באב\" (טושו\"ע או\"ח סתכ\"ח ס\"ג. הובא בסידור תורה אור (קה\"ת, תשמ\"ז) סט, ב). וראה פתיחתא לאיכ\"ר (יח) ובמפרשים שם השייכות דליל פסח וליל ת\"ב."]]],[1301550304,"אשר תוכנו בכל תוקפו גם בשנה זו, ואדרבא, בכל שנה ושנה הרי מקיימים הציווי להעלות בקודש<sup data-n=\"1807\">7</sup>, חמשה עשר מעלות<sup data-n=\"1808\">8</sup> מאז שנת ה'תשל\"ב.\nורמז מיוחד בשנה זו, בנוגע לתומ\"צ עליהם נאמר משמחי לב<sup data-n=\"1809\">9</sup> — שהיא שנת תשמח (בעצמן, וכל או\"א מבנ\"י שיכול להשפיע עליהם, האנשים והנשים והטף, כמרומז ג\"כ בפרט בשנה זו שהיא שנת הקהל<sup data-n=\"1810\">5</sup> את \"האנשים והנשים והטף<sup data-n=\"1811\">10</sup>\").\nוע\"פ ההוראה, שהיא גם נתינת-כח, המעשה הוא העיקר<sup data-n=\"1812\">11</sup>\nיה\"ר שיבוא כהנ\"ל במעשה בפועל ובהקדם ובזריזות<sup data-n=\"1813\">12</sup> המתאימים,\nועוד ועיקר — שתבוא בפועל ממש ובמהרה בימינו ממש גאולתנו האמיתית והשלימה,\nויקויים היעוד \"ולציון יאמר איש ואיש יולד בה והוא יכוננה עליון<sup data-n=\"1814\">13</sup>\"\nויהפכו ימים אלה<sup data-n=\"1815\">14</sup> \"להיות ימים טובים<sup data-n=\"1816\">16</sup> וימי ששון ושמחה<sup data-n=\"1817\">15</sup>\", בביאת משיח צדקנו.\nבברכה\n<hr>\nמאשר הנני קבלתי היום: ספר עץ חיים ג' חלקים, מבוא שערים ושער ההקדמות, אשר השגחה העליונה זיכתו והצליחתו להו\"ל, מתאים לגודל הכרח",[["1807","7","<b>הציווי להעלות בקדש</b>: ברכות כח, א. וש\"נ. זח\"ג קסב, ריש ע\"ב."],["1808","8","<b>חמשה עשר מעלות</b>: ראה מדות פ\"ב מ\"ה בסופה (\"כנגד ט\"ו מעלות שבתהלים\")."],["1809","9","<b>עליהם נאמר משמחי לב</b>: תהלים יט, ט. שו\"ע או\"ח בהל' ימים אלה (סתקנ\"ד ס\"א)."],["1810","5","<b>שנת הקהל</b>: ראה מכתב וא\"ו תשרי שנה זו (נדפס לקמן ע' 329), ובהערה שם ד\"ה זה."],["1811","10","<b>הקהל. . האנשים הנשים והטף</b>: וילך לא, יב."],["1812","11","<b>המעשה הוא העיקר</b>: אבות פ\"א מי\"ז. תקו\"ז תנ\"ב (פז, סע\"א). ת\"ס (צג, ב). ת\"ע (קלג, ב. קלד, א)."],["1813","12","<b>ובזריזות</b>: ראה אגה\"ק סכ\"א. — ולהעיר מענין שקדים המתוקים (מעשרות פ\"א מ\"ד. וראה לקו\"ש חל\"ג ע' 194 ואילך. וש\"נ)."],["1814","13","<b>ולציון. . עליון</b>: תהלים פז, ה."],["1815","14","<b>ויהפכו ימים אלה</b>: ע\"פ ירמי' לא, יב."],["1816","16","<b>ימים טובים</b>: כ\"ה ברמב\"ם דפוס רומי וכו' (מתאים לההמשך: וימי ששון), ולא כבדפוסים הרגילים \"יום טוב\"."],["1817","15","<b>להיות. . ושמחה</b>: רמב\"ם סוף הל' תעניות. וחותם (ומעתיק גם): והאמת והשלום אהבו."]]],[1301550305,"ודרישת השעה, לגלות זאת החכמה, וכדברי האריז\"ל החי הידועים, הובאו ומבוארים באגרת הקדש לרבנו הזקן, בעל ההילולא, ובקונטרס עץ החיים לכ\"ק אדמו\"ר (מוהרש\"ב) נ\"ע, אביו של כ\"ק מו\"ח אדמו\"ר,\nת\"ח ת\"ח על המשלוח, אשר בודאי גם מהמו\"ל ע\"י כת\"ר להבא ישלח לכאן ות\"ח מראש.\nאף שאתאפק לא אוכל מלהעיר על הפליאה והתמי' הכי גדולה, שאינו מובא ומוזכר כלל בהערות המו\"ל ספרי כ\"ק רבותינו נשיאי תורת חב\"ד, אף שבודאי ידוע שביארו בדבריהם כו\"כ מכתבי האריז\"ל [מקצתם עכ\"פ — צוינו ומובן מקומם ג\"כ ממפתח לתורה אור ולקוטי תורה של רבנו הזקן, ספר שערי אורה לבנו ומ\"מ כ\"ק אדמו\"ר האמצעי, ספר המצות לנכדו ומ\"מ חותנו כ\"ק אדמו\"ר הצמח צדק].\nואם בכלל ביארו חכמינו ז\"ל גודל הענין דאזנים לקופה, עאכו\"כ כשהמדובר בבאורים דתוכן הדברים. וביתר שאת — בנוגע לספרי קבלה, וע\"פ ציווי הבעש\"ט בזהירות מיוחדה בלימוד האמור (הובא בשרש מצות התפלה סו\"פ ב' לאדמו\"ר הצ\"צ, יעו\"ש).\nמובן שאין כוונתי לצעוק על העבר ועאכו\"כ לא בתור טענה, כי אם במקום שנוגע הענין לעתיד, שהרי — בהקדמת המו\"ל שמכינים לדפוס עוד מכתבי האריז\"ל.\nכן עלי עוד להוסיף, ובהמשך דענין אזנים לקופה, שמהנכון במאד למלאות ההערות ומראה מקומות לעוד כתבי האריז\"ל, ומפרשיו המקובלים, ככל האפשרי, ולכל לראש — לכלול בהם המצוין בהגהות וביאורים לעץ חיים, הוצאת ורשא תרנ\"א, ועד\"ז בכתבי האריז\"ל שנדפסו בירושלים עם הגהות הרמ\"מ הלפרין וכיו\"ב, וגודל הענין שבהשוואת הענינים בכתבי האריז\"ל, ממקום למקום, בודאי מובן וגם פשוט.\nוהרי ציונים ומראה מקומות לכתבי האריז\"ל (על יסוד מאמר חז\"ל דברי תורה וכו' ועשירים במקום אחר), בודאי רק תועלת וענין בהם (משא\"כ בביאורים ע\"ד עצמו).\nבודאי מתאים למכתבי מאז, משתדל כת\"ר גם בהפצת תורת הבעש\"ט בכל אופן האפשרי, בכתב בדפוס ובע\"פ, ויהי רצון מהשי\"ת שיראה פרי טוב בעמל זה, והרי תורת הבעש\"ט תלמידיו ותלמידי תלמידיו וכו' — היא עמלא דאורייתא אשר ע\"י דחילו ורחימו סלקא ובקעא רקיעין וקיימי קדם ה', וכמובא בספר תניא קדישא (פרק מ' ושם קונטרס אחרון בתחלתו).\nבכבוד ובברכה.\n<span data-k=\"q\">(ממכתב כ\"ד טבת תשכ\"ב)</span>\n<hr>"],[1301550306,"<h3>ואתחנן</h3>\nבעת רצון יזכירוהו על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע מתאים לתוכן כתבו,\nולכתבו אודות ענין השכחה, ידועה העצה בזה מתאים להוראת חכמנו ז\"ל, חיים הם למוצאיהם בפה, ללמוד בדבור, ומה טוב בחברותא באופן של שקו\"ט עם החבר, שכל זה מועיל לזכרון.\nועוד שיהי' בקי בעל פה המאמר ד\"ה והדרת פני זקן, דסוף פרשת קדושים בלקוטי תורה.\nוכן אשר יבדקו את התפילין שלו, ובכל יום חול קודם התפלה יפריש פרוטות אחדות לצדקה...\n<span data-k=\"q\">(ממכתב כ\"ו אד\"ר תשכ\"ב)</span>\n<hr>\n... מרז\"ל תוקפא דגופא חולשא דנשמתא (דנפשא) — ראה זח\"א קפ:, קמ:. הגירסא דנפשא — מפרטת יותר שמצב הגוף נוגע במדרי' הנשמה הסמוכה אליו דוקא והיא הנק' נפשא, כידוע.\n<span data-k=\"q\">(ממכתב שלהי אלול תיש\"א)</span>\n<hr>\n... לההערה בסוף אגה\"ק לאדה\"ז ד\"ה הוכח תוכיח<sup data-n=\"1818\">*</sup> — הרי כמו שרמוז חיצונית",[["1818","*","ז\"ל השואל: אדמוה\"ז לא בא לחדש או גם לבאר הלכות שבת ומקורותיהן, כי אם להדגיש גודל העון של שיחה בטלה בש\"ק, ולזה ביאר מה שידוע ליו\"ח כי בכל המצוות יש פנימיות וחיצוניות וגם בשבת כן. וא\"כ לכאורה הי' די להזכיר חיצונית מהשבת (בבחי' שמור) כמו ששבת וכו', ופנימיות של בחי' שמור כמו ששבת וגו'. ואעפ\"כ נראה מדבריו הקדושים והמאירים שרצה גם כן להזכיר בחי' זכור וא\"כ למה לא התחיל בחיצוניות כמו שנאמר ויקדש אותו ויברך וגו' ואח\"כ הפנימית כמ\"ש שבת לה\"א וגו'. ולפיכך אמרתי בדרך השערה בעלמא, שאדמוה\"ז כלל בחכמתו את החיצוניות דזכור בפנימית דזכור, באמרו: \"הכוונה בתפלת השבת\", משא\"כ בשמור אין השביתה מעשי' גשמיית כלולה בשביתה מדיבורים גשמיים. המו\"ל."]]],[1301550307,"דזכור בפנימיותו בתיבות \"הכוונה בתפלת השבת\", כמו\"כ ממש מקום לרמוז חיצוניות דשמור בפנימיותו ע\"י שינוי קל מלשונו הק', והוא: \"השביתה מדיבורים בעשיות גשמיים\", ולא עוד אלא, שכנראה, גם בלא שינוי הנ\"ל, זוהי הכוונה, כי מה פי' אחר לענין \"דיבורים גשמיים\"? וגם ההמשך \"כמו ששבת כו'\" מוכיח כן.\n<span data-k=\"q\">(ממכתב שלהי חנוכה תשכ\"ב)</span>\n<hr>\n... לכתבו ע\"ד סדר בלימודים: הרי אמחז\"ל במקום שלבו חפץ. הצד השווה בכאו\"א: מס' בחלוקת הש\"ס (למיגרס) עוד מס' או פוסקים — לעיונא. פ' השבוע וכיו\"ב — בס' תו\"א ולקו\"ת (למיגרס), עוד לימוד בחסידות — לעיונא. הלימודים למיגרס בכל יום. לעיונא — לכה\"פ שלא יעברו ג' ימים בלא לימוד זה. ועייג\"כ שיחת חי אלול ה'תשכ\"ב<sup data-n=\"1819\">*</sup>.\n<span data-k=\"q\">(ממכתב כה שבט תשכ\"ג)</span>\n<hr>\n... ולכתבו אודות לימוד חק לישראל, אשר מפני קוצר זמן אינו יכול ללמוד כל השיעור בחק לישראל, ושואל האם יותר טוב ללמוד חלק מזה בעיון או כולו בלא עיון.\nוהנה אע\"פ שבתורה שבעל פה צריך להיות הלימוד בהבנה וכפסק דין הידוע (שו\"ע או\"ח במג\"א סי' נו\"ן, ומבואר בלקוטי תורה לרבנו הזקן, בהביאור דלא תשבית)",[["1819","*","נדפסה בלקו\"ש ח\"ט ע' 343 ואילך. המו\"ל."]]],[1301550308,"הנה כיון שלומד שיעורים האמורים זה שמונה שנים, בודאי שאין לבטלם ח\"ו, אלא שמוכרח שימצא זמן לאחרי שילמוד השיעור באופן דעד עתה, ללמוד עכ\"פ משנה אחת וכן עד\"ז בשאר השיעורים מאלו שבתורה שבעל פה בהבנה, והשי\"ת יצליחו.\nנעם לי לקרות בסיום מכתבו שלומד השיעורים דחומש תהלים ותניא, וע\"פ מאמר חז\"ל מצוה גוררת מצוה, ירבה זה הצלחה גם בזמן ולהרבות בלימוד התורה וקיום המצות בהידור.\n<span data-k=\"q\">(ממכתב כ\"ה סיון תשכ\"א)</span>\n<hr>\nבמענה למכתבה ממוצש\"ק, בו כותבת אודות הקישוים שפגשה בלמדה \"תוכן הענינים\" המדוברים בשיחות שבת קדש, שמבינה הענין בכללותו אבל לא תמיד לפרטיו.\nובכלל בשיחות האמורות, ישנן כמה חלקים, כיון שהבאים ללימוד זה גם כן שייכים לסוגים שונים בהבנת התורה, אבל בכל אחת מהן — כל סוג יכול למצוא ענין שהבנתו מתאימה לידיעותיו נוסף על הבנת כללות הענין, ובטח גם בנוגע אלי' כן הוא, וכשתתקדם בלימוד התורה בודאי תבין עוד חלק ועוד חלק וכו'. ואין ענין ללמוד ספרים בכדי להבין אלו השיחות, כי לא זו הדרך, כי אם להתקדם בלימוד והבנת התורה צעד אחר צעד, ובנקודה העיקרית — שתתאים להוראת רבנו הזקן בהלכות תלמוד תורה סוף פרק ראשון, בנוגע ללימוד התורה של נשים שהשתדלות בהעיקר — שיהי' הלימוד מביא לידי מעשה, חדור יראת השם ואהבת השם (כמובן ג\"כ בהלכות ת\"ת הנ\"ל).\n<span data-k=\"q\">(ממכתב כ' אד\"ש תשכ\"ה)</span>\n<hr>\nמאשר הנני קבלת ספרו נצוצי אור, הארות והערות וכו' שנמסר לי ימים אלו וכן פ\"ש מהאורחים דאה\"ק ת\"ו, אשר בקשתים גם להחזיר ד\"ש לכת\"ר שי'.\nת\"ח על שימת לבבו לשלוח לי ספרו האמור וכן לפני זמן ספריו המקרא והמסורה וכו' ובודאי גם להבא יעשה כן, ות\"ח למפרע."],[1301550309,"ויהי רצון אשר רבות בשנים ירבה חילו לאורייתא, ולזכות ולהצליח להו\"ל תורתו, ובפרט אשר חלק חשוב מהם הם מראי מקומות וציונים ועיונים, המבליטים את האחדות אשר בתורתנו הק' תורה אחת, וכיון שניתנו מיחידו של עולם, בודאי גם למעלה מזה, תורה יחידה.\nבכבוד ובברכה לבשו\"ט בכל האמור.\nנ.ב.\nימים אלו נוסע לביקור באה\"ק ת\"ו אחד מהמדפיסים המפורסמים האחים שולזינגר שי' שזכו והצליחו להו\"ל תורת ראשונים ואחרונים בהדר ויופי חיצוני וגם פנימי, מתחיל מחמשה חומשי תורה ש\"ס בבלי וכו' וכו', הם הן גם המדפיסים שהו\"ל ספר לקוטי תורה לאדמו\"ר הזקן נוסף על כמה ספרי חסידות שהדפסנו על ידם.\nוכיון שרכש לבם דבר טוב להו\"ל ש\"ס ירושלמי ביחד עם ש\"ס בבלי עם כל פירושיהם וכו' הצעתי להנ\"ל לבקר את כת\"ר ולקבל חוו\"ד אודות תכנית הוצאת הש\"ס וש\"ס (חגיגה יו\"ד ע\"א) ביחד, והרי זה ענין הנוגע לרבים ולזכות הרבים.\nמענין לענין באותו ענין, תמיהני על אשר בשערי זהר דכת\"ר לא הכניס גם ציונים מש\"ס ירושלמי, ובאם אפשרי בודאי כדאי להו\"ל בגליון בפ\"ע, ובמשך הזמן לצרפם להוצאה שני' דספר זה.\nכיון שתכנית הנ\"ל לשהות באה\"ק רק ימים ספורים, נשלח המכתב מהיר דחוף.\nבריש ס' ניצוצי אור. שנק' התנאים כו' פרושים — ע\"ש שענינם לפרש התורה. לכאורה לפ\"ז צ\"ל שמם פירושים (ביו\"ד) או עכ\"פ בניקוד שונה מהרגיל בפי כל. וכנראה בכ\"מ — כן נקדו תיבה זו עוד בדורות קדמונים. ואף ש\"השמות אינם נשמרים כמו הפעלים\" (הראב\"ע שמות ב, י) — בכ\"ז צ\"ל באותו הענין.\nבסופו: בנוסח הקדיש (דסיום מס') ולאחיא כו' ולמיבני כו' ולמיעקר כו' — צ\"ע שהענינים בו באים שלא ע\"ס הזמן, ראה ברכות מט, א. זח\"א ס\"פ ח\"ש, וקל\"ט, א. רמב\"ם [הל'] מלכים ספי\"א. מכ' כ\"ק אדנ\"ע (נדפס בקובץ מכ' שלו<sup data-n=\"1820\">*</sup>). ובכ\"מ שציין כת\"ר בניצוצי זוהר שלו ברכות שם. ז\"ע ראיתי שציין כ' בזהר שם מס' כתם פז.\n<span data-k=\"q\">(ממכתב ז' מ\"ח תשכ\"ו)</span>\n<hr>",[["1820","*","אג\"ק ח\"א אגרת קכט. המו\"ל."]]],[1301550310,"במענה לשאלתו — לרגש ביוקר התורה מגיעים ע\"י התבוננות בדברי חז\"ל המבארים ענינה ומעלתה. ועייג\"כ תניא פרק ד' ה' כ\"ג ובכ\"מ. ב\"ח לטור או\"ח סמ\"ז.\n<span data-k=\"q\">(ממכתב כ\"ט מ\"ח תשכ\"ב)</span>\n<hr>\nמאשר הנני קבלת מכתבו מכ\"ד מרחשון, בו כותב ע\"ד המצב בהישיבה.\nואף שמבואר בכ\"מ ובדא\"ח שלא הכמות הוא העיקר, ואחד הי' אברהם וירש זרעו את הארץ, אבל ביחד עם זה מבואר בכ\"מ גם מאמר חז\"ל הידוע אלף נכנסים למקרא וכו' אחד יוצא להוראה, שנקודת הביאור, שכמות של אלף כניסה למקרא נוגע בשביל שיהי' אחד להוראה, ובהדגשה יותר יובן ע\"פ המבואר (בלקו\"ת לג' פרשיות ג' ע\"א<sup data-n=\"1821\">*</sup>) שהאלף הוא בעולם העשי' ובזה תלוי האחד להוראה בעולם האצילות, עיי\"ש דברים נפלאים בזה.\nומובן שלא לדרשה קאתינא, כ\"א ע\"ד כמות התלמידים בהישיבה שמבהילה היא. ומה שנוגע לא פחות מזה, שבמשך שנים האחרונות הולכים ופוחתים. . הגיעו לכאן ידיעות, שבכו\"כ חוגים מאחב\"י בצרפת וביחוד בפאריז, מתכוננים בשטח החינוך לקראת עליית היהודים מאלג'יר לצרפת שהתחילה מכבר והולכת וגדלה מזמן לזמן, ובמכתבו אין ניכר כל הד לידיעה האמורה ולפעולות בהאמור...\nלכתבו אודות תלמידים מכאן — מובן שלכל לראש עליו לפנות להנהלת הישיבה דכאן, ולבארם ג\"כ איך זה אפשר לסדר באמצע זמן הלימודים הן כאן והן בצרפת [. . . ] ועוד ועיקר איך זה יועיל הנ\"ל, התלמידים דכאן המדברים אידיש או אנגלית בנוגע לאחב\"י מאלזשיר וכיו\"ב שצריכים לדבר עמהם בצרפתית או עכ\"פ בלה\"ק.\nוכיון שעומדים אנו בערב חדש כסלו, חדש הנסים, יהי רצון שיחול נס בכל הענינים הנ\"ל, ויהי' מוסיף והולך מוסיף ואור בריבוי תלמידים זרע ברך ה' לומדים נגלה וחסידות.\n<span data-k=\"q\">(ממכתב כ\"ז מ\"ח תשכ\"ב)</span>\n<hr>",[["1821","*","אוה\"ת בראשית כרך ו' תתרכו, ב ואילך. המו\"ל."]]],[1301550311,"... והנה ידוע דרך הקדושה שהוא לאט לאט, ובמילא, צריך הי' למצוא דרכים המתאימים לקרב את המיול\"ח לתורת החסידות דרכי' והנהגותי'. ובפרט ע\"פ מרז\"ל דחתנו כבנו, וידוע שמצות חינוך בבן היא מוטלת על האב, ובפרט מצות חינוך דתלמוד תורה שהוא מדאורייתא על האב, וכפסק רבינו ז\"ל בהלכות ת\"ת בתחלתו ובכמה מקומות. ופשוט אשר לימוד תורת החסידות הוא בכלל זה.\n<span data-k=\"q\">(ממכתב י\"ב אדר תשי\"ג)</span>\n<hr>\nבמענה למכתבו מכ\"ו סיון, בו שואל ע\"ד בן אחיו שי' הרוצה ללמוד שנים אחדות בישיבה, והשאלה אם יכנס אחרי כן בקבוץ דתי וכו'.\nולדעתי כיון שהענין נוגע לאחרי שילמוד משך זמן בישיבה, לימוד תורתנו הק' תורת חיים, אשר כדברי רבנו הזקן בספר תניא קדישא שלו, שהתורה נקראת בשם לחם ומזון הנפש, וע\"י הלימוד כדבעי, מתאחדת עם נפש הלומד והיו לאחדים, ונעשה מזון לנפש וחיים בקרבה מחיי החיים אין סוף ברוך הוא וכו' (תניא פרק ה'),\nהרי עפי\"ז אין כדאי להחליט עתה מה שיעשה לאחרי לימוד האמור, שהרי התקוה ע\"פ האמור שיתעלה ע\"י לימוד זה, ויחליט בהתאם למצבו אז.\nהתקוה חזקה אשר ידוע לכ' פרשת ימי י\"ב וי\"ג תמוז גאולת כ\"ק מו\"ח אדמו\"ר נשיא דורנו.\nויהי רצון שיתעורר ויוסיף כאו\"א בעניני תורה ומצות ובהפצת היהדות ועניני' לקרוב ולרחוק ומתוך שמחה וטוב לבב.\n<span data-k=\"q\">(ממכתב כ\"ח סיון תשכ\"ד)</span>\n<hr>\nבתמהון גדול קראתי מכתבו מעש\"ק תצוה, בו כותב אודות נכדו הנעלה האברך ירא שמים ות\"ח. . אשר מתבטא שאין לו נחת ממנו (ח\"ו) כבריאות גופו וכו'.\nותיכף שאלתי וחקרתי להנעשה את נכדו שי' ומסרו לי עוד הפעם ע\"ד הצלחתו בלימוד התורה, לימוד המביא לידי מעשה, כמובן וגם פשוט, ובהנוגע לבריאותו, אשר — הרופא מצא שהכל אתו בסדר, אלא שכנראה טבע נפשו, שתובע מעצמו תמיד"],[1301550312,"בנוגע למצבו ברוחניות ובמילא פועל על הבריאות וכו', מובן וגם פשוט אשר נסיעה וטלטול ממקום למקום, לא ישנה בזה מאומה, והלואי שלא יזיק, שהרי הורונו חז\"ל, לעולם ילמוד אדם במקום שלבו חפץ, ומי יודע איך יסתגל במקום החדש.\nולהמשך מכתבו אשר במקום חדש ילמוד ג\"כ איזה אומנות, כי טוב תורה עם דרך ארץ, הרי במכתבו זה עצמו, הקדים תורה לדרך ארץ, ובודאי ובודאי שעדיין לא הגיע זמן נכדו שי' לגזול מהשעות אשר מקדיש הוא להתמדה ושקידה בלימוד תורתנו תורת חיים, חיים גם כפשוטם בעולם הזה הגשמי, ולהתבלבל בחשבונות רבים מחשבות בני אדם ותחבולותיהם היפך מזה שהאלקים עשה את האדם ישר.\nיודע הנני אשר אויר מדינה זו גורם למחשבות בנוגע לתכלית, בגיל הרך של הבנים והבנות, אבל כל המביט בעינים גלויות על הנעשה סביבו, רואה על כל צעד ושעל, שברובא מסתדרים בפרנסה דוקא לא בזו האומנות שלמד בעודו רך.\nשולח הנני העתק מכתבי גם לבנו הרב שי' כיון שאיני יודע ממי באו סברות הכתובות במכתב כ' (אף שלכאורה הרי הן בהיפך מפעולות בנו הרב שי' לילך נגד הזרם דארצוה\"ב, פעולות במרץ ומבלי התחשב עם דעת הרבים וכו' וכו').\nויהי רצון אשר נוסף על הנחת רוח שיש לו עתה מנכדו שי' והלואי ועוד יותר מכל יו\"ח שי' נחת אמיתי, יוסיף השם כהנה וכהנה ע\"י הצלחה מופלגה של נכדו בלימוד התורה בנגלה ובחסידות, מבלי הפרעות ענינים מבחוץ, ובודאי כשיוכל ללמוד במנוחה, יקוים בו אשריך בעוה\"ז וטוב לך וכו'.\nבכבוד ובברכה לבשו\"ט.\nנ.ב. וכיון שהכל בהשגחה פרטית, עלי החובה (והזכות) לעוררו על ההכרח לקבוע עתים בלימוד פנימיות התורה, שבדורנו נתגלתה בתורת החסידות, קביעות בכל יום ובהוספה ביום השבת, כמבואר בכתבי האריז\"ל החי.\n<span data-k=\"q\">(ממכתב י\"ז אד\"ר תשכ\"ה)</span>\n... וכל<sup data-n=\"1822\">*</sup> העושים זאת — גוזלים מאת התלמידים כמה וכמה שעות מלימודי קודש שלהם. ועי\"ז מחסר גם את ידיעותיהם בקיום המצות בפועל וביר\"ש, ומכשילים אותם עי\"ז בענינים דרבנן וגם דאורייתא. ור\"ל.\n<span data-k=\"q\">(ממכתב כ\"ו סיון תשט\"ז)</span>\n<hr>",[["1822","*","מענה לא' ע\"ד לימוד עברית בבי\"ס. המו\"ל."]]],[1301550313,"ע\"פ כתבו שבלימוד בישיבה לא הצליח בנו שי' — מובן שכדאי שילמוד מקצוע (מלאכה) ומה טוב בביסל\"מ — שבו לומדים תורה [לימוד בבי\"ס עממי — מובן שאין זה ענין כלל, כיון ששם מעורבים עם נכרים וכו', נוסף — על התערובת דנערים ונערות]. באם נמצא כהנ\"ל ועכ\"פ בנ.י. — טוב יותר מאשר בריחוק מקום גדול — כדי שיראוהו לעתים קרובות ויוכלו לייעצו איך להסתגל בקל יותר וכיו\"ב.\nבאם אין נמצא — אזי באהקת\"ו. ויבררו אצל. . שי' — האם התכנית בכחב\"ד לפי כחו (שלומדים גם חסידות) או בביסל\"מ דתי אחר באה\"ק...\n<span data-k=\"q\">(ממכתב סיון תשכ\"ו)</span>\n<hr>\nבודאי מובן (ורגיל) אשר הנוער צמא למצוא ודבר חדש וכו' — ולא עוד אלא שיש לזה יסוד בציווי חז\"ל לעשות \"כמאן דבעי למיעבד\", היינו לנצל הכוחות שניתנו לו במילואן,\nלאידך גיסא מובן ג\"כ ופשוט שאינו ענין כלל לחפש טרם שיזדיין בנשק שיוכל להתגבר עליו ולתקנו (עכ\"פ שידע שיש סיכויים טובים לזה) — ולא שינוצח על ידו (שאז תיתוסף קלקול בעולם ואצלו וכו'), ובנוסח חז\"ל שאסור לאדם לעמוד במקום סכנה ועוד יותר — כבתפלה שאומרים אותה קודם להתפלה \"אל תביאני לידי נסיון\".\nבנוגע ליהודים ובפרט בתקופתנו — זו שמזכירה לעיל וקאלידזש בכלל — ה\"ז בדוגמא לאדם בריא האומר שכל ימיו חי בתנאים בריאים והי' בריא וראה רק בנ\"א בריאים ובמילא אינו מנצל הכחות שלו כלל, ומהי תכלית חיי? ולכן קס\"ד שיעתיק דירתו למקום מחלות — מתדבקות — שיש בהן סכנה, ולאחרי זה ינסה אולי מסוגל הוא להתחיל ללמוד חכמת הרפואה במקום זה וכו'. והנמשל מובן.\nישנו מוכן בשביל בנות מבנ\"י הדומות לה, אשר מוכרח להתגבר עליו, הוא: החסרונות שמזכירה בנוגע לאוירת הסעמענארים (— וביה\"ס בכלל) אפשרי לתקנן, אבל רק ע\"י אלו שהרגישו בעצמן ופגע בהן החסרון — אלא שככל הישג טוב דרושה לזה הכנת עצמו — עד כדי יגיעה בזה, כוונתי: לרכוש ידיעות מספיקות במקצעות הנלמדים בהסמינארים, מומחיות בפדגוגיא, החלטה תקיפה לא להתרשם באם לא יראו הפירות תומ\"י ולא ליבוש מפני המלעיגים — ולאחרי זה להתחיל לשנות האוירה וכו' ובהתלהבות ובמסנ\"פ. ובודאי שהשי\"ת יצליח.\n<span data-k=\"q\">(ממכתב שנת תשל\"ב)</span>"],[1301550314,"במענה למכתבו מעש\"ק שהגיעני באיחור זמן, ולתוכן הענין נענה שלא בתור ובמהיר דחוף.\nבו כותב אודות מקום המשך לימודו של בנו שי'.\nוהנה בודאי לדכוותי' למותר להדגיש אשר כיון שישנו פס\"ד תורתנו בזה, הרי אין מקום לספיקות, ומפורשת ההוראה, לעולם ילמוד אדם במקום שלבו חפץ, וגדולה הפלגת חז\"ל בהוראה האמורה, עד שנפסק הדין להלכה למעשה, בשו\"ע יו\"ד הלכות כבוד אב ואם סוף סי' ר\"ם, שאפילו אם האב מוחה בו, ואפילו אם המחאה מפני סכנת נפשות, בכ\"ז ילמוד דוקא במקום שלבו חפץ. עיי\"ש.\nפשוט גם כן, שכיון שזוהי הוראת תורתנו תורת חיים, בודאי שזוהי הטובה, לא רק של התלמיד אלא גם של ההורים שלו, ופשוט ג\"כ כיון שהמדובר בחפץ הלב, מובן ורואים במוחש, שאין שייך בזה לגזור על התלמיד הבן, שיחפוץ במקום אחר, כי גזירה שייכת למעשה בפועל, אבל לא בנוגע לחפץ הלב והרגשו.\nוהנה כל הנ\"ל הוא, אפילו באם היתה השאלה לפני כמה זמן, אבל בנדון דידן שכבר נמצא הבן כמה חדשים. . ורואים המצב בבית וכו' וכו' נראה במוחש, שטובת ובריאות ההורים וכן טובת ובריאות הבן הוא, שבהקדם יסע ללמוד בעיר אחרת, וע\"פ פס\"ד האמור שבשו\"ע, הרי צריך לנסוע למקום שלבו חפץ, ובפרט שכבר נסע למקומות אחרים. . ולאחר כל זה לבו חפץ במקום מסוים.\nוהנה פשיטא ג\"כ שלטובת כל המעונינים בדבר, הוא שיעשה כל האמור בדרכי נועם ומתוך קירוב הלבבות, שבכלל הרי גדול השלום וקירוב הלבבות, ובפרט כבית כשלהם, המיוסד על התורה ומצותי' אשר דרכי' דרכי נועם וכל נתיבותי' שלום.\nובכגון זה יש לדרוש מההורים יותר מאשר מהבן, שהרי הורים מבוגרים יותר, יש להם נסיון רב יותר בדרכי החיים והיחסים שבבית וכו' וכו'.\nועוד וגם זה עיקר, שהבן נמצא בתקופת הבגרות, ז.א. שע\"פ טבע העצבים (ניערווען) שלו מתוחים יותר, ולא כל אדם זוכה שהמוח יהי' שליט על הלב, להשקיט העצבים לגמרי וכו' וככל שמבוגר האדם יותר, המוח שליט על הלב יותר.\nפשוט שאין רצוני להפחיד ח\"ו וכו' אבל מוכרחני להדגיש עוד הפעם, שבכל הזמנים ועאכו\"כ בתקופתנו זו, צריך לשמור ולהזהר ביותר בכל שנוגע בניערווען הדור הצעיר, הבנים והבנות, בהתבונן ל\"ע ול\"ע בהנעשה בתוככי הנוער, בנוגע לבריאות בכלל, ובהקשור עם הנערווין בפרט, ולכן ההקדם בכל האמור, ישובח, ובהדגשה עוה\"פ שזוהי הטובה של כל הפרטים ושל כל הצדדים, שהוא וכן זוגתו תחי' יעודדו את בנם שי' לנסיעתו למקום שלבו חפץ, ויעשו בזה כנ\"ל בהקדם וכו', ובודאי לדכוותייהו האריכות בהאמור אך למותר.\nמובן שקראתי בשימת לב הדרושה, כתבו בנוגע לתכלית ולהסתדרות בחיים, ובהסיכוים לשנות ההנהגה וכו', אבל כאמור לעיל, הרי זה ענין שאינו תלוי כ\"כ בשקו\"ט שכלים, כ\"א כהוראת חז\"ל, בחפץ לב, נוסף על זה בנדון דידן, מתיחות"],[1301550315,"הניערווין, היחסים שהולכים ומחריפים וכו', שזה דורש לטובת זוגתו תחי' ולטובת בנם שי', שבהקדם ישתנו היחסים לאופן של קירוב ועד לנסיעתו ללמוד למקום שלבו חפץ.\nמסיים במכתבו, שלדעתו הנה התערב בזה אדם שלישי, הנה לאחרי בקשת סליחתו, איני יודע מה היתה סיבה הראשונה, אבל לאחרי השיחה כ\"פ עם בנו שי' ולאחרי השיחה עם כת\"ר וזוגתו תחי' כשביקרו כאן, המצב עתה הוא באופן המתואר לעיל, ז.א. שחל ע\"ז פס\"ד והוראת תורתנו תורת חיים במילואה, כי לעת עתה, אפילו בנו שי' לא יוכל לשנות, חפץ לבו, באם ירצה אפילו באמת.\n[בכתבי לעת עתה, כוונתי שנה ושנתים עכ\"פ].\nותקותי חזקה אשר כת\"ר וזוגתו תחי' ישאו לבם להכתוב לעיל בנוגע להוראת חז\"ל בהאמור, ובמילא יבואו למסקנות האמורות.\n<span data-k=\"q\">(ממכתב י\"ט מ\"ח תשכ\"ו)</span>\n<hr>\nב) במ\"ש<sup data-n=\"1823\">*</sup> אודות תמונת האותיות שכתב לי. . הנה מכתבו נתקבל, וכפי שרואה אני ממכתב כת\"ר שי', הרי, כנראה, שאין להנ\"ל קבלה איש מפי איש, אלא רק שמדייק בתמונת הפרשיות שראה. ולכאורה, בענינים כמו אלו צריך לשמוע איש מפי איש — מה בדוקא ומה בא בהזדמן, אבל אינו בדוקא. וכדאי לחפש אם ימצאו כאלה...\n<span data-k=\"q\">(ממכתב כ\"ט טבת תשי\"ד)</span>\n<hr>\n... מלשון<sup data-n=\"1824\">*</sup> אדה\"ז בסידורו שלא לבטל כו' מוכח דחיוב הוא.\n<span data-k=\"q\">(ממכתב ה' סיון תשי\"ז)</span>\n<hr>",[["1823","*","ראה גם לקו\"ש חכ\"ט ע' 383. המו\"ל."],["1824","*","מענה לשאלה במ\"ש אדה\"ז גבי הפסק בין תש\"י לתש\"ר ש\"לא לבטל מעניית דבר שבקדושה\", אם רק מותר להפסיק או שצריך להפסיק. המו\"ל."]]],[1301550316,"... ולכתבו אודות תפילין בבתים ריקים בקשר עם חוה\"מ, האריך בזה בספר אות חיים ושלום להרה\"צ הרה\"ג כו' ממונקאטש סי' ל\"ח סק\"א ואין הענין פשוט כלל וכלל אפילו לאלו המצדדים לזה. וכמה ששוללים הענין מטעמים חזקים<sup data-n=\"1825\">*</sup>...\n<span data-k=\"q\">(ממכתב י\"ג אלול תשכ\"א)</span>\n<hr>\n... לכתבו ע\"ד המאורע בהנחת תפלין — יש להעשות בקי בהעניני דרושי דא\"ח בענין תפלין: ד\"ה שימני כחותם וביאורו (לקו\"ת שה\"ש) בשער התפלין שבסי', ומצות תפלין בס' דרך מצותיך.\n<span data-k=\"q\">(ממכתב ד' אייר תשכ\"ג)</span>\n<hr>\n... בנוגע פאַרפעלען אַ טאָג לייגין רבנו תם תפילין, דאַרפמען זעהען אַז מען זאָל האָבן אין קאָפּ עטליכע פרקים תניא און בלי נדר זעהען אַז עס זאָל ניט אַדורך אַ טאָג, אין וועלכען די פרקים זאָלן ניט געזאָגט ווערען אָדער איבערגעטראַכט ווערען לפחות איינער פון זיי אין פאַרלויף פון דער מעת לעת, בל\"נ...\n<span data-k=\"q\">(ממכתב כ\"ז מ\"ח תשט\"ו)</span>\n<hr>\n... ע\"פ המבואר בכתהאריז\"ל (בימינו אלה) כל בנ\"י צ\"ל תפלין דר\"ת. וכן נוהגים כל השייכים לחב\"ד וכל הנלוים אליהם מכו\"כ שנים.\n<span data-k=\"q\">(ממכתב ט\"ז אד\"ש תשמ\"ו)</span>\n<hr>",[["1825","*","מהם בס' אדרת אלי' (לבעהמ\"ס משנת חסידים) אוסר בפשיטות. בשו\"ת חתן סופר (סקכ\"ז) כותב \"יש בזה חששות וכמו שכבר נשמע מגדול א' שהרעישו עליו\". דרך אגב — מזה מוכח שלא עשה כן החתם סופר, ודלא כמו שאמר לו פ'. ובס' מאסף לכל המחנות קיבץ להקת פוסקים שאין באי הנחת תפלין לא תתגודדו. ועד\"ז פס\"ד הצ\"צ בפס\"ד שלו או\"ח סרל\"ו."]]],[1301550317,"... בשאלתו בענין תפילין דר\"ת<sup data-n=\"1826\">*</sup>, הנה לע\"ע לדעתי עדיין לא יניחם, ובעוד איזה זמן בטח יבוא עמדי בכתובים עוד הפעם אודות זה, ועד אז הנה יוסיף אומץ בלימוד תורת הדא\"ח שע\"פ המבואר בכ\"מ הנה זה מהשייך לתפילין דר\"ת שע\"פ המבואר בספרי קבלה, זהו ענין מוחין דאבא.\nבטח נותן לצדקה בכל יום מימות החול איזה פרוטות קודם התפלה ושומר שלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר בחומש תהלים ותניא הידועים ופשיטא אשר נזהר בטבילת עזרא, והשי\"ת יזכהו לתלמוד תורה ביראת שמים ומבלי מפריעים ומונעים המדומיים שאינם באים אלא להגדיל את השכר והחביבות של הענין...\n<span data-k=\"q\">(ממכתב י\"ג ניסן תשי\"ג)</span>\n<hr>\n... בנוגע לשאלתו אודות הנחת תפילין ר\"ת, הנה תלוי זה בכמות ואיכות ידיעותיו בתורת הדא\"ח, ויבקש את המשפיע שלו שיכתוב לי עד\"ז, ובטח נזהר הוא ג\"כ בטבילת עזרא.\n<span data-k=\"q\">(ממכתב כ\"ד מנ\"א תשי\"ג)</span>\n<hr>\nבמענה על מכתבו בו מודיע יום הולדת שלו ושואל אם להתחיל להניח תפילין דר\"ת.\nהנה אם נזהר בטבילת עזרא ולומד בכל יום דא\"ח (מובן אשר הכוונה בזה הוא בלי נדר ובקביעות ובמילא אם מאיזה סיבה ואונס לא עשה פעם כנ\"ל או שהי' אונס שכחה לא לזה כוונתי) אזי איזה ימים לפני יום הולדת יתחיל להתרגל בהנחת תפילין ר\"ת ומיום ההולדת ואילך יתחיל להניחם בקביעות.",[["1826","*","ראה מכ' שלפנ\"ז. ובס' השיחות תשמ\"ט ע' 632 הערה 114: בדורנו זה פשט המנהג (ובפרט מנהג חב\"ד) שמתחילים להניח תפילין דר\"ת באותו זמן שמתחילים להניח תפילין דרש\"י (כולל גם בנוגע לזמן ההכנה שלפני בר-מצוה) — ראה לקו\"ש ח\"ב ע' 507 ובהערה 39, ונתבאר בארוכה בשיחת פורים תשל\"ו. המו\"ל."]]],[1301550318,"והשי\"ת יזכהו להצליח בלימוד תורת הנגלה ותורת החסידות (וידוע אשר תפילין [ד]ר\"ת הם מוחין דאבא השייכים יותר ללימוד פנימיות התורה) וישפיע ג\"כ על זולתו לקרבו לנר מצוה ותורה אור ומאור שבתורה מתוך אהבת ישראל.\n<span data-k=\"q\">(ממכתב א' כסלו, תשי\"ד)</span>\n<hr>\n... בשאלתו אודות הנחת תפילין דר\"ת — הנה בודאי נזהר בטבילת עזרא וכן לומד פנימיות התורה, בלי נדר, ולכן יתחיל בהנחתן ובודאי ילמוד ויחזור על דרושי התפילין אשר בכמה מספרי דא\"ח (לקו\"ת שה\"ש, אמרי בינה, דרך מצותיך וכו') והשי\"ת יצליחו...\n(ממכתב ה' אלול תשי\"ז)\n<hr>\n... ער שרייבט מיר אויך וועגן דעם געשפּרעך בנוגע תפלין.\nאיך הייל מיך אויסדריקן שריפטליך מיין שטאַרקע האָפנונג, אַז תפלין, דער אות (צייכן) וואָס דער אויבערשטער גיט יעדער אידן און בעט כביכול, יעדער אידן עם אָנטאָן יעדער וואָכן טאָג — וועט ניט נאָר פּונקטליך ערפילט ווערן דעם אויבערשטען'ס מצוה — בקשה נאָר עס וועט אויך געטאָן ווערן בשמחה. ובפרט אַז ווי חכמינו ז\"ל ווייזען אונז אָן, אַז \"הוקשה כל התורה כולה לתפלין\", תפלין זיינען אַ אָנדייטונג אויף אַלע מצות פון דער תורה: די תפלין של יד — וואָס מ'לייגט אויף דער האַנד — געגען האַרצען, דייטען אָן, אויף דעם האַרץ געפיל, און די תפלין של ראש — וואָס מ'טוט אָן אויפן קאָפּ — דייטען אָן אויף דעם שכל וואָס איז אין מוח, און אַז דער געפיל פון האַרץ און שכל-פאַרשטאַנד פון מוח זיינען איבערגעגעבען צו הקדוש ברוך הוא איז לויט זייערע אָנווייזונגען פירען זיך אויף אויך אַלע אַנדערע אברים, אין איינקלאַנג מיט דעם ווילען פון השם יתברך, ווי אָנגעוויזען אין דער הייליקער תורה, תורת חיים.\nאון די ברכה פון השם יתברך וויל מען דאָך געוויס יעדער טאָג אָן אויסנאַם, אַזוי אויך דאַרף זיין דאָס לייגען תפלין יעדער וואָכען טאָג, אָן אויסנאַם,\n(און שבת און יום טוב, זאָגט דער אויבערשטער בתורתו — אַז די קדושה פון די טעג, פאַרבייט דעם ענין פון תפלין)."],[1301550319,"פאַרשטענדליך אַז איך וועל זיין זייער צופרידען צו באַקומען אַ גוטע בשורה אין דאָס אַלץ אויבען געזאָגטע.\nספּעציעל ווען מיר דערנעהנטערן זיך צו די סגולה טעג פון י\"ב וי\"ג תמוז, באַפרייאונגס טעג פון מיין שווער כ\"ק אדמו\"ר, וועלכער האָט זיך מוסר נפש געווען צו פאַרשפּרייטן אידישקייט תורה ומצות, און מ'האָט געזעהען בעשיינפערליך, ווי אַזוי אַז מ'וויל אויף אַ אמת, באַזיגט מען אַלע שוועריקייטען און מען איז מצליח.\n<span data-k=\"q\">(ממכתב ד' תמוז תשכ\"ג)</span>\n<hr>\nלכתבו אודות הנוער שהאם אינה יהודי' — הנה הדין ברור שהולך אחר האם, ובמילא גם אסור ללמדם תורה (מלבד ע\"ד ז' מצות דבני נח). ומה שאולי חשוב עוד יותר — קליטתם במסגרת ארגון נוער דבנ\"י עלולה ביותר וביותר להביא לטמיעתם ח\"ו בקהל בנ\"י — מבלי כל גרות (ואפילו אם לפעמים יזכירום עד\"ז). ההסברה — ללמדם ולחכות בשאלת הגרות עד י\"ח שנה — פשוט שאינה מתירה האיסור הנ\"ל ולא מבטלת כלל חשש הנ\"ל. — נוסף על שבענין גרות קובע רק גיל י\"ג שנה.\n<span data-k=\"q\">(ממכתב ל' שבט תשכ\"ב)</span>\n<hr>\nמצו\"ב שליחות לילדיהם שי' לצדקה באה\"ק.\nכדאי להסביר לאחותה. . תי': שבאם יש לה רגש בן קיימא לבחור הגוי: איך זה תמשיך אותו לשידוך, שתמיד לאחר רגע של התרגשות [יזכור] שעקרה אותו מכל הדורות של העבר שלו, מאביו ואמו וכל משפחתו שבחיים, ובכל פעם שיפגשם יתעורר שהיא הפרידה ביניהם נצחית.\nהמשערת אחותה. . — איזה רגש יוקבע אצלו?!\nאזכיר על הציון.\n<span data-k=\"q\">(ממכתב תש\"נ)</span>\n<hr>"],[1301550320,"אין ענטפער אויף אייער בריף פון 1230 מיט דאָס בייגעלייגטע, אין וועלכען איר שרייבט וועגען אייער זון שי' און זיין געדאַנק וואָס ער האָט אייך דערציילט.\nאון פאַרשטענדליך אַז דאָס איז דער גרעסטער אומגליק ר\"ל וועלכעס קען טרעפען, אַז אַ איד זאָל טראַכטען, ווי איר שרייבט, וועגן אַ שיקסע, און מ'דאַרף טאָן אַלס מעגליכע צו פאַרהיטען פון דעם אומגליק און אַלס ערשטע ליגט די פליכט אויף עלטערן, און ספּעציעל אַז דאָס איז אַ אייביקער אומגליק, ניט נאָר בעולם הזה נאָר אויך בעולם הבא, און אויב עלטערן טוען אַלעס צו פאַרהיטען קינדער פון ניט גוטעס אויף דער וועלט אַליין, טאָ וויפל דאַרף שוין זיין די אָנשטריינגונג צו פאַרהיטען פון אַ אומגליק, דער גרעסטער, אין די ביידע וועלטען.\nאיך וויל ניט מאריך זיין אין אַזאַ טיפען ווייטדיקען ענין, וואָס מיט אַזעלכע טהאטען העלפט מען אַרויס היטלער'ן — ימ\"ש — וואָס זיין ציל איז דאָך געווען, ס'זאָל זיין וואָס ווייניגער אידן, וואָס דאָס איז די וועג וואָס פירט צו דעם, און מ'דאַרף האָפען אַז דורך טאָן מיט דער געהעריגער אָנשטריינגונג צוזאַמען מיט אַ טיפע תפלה צו השם יתברך, פון יעדערן וועלכער איז פאַראינטערעסירט אין דעם אמת'ן גוטס פון אייער זון שי' און אַלס ערשטע פאַרשטענדליך די עלטערן און די גאָר נאָהענטע, וועט בריינגען צו אָפּהיטען און פאַרהיטען פון דעם גרעסטען אומגליק וואָס ער אַליין וויל בריינגען אויף זיך, ח\"ו.\nאון השי\"ת זאָל אייך העלפען צו אָנזאָגען אַ גוטע בשורה אַזוי ווי איר האָט געבראַכט [די] ידיעה וועגען דעם טיפען צער.\nמ'האָט געדאַרפט בודק זיין די תפילין אייערע און אויך דעם זונ'ס שי' און די מזוזות אין אייער דירה אַז זיי זאָלען זיין אַלע כשר'ה ווי דער דין איז.\n<span data-k=\"q\">(ממכתב י\"ז טבת תשכ\"ד)</span>\n<hr>"],[1301550321,"<h3>ט\"ו באב</h3>\n... שמחתי לקרוא במכתבם מהחלטתם הטובה בקיום המצוות המעשיות בחיי היום יום, שנוסף על ההכרח שבדבר מצד עצמו להיותם צווי השם יתברך ויתעלה, בורא עולם ומנהיגו, הרי הם הצנורות וכלים לקבלת ברכותיו לכל אחד ואחת מכם וב\"ב שיחיו.\nובעמדנו ביום סגולה עליו נאמר לא היו ימים טובים לישראל כחמשה עשר באב, יהי רצון שסוף סוף יקויים יעוד זה בפועל, שאז יקוימו הכתובים כפשוטם וכמשמעם וכדרשת רבותינו ז\"ל, בנות ירושלים יוצאות וחולות בכרמים כו' צאינה וראינה בנות ציון גו' ביום חתונתו זה מתן תורה וביום שמחת לבו זה בנין בית המקדש שיבנה במהרה בימינו, על ידי משיח צדקנו, ובלשון הרמב\"ם יעמוד מלך מבית דוד הוגה בתורה ועוסק במצות כדוד אביו, כפי תורה שבכתב ושבעל פה כו' הרי זה משיח בודאי כו'.\n<span data-k=\"q\">(ממכתב ט\"ו באב תשכ\"ב)</span>\n<hr>\n... ובעמדנו ביום סגולה, חמשה עשר באב, שלא היו ימים טובים בישראל כמותו, כדבר משנה, הבא תיכף אחר תקופת בין המצרים לזכר החורבן והגלות, וכמו שאומרים אנו בתפילה ומפני חטאינו גלינו מארצנו, יהי רצון שבקרוב ממש נזכה לגאולה השלימה והאמתית. והרי החלטתם הטובה להרבות בנר מצוה ותורה אור מביאה גאולה הפרטית, גאולת הנפש וגאולת הגוף, ומקרבת גאולה הכללית של עמנו עם בני ישראל, על ידי משיח צדקנו במהרה בימינו.\n<span data-k=\"q\">(ממכתב ט\"ו באב תשכ\"ב)</span>\n<hr>"],[1301550322,"... ובעמדנו ביום סגולה חמשה עשר באב, וכדבר משנה שלא היו ימים טובים כמותו לישראל, ובנות ירושלים היו יוצאות וחולות בכרמים ואומרות אשה יראת ה' היא תתהלל כו' צאינה וראינה בנות ציון במלך שלמה — שהשלום שלו — גו' ביום חתונתו זה מתן תורה וביום שמחת לבו זה בנין בית המקדש שיבנה במהרה בימינו, יהי רצון שיקויימו כל היעודים הללו, שנשי ובנות ישראל לקחו ולוקחות בהם חלק ראשון, וגדול זכות נשי ובנות חב\"ד בפרט להחדיר יוקר התורה ויוקר המצוות בכל מקום שידן מגעת ולהחיש קיום היעודים הנ\"ל ועד לבנין בית המקדש בקרוב ממש.\n<span data-k=\"q\">(ממכתב ט\"ו באב תשכ\"ב)</span>\n<hr>"],[1301550323,"<h3>עקב</h3>\n... חבל שאין מזדרזין בענין המעמד. ודא עקא שבשכל הרי יש עוד לכל אחד טעם ע\"ז ג\"כ.\nוי\"ל בפרשת השבוע שמתחלת והי' עקב תשמעון את המשפטים, שנקט משפטים דוקא (ועיין ברמב\"ן עה\"ת), עפמ\"ש כ\"ק מו\"ח אדמו\"ר שליט\"א במעלת העקב שזהו ענין הקבלת עול (ד\"ה אין הקב\"ה בא בטרוניא שבס' המאמרים ועוד), וקמ\"ל שאפילו משפטים, מצות שכליות, הנה לולא ענין הקב\"ע מי יודע אם, סו\"ס, אין שומעים אותם.\n<span data-k=\"q\">(ממכתב י\"ח מנ\"א תש\"ז)</span>\n<hr>\nבכל עת שבע רצון אני אם אוכל לענות בעניני תורה, הנלפע\"ד. וגם אלהבא יעשה כן. וכמובן אם יהי' ביכולתי אענה.\nרש\"י<sup data-n=\"1827\">*</sup> בר\"פ עקב, שהוא מיוסד על מדרש תנחומא כאן. יל\"ש ר\"פ עקב. תהלים מט [רמז תשנח. מדרש] תהלים מט, [ו]. ועוד. שאין כאן סתירה — רק מוכחת מילתא. וז\"ל: אמר דוד, רבש\"ע, איני מתיירא מפני מצוות חמורות שבתורה, מפני שהן חמורות, אבל מתיירא אני מפני הקלות שמא עברתי עליהם מפני שהם קלות, ואתה אמרת הוי זהיר במצוה קלה כבחמורה, לכך נאמר והי' עקב תשמעון [כו']. מה רב טובך (תהלים לב), זהו שכרן של מצוות קלות. עכ\"ל.\n<span data-k=\"q\">(ממכתב אלול תש\"ח)</span>\n<hr>",[["1827","*","המקור למבואר בטאָקס אנד טיילס חוב' מנ\"א תש\"ח ע' 4, עה\"פ עקב תשמעון, שיש שכר מיוחד עבור קיום מצוות \"קלות\" שאדם דש בעקביו — דלא כנראה מל' המשנה (אבות פ\"ב מ\"א) \"והוי זהיר במצוה קלה כבחמורה, שאין אתה יודע מתן שכרן של מצוות\". המו\"ל."]]],[1301550324,"בהמשך לשיחתנו אכפול ברכתי אשר תהי' נסיעת כת\"ר עם זוגתו הרבנית תחי' לבקור באה\"ק ת\"ו ע\"י משיח צדקנו, בשעה טובה ומוצלחת.\nואם בנוגע לעובר חנות של בשם נאמר שריחו קולט עאכו\"כ בביקור שלא בדרך מעבר ובארץ עלי' נאמר, עיני ה\"א בה מראשית השנה ועד אחרית שנה, שהאפשרית ניתנה לקליטת ריח וגם בפנימית, ענינים שהנשמה נהנית מהם וגם הגוף נהנה מהם, שהרי גם גוף איש הישראלי קדוש הוא ובקדושת הגוף,\nוכנאמר ג\"כ בדברי רבנו הזקן, ובנו בחרת מכל עם ולשון הוא הגוף וכו' (תניא פרק מ\"ט יעו\"ש היטב).\n<span data-k=\"q\">(ממכתב ל' ניסן תשכ\"ד)</span>\n<hr>\nבמענה על מכתבו המודיע כי מתכוננים הם לעלות לארצה\"ק ת\"ו ומבקש ברכה,\nהנני לשלוח בזה ברכותי שתהי' הנסיעה בזמנה כשורה ובנקל, ויסתדר שם באופן המתאים בגשמיות וברוחניות.\nבטח ידוע לו פתגם כ\"ק מו\"ח אדמו\"ר הכ\"מ, אַז מ'דאַרף מאַכן פון ארץ ישראל ארץ הקדושה, ובאשר כלל הוא בקדושה שלפום גמלא שיחנא, בודאי גם הוא יתבונן בזה וישתדל למלא אחרי דברי הרב הוא נשיאנו כ\"ק מו\"ח אדמו\"ר הכ\"מ.\nבטח יש לו קביעות עתים בתורה בכלל, ובלימוד תורת כ\"ק מו\"ח אדמו\"ר הכ\"מ בפרט, נוסף על השיעורים השוים לכל נפש, כמבואר במורה שיעור.\n<span data-k=\"q\">(ממכתב י\"ב אלול השי\"ת)</span>\n<hr>\n... לכתבו אודות מפלגה וכו' — כמענתי בכיוצא בזה — באם תכניתה אך הנהגות ופעולות שתעשה מדינת היהודים למדינה יהודית.\n<span data-k=\"q\">(ממכתב י\"ז אד\"ר תשמ\"ו)</span>\n<hr>"],[1301550325,"לאחרי הפסק הכי ארוך היתה לי הפתעה נעימה קבלת מכתבו מי\"א במנ\"א, ואף שאינו מזכיר דבר מפעולות מתאימות להמקווה מכל אחד ואחת אשר בארץ ישראל, ארץ הקדש יקרא לה, התקוה בכ\"ז אשר מנצל האפשריות והיכולת שלו בכיוון האמור ככל האפשרי, ומוסיף בתקוה זו תוכן מכתבו ע\"ד בנין תלמוד תורה, תורתנו תורת חיים המביאה לידי קיום מצותי' עליהם נאמר וחי בהם,\nויהי רצון אשר יעשה בהאמור באופן דמוסיף והולך מוסיף ואור ומתוך שמחה.\nלשאלתו בנוגע לביקורי באה\"ק ת\"ו.\nהרי, מכמה סיבות, בנוגע לעתיד הקרוב, אין ביקור זה בסדר זמנים שלי.\nאלא שבתוככי כלל ישראל, ובנוסח הידוע, אני מאמין באמונה שלימה בביאת המשיח וכו' אחכה לו בכל יום שיבוא, ותקותי — תקות כאו\"א ובטחונו אשר יזכה לעלות ברינה קוממיות לארצנו, וכנ\"ל — התקוה היא בכל יום שיבוא.\n<span data-k=\"q\">(ממכתב כ\"א מנ\"א תשכ\"ג)</span>\n<hr>\nאין ענטפער אויף אייער בריף פון מוצאי שבת קדש מיט דאָס בייגעלייגטע, אין וועלכען איר פרעגט, וועגען אַ באַזוך בארץ הקדש ארץ ישראל אויף פיר וואָכען, חאָטש ס'איז אפשר שווער פאַר אייך וכו'.\nבכלל אין אַזעלכע ענינים, וויבאַלד ס'איז אַ ספק, דאַרפמען זיך אָפּהאַלטען פון טאָן דאָס, אַלענספאַל דערוויילע.\nאון לויטן וואָרט פון כ\"ק אדמו\"ר הצמח צדק, אַלס ענטפער צו איינעם, אויף זיינע פראַגע צו פאָרען קיין ארץ ישראל,\n\"מאַך דאָ ארץ ישראל\"\nגעמיינט דורך פאַרשפּרייטען אידישקייט וואו נאָר מ'קען און צוציהען צו אידישקייט וועמען נאָר מ'קען.\nזאָל השם יתברך אייך בענשן מיט אריכות ימים ושנים טובות און טאָן אין דאָס אויבען געזאָגטע מיט גוטע שטימונג און גוטען געזונט,\nאון דער זכות הצדקה (לויט דער בייגעלייגטער קבלה) זאָל אייך ביישטיין אין דעם.\n<span data-k=\"q\">(ממכתב כ\"ו טבת תשכ\"ו)</span>\n<hr>"],[1301550326,"ב\"ה, ה' מנחם-אב, הילולא<sup data-n=\"1828\">1</sup> של האריז\"ל החי\nהתשכ\"ב. ברוקלין נ.י.\nנעם לי להודע מההתעוררות להוספה בפעולות לטובת כולל חב\"ד רמבעה\"ן, מיסודו של כ\"ק אדמו\"ר הזקן ובהנהלתו ואחריו כ\"ק רבותינו נשיאינו ועד לנשיא דורנו כ\"ק מו\"ח אדמו\"ר — זצוקללה\"ה נבג\"מ זי\"ע,\nאשר אם בזמנם אז חיבה יתירה נודעת מהם לפעולות לטובת הכולל חב\"ד,\nעאכו\"כ בדורנו ובזמננו עקבות משיחא ממש,\nוכיון אשר הגאולה תלוי'<sup data-n=\"1829\">2</sup> במעשינו ועבודתינו, מובן אשר בתקופה זו ביחוד הזמן גרמא לענינים השייכים לארצנו הקדושה, פעולות אשר על ידן יתוסף בארץ חיים<sup data-n=\"1830\">3</sup> זו בלימוד תורתנו תורת חיים ובקיום מצותי' עליהן נאמרו וחי בהם,\nוהרי זוהי מטרת ותכלית כולל חב\"ד, כמבואר במכתבי רבותינו נשיאינו בזה בארוכה.\nויהי רצון אשר פעולות האמורות, ביחד עם הפצת מעינות דברי אלקים חיים חוצה, תמהרנה הגאולה האמיתית והשלימה על ידי משיח צדקנו במהרה בימינו ממש.\nויהפכו ימים אלו — דבין המצרים<sup data-n=\"1831\">4</sup> — לששון ולשמחה.\nבכבוד ובברכה לכל המשתתפים בהנ\"ל — העושים והמעשים גם יחד — שליט\"א.\n<hr>\nהנני לוקח רשות לעצמי לעורר דעת כ' לאיזו נקודות העומדות על הפרק, שאף על פי שבודאי לא נעלמו מכ', אבל כיון שלא שמעתי שנעשה דבר מה בנקודות אלו, הרי מחובתי להביאן לתשומת לב כ' לגודל חשיבותן:\n(א) בחדשים האחרונים [... ] כידוע, הגיעו לארצנו הקדושה, תבנה ותכונן על ידי משיח צדקנו במהרה בימינו, אלפי משפחות עולים חדשים. ואף על פי שאפשר שיש ביניהם כאלו שעלו מארצות אשר שם לא כל היהודים, בלי יוצא מן הכלל, היו",[["1828","1","<b>ה' מנחם אב הילולא</b>: שם הגדולים (להחיד\"א) בערכו. וראה ג\"כ תענית כו, א."],["1829","2","<b>הגאולה תלוי'</b>: ראה אגה\"ק ס\"ד."],["1830","3","<b>בארץ חיים</b>: ארץ ישראל (יחזקאל כו, כ. אדר\"נ ספל\"ד. זח\"א קטו, א)."],["1831","4","<b>ויהפכו. . המצרים</b>: עייג\"כ רשימות אדמו\"ר הצ\"צ לאיכה [אוה\"ת נ\"ך (כרך ב) ע' א'לו] (הג\"ה עה\"פ איכה, ושם סו\"פ ג')."]]],[1301550327,"שומרי תורה ומצוות, אבל בודאי שבין העולים החדשים יש מספר חשוב של שומרי תורה ומצוה.\n— ועוד ועיקר, שמהשקפת תורתנו תורת חיים, הרי איך שלא יתנהג יהודי בעבר, בכל יום ויום ניתנת לו התורה ומצוותי' מחדש, ומחוייב לקבלה (אלא שאם קודם לכן לא היתה הנהגתו כדבעי, עליו עוד מצוה מיוחדת, מצות התשובה בפועל) —\nוהנה כשבאים עולים חדשים מסוג זה, הרי ברוב הפעמים מיישבים אותם במושבים חדשים שמייסדים בשבילם, מה שמביא אותם משך זמן מסויים במגע ומשא עם באי כוח המשרדים השייכים להתיישבות וקליטה וכו'. וכטבע בני אדם, רושם ראשון הוא החזק ביותר, בפרט כשקשור עם סיוע בהתיישבות ובהדרכה במקצעי חקלאות או תעשי' וכדומה.\nעל פי הידיעות שקבלתי עד עתה, הנה לצערי הרב ברוב הפעמים ככולם אלו שמקבלים פני העולים בנמל או בשדה התעופה, והמדריכים והמפקחים וכו' רובם ככולם עדין אינם שומרי תורה ומצוות, שזה נראה בעליל מיד בפגישה ראשונה בהנהגתם, אפילו אם אין בדעתם להדגיש אי-דתיותם, ובפרט שיש ביניהם גם כאלו שרוצים להדגיש זה, ועל אחת כמה וכמה כשיש ביניהם כאלו שרוצים לנצל את המצב לרחק העולים מהתורה ומצוות. וכמובן, אחרי שהעולים נופלים תחת השפעה זו, הרי קשה אחר כך למצוא דרכים להחזירם למוטב ולקרבם לה' ולתורתו, כיון שידוע הכלל, עבר ושנה כהיתר נעשה לו, וזהו אפילו אם רק עבר ושנה פעם אחת, ק\"ו אם עבר ושנה כמה פעמים.\nכל האמור בתקפו אם אפילו לא הי' המדובר אלא על דבר נפש אחת בישראל; על אחת כמה וכמה כשהמדובר הוא על דבר אלפי משפחות, וכנראה עומדים לבוא בעתיד הקרוב עוד אלפי משפחות עולים חדשים.\nאי לזאת, עת לעשות היא לנקוט באמצעים דחופים והכרחיים לתקן המצב במדה הכי אפשרית וגדולה.\nבאמת הי' צריך שיהיו באי כוח דתיים במקומות הריכוז בחו\"ל ועל האניות, אבל אם אפילו אין אפשריות לזה, הכרח גמור הוא, לדעתי, שיהיו באי כוח דתיים — על כל פנים לפגוש העולים בשדה התעופה או בנמל, וכן שיהיו משך זמן אתם במקום התיישבותם. וגם בנוגע לעולים שהגיעו בחדשים האחרונים וכבר נפלו במצב האמור, בודאי יש אפשריות לתקן המצב במדה חשובה עכ\"פ אם אי אפשר לתקן לגמרי.\nכמובן שלא נעלם ממני, שהשאלה העקרית תהי' בנוגע לכוח אדם, למצוא אנשים מתאימים לפגוש העולים ולעמוד לימינם וכו'. ואפשר שתעלה גם שאלת מימון. אבל יש תקוה שאם יתחילו לעשות בזה בפועל, יימצאו שני הדברים במדה גדולה יותר מששיערו מראש. והרי אפילו על הספק צריך לעשות, ועל אחת כמה וכמה כשאין ספק שאפשר לפעול הרבה."],[1301550328,"מובן גם כן שלא באתי להציע הצעות איך לתקן המצב, אם על ידי שאלתא בכנסת או באופן רשמי אחר, שמצד אחד יש לחשוש שבאופן זה ילהיבו הרוחות, אבל לאידך גיסא באופן זה גם כן נקל יותר לגייס דעת הציבור ומתנדבים וכו'. ועוד, אם אפילו לא יעשו באופן רשמי, לא יישאר הדבר בסוד, כי אלו שרוצים להסעיר הרוחות יקפצו ויעשו כן, שאז תהי' יד החרדים על התחתונה. ובכגון דא, כסגנון חכמינו ז\"ל, אין לו לדיין אלא מה שעיניו רואות, במקומו ובזמנו.\nולהעיר, כיון שבכל ענין יש מעלה וחסרון, הנה ביחס להעלי' הנוכחית, דוקא משום שלא כל העולים הם, כפי השמועה, שומרי תורה ומצוה, הרי ההכרח בפגישתם כנ\"ל עוד גדול יותר, שאם העולים היו כולם שומרי תורה ומצוה אפשר לצפות שתבוא דרישה מצדם לצרכיהם הדתיים, משא\"כ אם העולים כנ\"ל, שאם לא יתחילו [... ] מרגע הראשון בבואם לא תבוא ההתעוררות מצדם.\n(ב) חריפות מיוחדת לשאלה האמורה כיון שחלק העולים מתיישב באיזורים חדשים. כי אף כשהמושב נמצא בסמיכות לקיבוץ דתי או לעיר גדולה, גם אז מוכרח לעמוד בקשר הדוק עם המושב החדש, על כל פנים בתחילת תקופת התיישבותם. וכש\"כ כאשר העולים מתיישבים בחבל חדש, וכל ענין החבלים החדשים הוא שכל נקודה תהי' עצמאית בלי זיקה לקיבוצים והערים, כי אם שהכל בה, והעומדים בראש פיתוח החבל הם, מטעמים מובנים, מהמפלגה השלטת, הרי בתנאים אלו העולים החדשים מנותקים לגמרי וכל מגעם ומשאם הוא עם באי כוח ונציגים ומדריכים וכו' שאינם שומרי תורה ומצוה, והתוצאות מובנות, והאריכות למותר.\nאמרו חכמינו ז\"ל הכל תלוי במזל. בנוגע מאות הילדים הראשונים יצאו במחאה וסער, ובמדה מסויימת — בלי ספק שהיו לזה תוצאות ממשיות. ועתה בנוגע לאלפי משפחות לא נשמע אפילו הד, וכנראה חסר גם בפעולה.\n(ג) בהמשך לסיום סעיף הקודם, בהנוגע לשאלת קליטת הנוער במסגרת עלית הנוער, ואפילו ילדים בגיל שלפני זה, הרי הבעי' היא לא רק לפעול שימסרו הילדים לחינוך דתי, אלא שיהיו ג\"כ מקומות קליטה מספיקים. ושאלת מקומות קליטה היא לא כ\"כ שאלת הוצאות באכילה ושתי' ולינה והוצאות שוטפות של חינוך, כי בין כך ובין כך מקומות קליטה הקיימים מתקרבים לשיא קליטתם ואפיסת מקום; זאת אומרת, שעיקר הבעי' היא בנינים חדשים, פנימיות ומקומות קליטה חדשים. וזה קשור בסכומים גדולים הרבה יותר לפי ערך מאשר לצרכי אספקה.\nלאידך גיסא, בתקציב הממשלה ובתקציבי המשרדים השונים, וגם לסוכנות, יש סכומים חשובים שנקצבו לדיור וקליטה, שההכרח לדייר את העולים הוא בכל אופן. מכאן, שעכשו שעת הכושר לפעול בנקודה שיטתית ויסודית שמתקציבי הדיור ינתנו סכומים מסויימים בשביל פנימיות נוער בגיל עלית הנוער, וגם בשביל פנימיות לילדים בגיל פחות מזה, ילדים שמצד סיבות לא יכולים לדור עם הוריהם, אם מצד תנאי משפחה, או מצד זה שההורים עדין לא הגיעו לארץ, או מצד גודל המשפחות וכו'."],[1301550329,"והרי הטענה שפנימי' נכנסת בסוג דיור צודקת בלאו הכי, כי מה לי דיור בעד משפחה שלמה ומה לי דיור בעד חלק מבני המשפחה, ואדרבה.\nולדעתי מוכרח להעמיד שאלה ודרישה זו בהקדם, כי לאחרי שתקציב הדיור יתחלק בין המשרדים השונים וכו', הרי אז יהי' צורך לבוא במשא ומתן עם מנהלי המשרדים האלה. משא\"כ קודם ההקצבה, שאז תהי' רק התנגדות כללית. וקרוב לומר שתהי' התנגדות, כי הצד השני בודאי נחש ינחש הכוונה שבדרישה זו.\n<span data-k=\"q\">(ממכתב ג' שבט תשכ\"ב)</span>\n<hr>\n... לכתבו, שכל ימיו מתפלל בהברה ספרדית, האם עליו לשנות להברה אשכנזית, ושמע שיש מעלות בתפלה בהברה זו.\nשמועה זו לא שמעתי, ואיני רואה טעם למה ישנה מהברה שהורגל בה, ככתבו, כל ימיו. ואף שנוסח חב\"ד הוא המובחר — אינו שייך לענין הברה.\n<span data-k=\"q\">(ממכתב ו' מ\"ח תשכ\"א)</span>\n<hr>\nנכון<sup data-n=\"1832\">*</sup> במאד מאד (כמבואר בל\"ת שלח הענין דב' פעמים מאד).\n***\nלח, ג<sup data-n=\"1833\">**</sup>. שהגבוה גבוה שבתפלה — יפעול גם בהמטה מטה (מעשה דאכו\"ש וכו', דבכל דרכיך).\n<span data-k=\"q\">(ממכתב שנת תש\"כ)</span>\n<hr>",[["1832","*","מענה על השאלה אם לשנות נוסח התפלה לנוסח האריז\"ל. המו\"ל."],["1833","**","מענה לשאלה על מענה הנ\"ל: למדתי הנ\"ל [לקוטי תורה שלח] אבל לע\"ע לא יכולתי להבין כוונת כ\"ק אדמו\"ר שליט\"א [הקשר בינו לנוסח התפלה]. המו\"ל."]]],[1301550330,"במענה למכתבו מכ\"ה כסלו, נר ראשון דחנוכה ושואל,\nא) להנאמר בקדיש \"קדם אבוהון דבשמיא\" בלשון נסתר, שלכאורה מוציא החזן א\"ע וכן את הנוכחים מהנ\"ל.\nהכתוב \"אבוהון\", בא בהמשך להאמור מקודם לזה \"דכל בית ישראל\", שזהו כולל גם את הנוכחים והש\"ץ. כן הנאמר בנוסח קדיש דרבנן \"מן קדם אבוהון דבשמיא\", בא בהמשך להתחלת הפסקא \"על ישראל\", ובכלל בחרו בלשון האמור (ככתוב בספר אבודרהם) מפני שכן הוא לשון חכמינו ז\"ל (במשנה ר\"ה סוף פרק ג' בכ\"מ)...\n<span data-k=\"q\">(ממכתב כ\"ז כסלו תשכ\"ב)</span>\n<hr>\nלהשאלה<sup data-n=\"1834\">*</sup> ע\"ד הפסק באמצע התפלה בתיבות טאַטע וכיו\"ב — ראה נימוקי או\"ח (להגה\"צ וכו' ממונקאטש) לסק\"א. אבל מובן דלא כל הרוצה ליטול את השם כו'.\n<span data-k=\"q\">(ממכתב שנת תשכ\"ו)</span>\n<hr>\n... לכתבו במרז\"ל מפני מה כו' לכוון בשם — (לכאורה מקומו שוח\"ט סו\"ס צא — ודלא כגירסתנו. וצ\"ע) — עי' הפי' בשער הק\"ש ד\"ה איתא בספרי (בסידור אדה\"ז) וכן בשרש מצות התפלה — לאדמו\"ר הצ\"צ — פ\"ז.\n<span data-k=\"q\">(ממכתב כ\"ב מנ\"א תשכ\"ב)</span>\n<hr>",[["1834","*","ראה גם לקו\"ש חי\"ד ע' 225. המו\"ל."]]],[1301550331,"במענה למכתבו מב' טבת, בו כותב אודות התפלה שלו ומצב רוחו הקשור בזה, ואיך שזה פועל צמצום הפרנסה שלו וכו'.\nוהנה שמענו איזה פעמים סיפור מכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נב\"מ זי\"ע, דמנהג חסידים הראשונים, שהיו מחלקים התפלה לכמה חלקים, ז.א. שבכל פעם ופעם היו כמובן מתפללים כל התפלה, אלא שההתבוננות בענינים ובכוונת פירוש המלות או ההסבר בהם, היו מחלקים לכמה ימים באופן שבמשך כשבוע ושבועים היו גומרים פירוש המלות פעם אחת ואחר כן חוזר חלילה, ולכן גם הוא יעשה באופן הנ\"ל, ובמצבו הנה יסדר אשר בימות החול יהי' זמן תפלתו בבקר לערך שתי שעות מתחלתה ועד סופה.\nבמ\"ש אשר לפעמים שונה וכופל תיבה אחת. — העצה היעוצה לזה הוא להתפלל מבפנים הסידור, ובלא\"ה נכון הדבר, ועצה לכמה ענינים.\nתקותי שבכל יום חול קודם תפלת השחר מפריש איזו פרוטות לצדקה, וכן אשר אחרי התפלה וגם בש\"ק ויום טוב שומר על השיעור תהלים חדשי — כמו שנחלק התהלים לימי החדש — לאומרו, ומהנכון אשר יבדקו את התפילין שלו וכן את המזוזות בדירתו, שתהיינה כולן כשרות כדין.\nכן מהנכון אשר ילמוד בעל פה בספר תניא קדישא מהתחלת פרק מ\"א עד לעמוד ב' תיבת המלך, וכשיתבונן בתוכן הענין אשר ה' נצב עליו, והוא עצם הטוב, והבטיח אשר הבא לטהר מסייעין אותו, והאדם כאשר מקדש עצמו מעט למטה מקדשין אותו הרבה מלמעלה, בטח שהדאגות תתמעטנה ותופחתנה עד שתתבטלנה כליל, והרי נצטווינו לעבוד השי\"ת בשמחה ובטוב לבב דוקא כמבואר בכו\"כ מקומות.\nכיון שכותב אלי תקותי, שיש לו קביעות עתים גם בלימוד תורת החסידות שהיא המביאה חיות ושמחה גם בחלק לימוד הנגלה דתורה ובקיום המצות.\n<span data-k=\"q\">(ממכתב ששי בטבת תשי\"ט)</span>\n<hr>\n... ב) במה שציינתי, שהתבוננות קודם התפלה ובתפלה עצמה מבואר בתניא וכו' וכתוב שימצא שם כו\"כ אופנים — מובן שכמה מאופנים המובאים שם, כתוב בפירוש הסוג השייך לאופן זה שאינו כלל מסוגו הוא אברך הלומד בישיבה ונמצא בכותלי הישיבה וכו' ומכל אותן האופנים שראה כתוב בודאי שלא יהי' ספק אצלו אלא בהנוגע לשנים שלשה מהם, אז יתייעץ עם המשפיע באיזה מהן לבחור."],[1301550332,"ג) לכתבו, שכשמתחיל להתבונן באיזה ענין בדא\"ח או בענין לימוד בכלל — נופלים לו כמה מחשבות מבלבלות.\nידועה העצה בזה ללמוד מתוך הספר, וגם בשעה שמתבונן והעינים סגורות, יהי' הספר פתוח לפניו, שהאותיות אוחזות המחשבה וממעטים הבלבולים ולפעמים מבטלין אותן כליל.\nד) במ\"ש שההתבוננות בפרק תניא מ\"א מהתחלתו עד לעמוד ב' תיבת המלך, הננו רחוק מזה — אל יתרשם מפתויי היצר אלה, כי אם יחזור על הענין במחשבתו איזו פעמים, ובמילא ישתתקו טענות היצר...\n<span data-k=\"q\">(ממכתב ה' אייר תשי\"ט)</span>\n<hr>\nבמענה למכתבו מעש\"ק ושואל לימוד התניא מתי יהי' אם קודם התפלה או לפני השכיבה.\nהנה לאמיתתו של דבר בכגון דא נחוץ הוא בשני הזמנים, אבל בעיקר הוא בבקר קודם התפלה, כיון שלימוד זה מוסיף בהתפלה וענינה (עיין ג\"כ רמב\"ם הלכות יסודי התורה (ריש פרק ב') ורבנו הזקן בהקדמה לסידורו ד\"ה הקול קול יעקב) והרי התפלה נותנת חיות בכל היום כולו לא רק בנוגע לעניני הרשות וכו' שע\"י התפלה עושים אותם באופן אחר לגמרי, כי אם גם בנוגע לימוד התורה, וכתפלתו של אבא בנימין, שתהי' תפלתי סמוך למטתי (עיין לקו\"ת ברכה צ\"ו ב').\n<span data-k=\"q\">(ממכתב י\"א טבת תשכ\"ב)</span>\n<hr>\n... בהנוגע לכוונה בתפלה, צדק בדבריו שלא בכל פעם היא אותה העצה, שהרי תלוי זה במצב רוח האדם, המשתנה מזמן לזמן, בכ\"ז ישנן נקודות כלליות, אשר בכל עת ובכל זמן מועילות הן, ומהן נתינת הצדקה לפני התפלה וכמרז\"ל (ב\"ב י, א') ר\"א יהיב פרוטה לעני והדר מצלי, וכמ\"ש אני בצדק (אזי) אחזה פניך, כן הזהירות בטבילת עזרא, ושיהי' הסידור פתוח לפניו במקום בו מתפלל, ז.א. שאפילו כשמפני העמקות"],[1301550333,"או התלהבות מתפלל בעינים סגורות וכיו\"ב עצם הענין שהסידור פתוח באותו מקום, מאחז (האַלט צו) המחשבה...\n<span data-k=\"q\">(ממכתב ג' טבת תשי\"ט)</span>\n<hr>\n... בתחלתו<sup data-n=\"1835\">*</sup>. ב. ע\"א כללות תיקון כו': ראה בכ\"ז: שער הכוונות תפלת השחר דרוש ב-ג. פע\"ח שער התפלה פ\"א, ה, ז. עולת תמיד ד\"ז, ח (בדפוס ירושלים, תרס\"ז). נהר שלום מח, א. נד, א ואילך (נדפס גם בסו\"ס ע\"ח דפוס ווארשא). שמן ששון לשעה\"כ שם. שם ח\"ד סדר תפלת שחרית אות ו'...\n<span data-k=\"q\">(ממכתב כ\"ה כסלו תשכ\"ב)</span>\n<hr>\nבמענה למכתבו מז' חשון, בו כותב אודות הרעיון להו\"ל תוכן התפלה, בצורת סידור הבעש\"ט וכו', ושואל דעתי בזה.\nובהנ\"ל שני ענינים נפרדים, סידור, ז.א. נוסח תפלה, ותוכן תפלה, שאפשר גם זה לפרשה בשני אופנים: פירוש המלות ע\"ד הבעש\"ט, או כללות ענין התפלה ומהותה.\nוהנה בנוגע סידור הבעש\"ט, ידוע שהתפלל בסידור האריז\"ל והרי ישנו גם עתה סידור הבעש\"ט, ועיין שער סידור האריז\"ל להר\"ש מרשקוב.\nפירוש המלות ע\"ד החסידות דהבעש\"ט מפוזרים בספרי תלמידי הבעש\"ט, ואף שרק במקצתם הוזכר בפירוש שהם מהבעש\"ט, כנראה שרובם מיוסדים עכ\"פ על תורת הבעש\"ט, והמקצת מעיד על הרוב.\nותוכן ענין תפלה ע\"פ תורת הבעש\"ט, לוקט מכמה וכמה ספרים וגם נדפס — בספר הבעש\"ט על התורה להרב שמעון מנחם מענדל שו\"ב, בפרשת נח.\nומאחר שהכל בהשגחה פרטית, עלי החובה (והזכות) לעוררו על ההכרח לקבוע",[["1835","*","סידור האריז\"ל — הר\"ש מרשקוב (ברוקלין, תשכ\"א). המו\"ל."]]],[1301550334,"עתים בלימוד פנימיות התורה שבדורנו נתגלתה בתורת החסידות קביעות בכל יום ובהוספה ביום השבת אשר קדש הוא לה'...\nמקום שהוזכר הבעש\"ט בס' התניא תורה אור ולקו\"ת — צויין במפתחות שבסוף הס'.\n<span data-k=\"q\">(ממכתב יו\"ד מ\"ח תשכ\"ב)</span>\n<hr>\n... דרך אגב הגיעתני ידיעה אשר הוציאו לאור סידור או מחזור או הגדה, או כולם יחד, בנוסח מאוחד בשביל בני עדתות השונות אשר באה\"ק ת\"ו. ובטח ידועה לכ' עמדתי בזה בשלילה, שהרי ענין התפלה הוא עבודה שבלב ואין להתערב בזה, ואדרבה מנהג אבותיהם בידיהם. בכל זה, באם כבר הופיע אסיר תודה אהי' לכ' אם יכלול גם זה במשלוחים הבאים.\n<span data-k=\"q\">(ממכתב כ\"ח מ\"ח תשכ\"ו)</span>\n<hr>\n... לשאלתו האם מותר ללמוד חסידות לבנות — פסק ברור בזה בהלכות ת\"ת ולדוגמא עיין הלכות ת\"ת לרבנו הזקן סוף פרק א: הנשים חייבות ללמוד הלכות הצריכות להן לידע אותן וכו' כל מצות עשה שאין הזמן גרמא וכו' —\nוהרי תכלית שלילת ענין הזמן במצות עשה, הן המצות שחיובן תמידי לא יפסק מעל האדם אפי' רגע בכל ימיו, להאמין בשם ליחדו, לאהבה אותו וליראה אותו [שלא להאמין בזולתו, שלא לסור אחרי מחשבת הלב וראיית העינים] (אגרת המחבר ס' החינוך) —\nוהרי קיום מצות אלו לאמיתתן ולא מן השפה ולחוץ בא כדברי המורה הגדול בהלכות יסודי התורה ריש פרק ב': והיאך היא הדרך וכו' בשעה שיתבונן כו' שהתבוננות זו היא באה בלימוד תורת החסידות וק\"ל...\n<span data-k=\"q\">(ממכתב כ\"ט טבת תשכ\"א)</span>\n<hr>"],[1301550335,"... בדעתי לנסוע צלחה לנ.י. סוף שבוע זה או אמצע שבוע הבע\"ל. כמובן, חפצי לברר ולסדר הענינים שנמסרו לחלק עבודתי, עד כמה שתלוי בי, עוד קודם נסעי. ואחד הענינים האלו הוא ענין הנפנה<sup data-n=\"1836\">*</sup> (אף, שכמובן, השתתפותי בזה הוא באופן שלא יודע בחוץ, כיון שטאסז לגסז<sup data-n=\"1837\">**</sup>).\nלמרות ששאלתי וחקו\"ד להנעשה בזה במחנם ובמחנות אנ\"ש אשר השפעתו עליהם, איני יודע דבר ברור: אם יש יחידים או ועד המתעסק בזה בקביעות, אם הוא בדרך נפנה חדשי, האם נודע להם שהמצב דחוק וכו' וכו'.\nאמרתי פה בהתועדות עם אנ\"ש והתמימים, דהנה ההתקשרות צ\"ל בכל הכחות שאפשר. והנה, לכל לראש, אצל חסידי חב\"ד כשמו כן הוא שצריך להתקשר בחב\"ד, היינו, בפשטות, ללמוד מאמרי וכ\"ק הנשיא. — כיון שכוונת אומר המאמרים הוא המשכת חב\"ד במדות ושינוי המדות על ידן, ה\"ז מכריח התקשרות ע\"י שוהלכת בדרכיו וע\"פ הוראותיו במדות ומחדו\"מ.\nאבל כ\"ז נוגע — רירט אָן — בכח או כחות פרטים, ועכ\"פ בכחות הגלויים, וא\"כ כיון שעדיין נשאר הספק באיזה דרך מוליכין אותו, ה\"ז מטיל ספק באיזה מקום מקושר הוא בפנימיותו ועצמותו.\nוהעצה לזה הוא רק ע\"י ענין הנפנה ועפמשנ\"ת בתניא פל\"ד, ל\"ז. אגה\"ק ס\"ד ועוד.\nוהנה כהנ\"ל הוא גם בשנים כתיקונם. וכ\"ש וק\"ו בעתים הללו, אשר ההתקשרות ע\"י חב\"ד חג\"ת נהי\"ם סבלה ע\"י צוק הזמנים ריחוק המקום והפסק הקישור אפילו בכתב למשך שנים רבות, שצ\"ל ההתקשרות בנפנה ביתר שאת ויתר עז.\nקצרתי בזה מבטחוני שיספיק הקיצור, והעיקר בתקותי שאין הם זקוקים להערה בענין זה, ואפילו לא בנוגע להעדפה וזריזות, וזריזותי' היא העומדת לעד כו'. . .\n<span data-k=\"q\">(ממכתב י\"ג סיון תש\"ז)</span>\n<hr>\nאייער בריף פון ר\"ח תמוז מיט בייגעלייגטן שעק אויף נאָמען פון מרכז לעניני חנוך ערהאַלטן, לויט אייער רשות צו טיילן לדעתי, האָב איך עס פאַרטיילט: מעשר אויף מעמד. האַלב פון די איבערגעבליבענע — אויף אָפּדרוקן און פאַנאַנדערשיקן דעם קונטרס י\"ב-י\"ג תמוז הבע\"ל, ווען עס ווערט דעם רבי'ן זיבעציק יאָר. און",[["1836","*","כינוי לכספי מעמד. המו\"ל."],["1837","**","שחתנו כבנו. המו\"ל."]]],[1301550336,"אויפגעשריבן אַפן קונטרס אַז דאָס זאָל פועלן מחזק זיין די התקשרות פון הרוצה בעילום שמו צום רבי'ן — (דורך דרוקן און פאַרשפּרייטן זיין תורה בכל קצווי תבל).\nאיך האָב עס ספּעציעל געטאָן, ווייל איך ווייס ניט וואָס עס טוט זיך מיט התקשרות (האָט נאָר קיין פאַראיבל ניט פאַרן זאָגן עס).\nאיך זה כמה וכמה מופתים פון רבי'ן איצט, איז אויב איר זאָגט, אַז באַ אייך איז \"ניטאָ קיין נייעס\" — מוז דאָך עפּעס זיין אַ סיבה אין דעם.\nזייער מעגליך, אַז דער רבי האַלט אַז מ'דאַרף איצט ניט פאַרקויפן דעם בילדינג דערפאַר איז ניטאָ קיין קונים וכיוצא בזה.\nאון אפשר איז דאָס מצד דער חלישות, ח\"ו, בהתקשרות. — (איך גלויב אָבער אַז איר האָט אויך געהאַט מופתים (מיט'ן שותף וכיוצא בזה) נאָר איר באַמערקט ניט אַלע) — דערפאַר האָב איך פאַרנוצט אַ טייל פון אייערע געלד אַף דער הפצה פון רבי'ס תורה — איינע פון די בעסטע עצות אוי[ף] התקשרות לנשיא ישראל בעל התורה.\nדי צווייטע העלפט אַריינגעטראָגן אין דער לשכת חשאים פון וואַנעט דער רבי פלעגט העלפן בחשאי צו אנשים נכבדים און וואָס עס ווערט געטאָן אויך ווייטער.\nדער קונטרס וועט זיין פאַרטיק אין אייניגע טעג אַרום. דער כתר שם טוב בייגעלייגט. ביטע מודיע זיין אַז איר וועט עס באַקומען.\nהמברכו בכל טוב ומחכה לבשורות טובות.\n<span data-k=\"q\">(ממכתב ד' תמוז השי\"ת)</span>\n<hr>\nב\"ה, כ\"ח אייר, תשכ\"א\nברוקלין.\nהמשתתפים בההגרלה השנתית לנסיעה בחודש תשרי הבע\"ל, שהתקיימה בכפר חב\"ד, מיסודו ובהנהלתו של כ\"ק מו\"ח אדמו\"ר, אשר שם צוה ה' את הברכה חיים\nה' עליהם יחיו\nשלום וברכה!\nמאשר הנני קבלת רשימת המשתתפים בההגרלה עם ההודעה ע\"ד ההגרלה והזוכה בגורל שי'."],[1301550337,"ויהי רצון, כאמור מכבר, שהזוכה יוציא בנסיעתו את כל המשתתפים ויזכה אותם בכל המובנים הן בכמות והן באיכות.\nובפרט עפ\"י גודל הענין דגורל כשנעשה כדבעי, כמבואר גם בתניא באגה\"ק סוף סימן ז', ומקרא מלא דבר הכתוב בחיק יוטל את הגורל ומה' כל משפטו (משלי טז, לג).\nוע\"פ סיפור חסידים הראשונים בשם הרה\"ח הרה\"צ והרה\"ג כו' הר\"ה מפאריטש שכל הענינים וההידורים שעושה הי' בשביל עס זאָל זיך באַ אים בעסער אָפּלייגען אַ וואָרט חסידות,\nיהי רצון שגם בהאמור — נוסף על עניני הנסיעה, יתוסף גם ענין עקרי זה, ובכל המשתתפים, בתוככי כללות התמימים ואנ\"ש, עס זאָל זיך אָפּלייגן אַ וואָרט חסידות באופן דהבנה עד כדי — בכן. ועוד (ובתקופתנו — גם זה עיקר) — לא יסתפקו כלל וכלל מיט אַ וואָרט, כי אם מי שיש לו מנה ירצה מאתיים וכו'.\nומובן וגם פשוט שאין לחכות לתועליות בהאמור עד הנסיעה בפועל, כי ההתחלה צריכה להיות מעת ההגרלה וההחלטה. וק\"ל.\nבברכה לבשורות טובות בהאמור, ובלשון רבנו נשאינו הוא כ\"ק מו\"ח אדמו\"ר — לקבלת התורה בשמחה ובפנימיות.\n<hr>\n... לפלא הכי גדול כתבו ע\"ד שאין עתה \"יחידות\" לכאו\"א בפ\"ע — שכנראה אינו יודע (או שלא הגיעו — (ראה לקו\"ת ר\"פ שמיני)) המדובר וכמה פעמים ע\"ד גודל המעלה דהיחידות הכללית ובביהכ\"נ ובביהמ\"ד וכו'.\n<span data-k=\"q\">(ממכתב ב' אייר תשמ\"ז)</span>\n<hr>\n... לכתבו אודות התלמידים שהיו כאן ובקשר עם התוועדות דיו\"ד שבט, והשאלה איך לפעול נח\"ר ותענוג.\nמוכרחני לאמר שלא שיערתי שעל זה צריך לשאול במדינה אחרת מעבר לגבול, בה בשעה שזהו — תוכן התומ\"צ. ובפרט ע\"פ המבואר ומואר בתורת דא\"ח החסידות, והנקודה אשר אין טוב אלא תורה, ובביאור יותר שטוב האמיתי הוא טוב"],[1301550338,"לשמים וטוב לבריות וטוב העושה פירות, שצ\"ל ג' הענינים, ובהוספת ביאור ע\"פ בי' המאמר פנימיות אבא פנימיות עתיק, אשר פנימיות התענוג הוא בעצמו נעשה פנימיות החכמה, שזהו בפנימיות התורה, הבנה והשגה ועד לשכל דנה\"ב, ביחד עם היותם רזי דרזין דאורייתא, וע\"פ המבואר שהתענוג הוא היפך ואתהפכא דהצער — הנה דוקא בדרא דעקבתא דמשיחא, ודוקא בעניני מעשה בפועל וקב\"ע שייך תענוג האמיתי עד שיבוא הזמן המאושר דתענוג הפשוט שאינו מורכב בשום ענין, שבת ומנוחה לחי העולמים.\nובנוגע לתלמידי תו\"ת ביחוד, הרי בזה לכל לראש — שמירת סדרי הישיבה בדיוק, ובהוספה ע\"ז בזמנים העומדים לרשותם, וכמובן וגם פשוט אשר וגם צריך להעשות זה מבלי לנגוע בבריאות הגוף, אשר היות הגוף בריא ושלם מדרכי השם הוא. גם די זמן פנוי לאח\"ז להתעסק בהפצת המעיינות חוצה, לא רק בהחוצה דעצמו, אלא גם בהחוצה כפשוטו, ויהי רצון שיסביר וישפיע כל הנ\"ל לכל אלו ששאלוהו בהאמור ולכל אלו שישאלוהו בעתיד ואפילו לאלו שצריכים היו לשאול אלא ש\"הנחות — בע\"ב\" מעכבתם מלשאול.\n<span data-k=\"q\">(ממכתב א' אדר תשכ\"א)</span>\n<hr>\n... רז\"ל דערציילן (עירובין י\"ג, ב), אמר רבי האי דמחדדנא מחבריא דחזיתי' לר' מאיר מאחורי' (כשלמדתי לפניו ישבתי בשורה של אחריו, פרש\"י) ואלו חזיתי' מקמי' הוה מחדדנא טפי דכתיב והיו עיניך רואות את מוריך.\nנאָך מער אונטערשטרייכן רז\"ל די באַדייטונג פון \"זעהן אַ רבי'ן\" אין ירושלמי ביצה (פ\"ה ה\"ב — עיי\"ש בגליון הש\"ס — הובא בתוד\"ה מוריינא מנחות קד, א), אַז רבי, ר' יוחנן און רשב\"ל האָבן זוכה געווען צו זייער תורה דערפאַר וואָס זיי האָבן געזען זייער רבי'ן איינמאָל!\nאיר, וועלכער האָט זוכה געווען צו זען — אין דעם לשון פון כ\"ק מו\"ח אדמו\"ר שליט\"א — \"כ\"ק אדמו\"ר אור עולם נזר ישראל ותפארתו כקש\"ת מוהר\"ר שמואל זצוקללה\"ה נבג\"מ זי\"ע\" איז געוויס האָט די דאָזיגע ראי' געהאַט איר גוטע פעולה אין גשמיות און אין רוחניות, און זיכער ווירקט זי נאָך עד היום, וואָרום ראיית צדיק איז אַן אייביגע און זי באַגלייט דעם מענטשן זיין גאַנצן לעבן, און בכלל ווייסן מיר דאָך אַז \"אין רוחניות איז ניטאָ קיין עבר\" (שיחת כ\"ק מו\"ח אדמו\"ר שליט\"א י\"ג תמוז, שנה זו<sup data-n=\"1838\">*</sup>).",[["1838","*","סה\"ש תש\"ה ע' 115. המו\"ל."]]],[1301550339,"יעצט שטייט אייך פאָר, אם יסכים, אַן אויסערגעוויינליך גרויסער זכות: — אַז דורך אייערע מיטלען, מיט דער מיטהילף פון אייערע קינדער יחיו, זאָלן פאַרעפענטליכט ווערן פיעל חדושי תורה פון גרויסן צדיק, דעם רבי'ן מהר\"ש נבג\"מ זי\"ע, וואָס ווען אימיצער וועט לערנען אַ מאמר פון די מאמרים וועלכע ווערן פאַרעפענטליכט ווערן דורך אייער הילף, ווען דער לערנער זאָל אפילו זיין אין עק וועלט, איז דאַן \"רעדן די נשמה פון צדיק אין ישיבה של מעלה און זיינע ליפּן אין קבר\" (תוד\"ה אגורה יבמות צו, ב), און עס ווערט אויסגערופן אַז דאָס אַלעס איז ערמעגליכט געוואָרען דורך אייך! און ווער קען עס משער זיין דעם גרויסן שכר און די גרויסע דערהויבונג וואָס עס איז זוכה דער וועלכער ערמעגליכט אַזאַ גרויסן ענין, סיי בזה און סיי בבא!\nאיך שרייב אייך אויף דער הצעה פון כ\"ק מו\"ח אדמו\"ר שליט\"א, וועלכער האָפט, אַז איר און אייערע קינדער יחיו וועט אויפנעמען דעם דאָזיגן גרויסן זכות מיט גרויס צופרידנהייט. . .\n<span data-k=\"q\">(ממכתב י\"ז מנ\"א תש\"ה)</span>"],[1301550340,"<h3>כ' מנחם אב</h3>\nב\"ה, יום הששי<sup data-n=\"1839\">1</sup> פ' ואתחנן,\nחמשה עשר במנחם אב<sup data-n=\"1840\">2</sup>,\nחודש דמזלי' ארי', ארי'<sup data-n=\"1841\">5</sup> שאג<sup data-n=\"1842\">4</sup> מי לא יירא<sup data-n=\"1843\">3</sup>,\nה'תשמ\"ח, שנת הקהל<sup data-n=\"1844\">6</sup>, ברוקלין, נ.י.\nלכל המשתתפים בכינוס השלוחים התשיעי,\nבארצנו הקדושה תובב\"א,\nה' עליהם יחיו\nשלום וברכה!\nבנועם קבלתי ההודעה ע\"ד קביעות זמן כינוס השלוחים התשיעי בארצנו הקדושה, \"ביום הראשון לס' \"תמיד עיני ה\"א בה מרשית השנה<sup data-n=\"1845\">8</sup> ועד אחרית שנה\" טו\"ב לחודש מנחם אב ותיכף לו (שלשת ימים<sup data-n=\"1846\">9</sup>) יום כ\"ף מנחם-אב — יום ההילולא של הרה\"ג והרה\"ח המקובל מוהר\"ר לוי יצחק ז\"ל נ\"ע\",\n\"בבית חב\"ד, רחובות<sup data-n=\"1847\">7</sup>\",",[["1839","1","<b>יום הששי</b>: שהוכפל בו טוב — בראשית א, כה. שם, לא. חזקוני עה\"פ שם, לא. וראה רמב\"ן שם. וראה לקו\"ש חכ\"ד ע' 641 הערה ד\"ה עש\"ק."],["1840","2","<b>חמשה עשר במנחם אב</b>: ראה משנה סוף תענית וגמרא שם. זח\"ב קלה, א. פע\"ח דרוש סוד ט\"ו באב (הובא ונתבאר בד\"ה נחמו, עת\"ר). לקו\"א להה\"מ (הוצאת קה\"ת) סקל\"ד (לא, ג). רשימות הצ\"צ לאיכה (אוה\"ת נ\"ך כרך ב ע' א'צו). לקוטי לוי\"צ אגרות ע' תיג."],["1841","5","<b>ארי' שאג</b>: וידוע הר\"ת דארי' אלול ר\"ה יוהכ\"פ הו\"ר (של\"ה ריש מס' ר\"ה (ריג, א). הובא ונתבאר באוה\"ת ר\"ה ע' א'תכב), עבודת התשובה, דבתשובה נגאלין (סנהדרין צז, ב. רמב\"ם הל' תשובה פ\"ז ה\"ה) וארי' יבנה אריאל (יל\"ש שם). ובלקו\"ת ר\"פ עקב: וגם ימים נוראים נקראים ע\"ש ארי' כי ארי' אותיות יראה (קה\"י ערך יראה)."],["1842","4","<b>ארי'. . יירא</b>: עמוס ג, ח."],["1843","3","<b>דמזלי'. . יירא</b>: ראה יל\"ש ירמי' בראשו ובתחלתו (רמז נטר)."],["1844","6","<b>שנת הקהל</b>: ראה מכתב וא\"ו תשרי שנה זו הערה ד\"ה זה (לקמן ע' 329)."],["1845","8","<b>תמיד. . שנה</b>: פרשת השבוע (עקב יא, יב) בו חל הכינוס."],["1846","9","<b>שלשת ימים</b>: כידוע שג' ימים נחשבים למציאות אחת — ראה פסחים קו, סע\"א. רמב\"ם הל' שבת פכ\"ט ה\"ד. שו\"ע אדה\"ז או\"ח סרפ\"ה ס\"ה. סרצ\"ט ס\"ח. ולהעיר מהדין דכל פחות מג' כלבוד דמי — רמב\"ם שם פט\"ז ה\"ח. ובכ\"מ."],["1847","7","<b>ביום. . רחובות</b>: ל' ההזמנה השלוחה להשלוחים שי' — ובמילא חל על זה אריכות הביאור בתורת הה\"מ (לקו\"א סרי\"ג — נב, א) ש\"כל המקריות שיקרה לאדם. . זהו כמשל מי שרואה במראה שרואה כנגדו פרצופו וכו'\" — בכל תיבה."]]],[1301550341,"כינוס אשר קבעו הנושא שלו \"והחי יתן אל לבו<sup data-n=\"1848\">10</sup>\", \"שנת הילד והילדה<sup data-n=\"1849\">11</sup>\".\nויה\"ר שיהא בהצלחה רבה בכל — והרי הודיעה תורתנו תורת אמת בקשר לאבוהן דכל שלוחים, שהוא לכל לראש \"משה רבנו\", שליח למסור תורת השם ומצוותי': לכה ואשלחך גו' ואנכי אהי' גו' והוריתי אתכם את אשר תעשון<sup data-n=\"1850\">12</sup>,\nובפרט שבמשך כל השנה שעברה, שכוללת כל שינויים האפשריים<sup data-n=\"1851\">13</sup>, בטח פעלו בהתאם להחלטות כל הכינוסים הקודמים.\nובאופן דכינוס<sup data-n=\"1852\">14</sup> — דיש בזה זכות ותוקף דרבים<sup data-n=\"1853\">15</sup>, ויתירה מזה — דציבור, שהרי בודאי יתאחדו כולם למציאות (חדשה<sup data-n=\"1854\">16</sup>) אחת בלב אחד<sup data-n=\"1855\">17</sup> ע\"י אהבת ישראל ועד לאחדות ישראל,\nובתור שלוחים של אחד, כ\"ק מו\"ח אדמו\"ר, נשיא דורנו, שהנשיא הוא הכל<sup data-n=\"1856\">18</sup> —\nהתשיעי — מספר המזכיר שהוא המכין בשלימות את השלימות של \"העשירי<sup data-n=\"1857\">19</sup> יהי' קודש<sup data-n=\"1858\">20</sup>\",\nביום הראשון הנקרא בתורה אור<sup data-n=\"1859\">22</sup>, ובה עצמה ב\"פתח דבריך יאיר<sup data-n=\"1860\">23</sup>\", יום אחד, שלא הי' בעולם אלא אחד<sup data-n=\"1861\">21</sup>, ונמשך בכל הימים שלאחרי זה ע\"י אשר \"אתה הראת לדעת כי הוי' הוא האלקים אין עוד מלבדו<sup data-n=\"1862\">24</sup>\",",[["1848","10","<b>והחי יתן אל לבו</b>: קהלת ז, ב."],["1849","11","<b>שנת הילד והילדה</b>: ראה סה\"ש תשמ\"ח ח\"ב ע' 8­537. 2­551."],["1850","12","<b>לכה. . תעשון</b>: שמות ג, י. שם ד, טו."],["1851","13","<b>כל השנה. . שינויים האפשריים</b>: ראה ביאורי מעלת אתרוג שדר באילנו כו' (סוכה לה, א) — סידור (עם דא\"ח) שער הלולב רסא, ג ואילך. שם רסד, סע\"ד ואילך. המשך וככה תרל\"ז פפ\"ז. סה\"מ — מלוקט ח\"א ע' תמב. וש\"נ."],["1852","14","<b>ובאופן דכינוס</b>: מתורת הבעש\"ט בתכלית פגישת שני אנשים (כש\"ט — הוצאת קה\"ת — הוספות סקכ\"ו) מובן גודל הענין דפגישה בכינוס דרוב עם."],["1853","15","<b>זכות ותוקף דרבים</b>: ראה ברכות ח, רע\"א. שו\"ע אדה\"ז או\"ח ס\"צ ס\"י. וראה ד\"ה פדה בשלום לאדמו\"ר האמצעי פי\"ב (שער התשובה ח\"א — שער התפלה — נו, ג­ד). ד\"ה עשרה שיושבים, תרפ\"ח (סה\"מ תרפ\"ח ע' קמח ואילך). וראה קונטרס החלצו, תרנ\"ט פ\"י. וראה גם שם פ\"ז (סה\"מ תרנ\"ט ע' סא. שם ע' נט)."],["1854","16","<b>דציבור. . למציאות (חדשה)</b>: ראה צפע\"נ — כללי התורה והמצוה ערך צבור."],["1855","17","<b>יתאחדו. . בלב אחד</b>: כלשון המכילתא עה\"פ ויחן שם ישראל (יתרו יט, ב). פרש\"י שם. וראה תו\"א ס\"פ נח. מאמרי אדה\"ז — ענינים ע' פו ואילך (ועם הגהות — באוה\"ת נח כרך ג תרלב, ב ואילך). תו\"ח נח ד\"ה ויהי כל הארץ שפה אחת פמ\"ב (עד, א) ואילך. ועוד."],["1856","18","<b>שהנשיא הוא הכל</b>: פרש\"י עה\"פ חוקת כא, כא (מתנחומא חוקת כג). וראה רמב\"ם הל' מלכים פ\"ג ה\"ו: לבו (של מלך) הוא לב כל קהל ישראל. וראה לקו\"ש חי\"ט ע' 165 ואילך."],["1857","19","<b>השלימות של \"העשירי</b>: ראה פרדס שער ב (שער טעם האצילות). ראב\"ע עה\"פ שמות ג, טו."],["1858","20","<b>העשירי יהי' קודש</b>: ל' הכתוב — בחוקותי כז, לב. וראה זח\"ב רעא, א."],["1859","22","<b>בתורה אור</b>: משלי ו, כג."],["1860","23","<b>פתח דבריך יאיר</b>: תהלים קיט, קל. וראה ב\"ר רפ\"ג. פרש\"י עה\"פ."],["1861","21","<b>הנקרא בתורה. . יום אחד. . אלא אחד</b>: בראשית א, ה. פרש\"י עה\"פ (בשם ב\"ר — פ\"ג, ח)."],["1862","24","<b>אתה. . מלבדו</b>: ואתחנן ד, לה. — פרשת השבוע בו נכתב מכתב זה."]]],[1301550342,"לס' \"תמיד עיני ה\"א. . שנה\", שזוהי כוונת ומטרת השליחות לפעול בכאו\"א מבנ\"י, ארץ חפץ<sup data-n=\"1863\">25</sup> דה' אלקינו, שיוכר בו תמיד אשר עיני ה\"א בו בגלוי,\nבבית — לפעול התיישבות וקביעות<sup data-n=\"1864\">26</sup>,\nחב\"ד — שהעבודה בכל הענינים האמורים היא באופן דהתיישבות (כנ\"ל), וחודרת באופן פנימי, ונקבעת (בית) בכל פרטי הכחות דחכמה בינה ודעת<sup data-n=\"1865\">27</sup>, כולל ובמיוחד — הפצת פנימיות התורה כפי שנתגלתה בתורת חסידות חב\"ד, \"יתפרנסון<sup data-n=\"1866\">28</sup>\", באופן של הבנה והשגה בחב\"ד שבנפש,\nרחובות — ושמא מילתא היא<sup data-n=\"1867\">30</sup>, כי ירחיב הוי'<sup data-n=\"1868\">29</sup> בכל עניני הכינוס.\nויה\"ר שיקיימו שליחותם בשלימות המתאימה לפעולות הבאות לאחרי החלטות הכוללות ומוסיפות (כהציווי להעלות בקודש<sup data-n=\"1869\">31</sup>) על ההחלטות הקודמות, וכציווי יום כתיבת מכתב זה — יום טוב<sup data-n=\"1870\">32</sup>, יום הוספה חדשה, כאו\"א מוסיף מחדש ומוסיפים לו חיים (גשמיים ורוחניים) על חייו<sup data-n=\"1871\">33</sup>.\nובודאי תבואנה ברכות ה' לכאו\"א וב\"ב שי' — בשלימותם, שהרי כאו\"א פועל בכח ויכולת הכינוס וציבור<sup data-n=\"1872\">34</sup>, עשרה (ויותר) מישראל, מלכתחילה אַריבער<sup data-n=\"1873\">35</sup>, ויתירה מזה — בנתינה (בעין יפה<sup data-n=\"1874\">36</sup>) אל לבו מכל עניני התורה ומצוותי', שהם חיינו ואורך ימינו, ומתוך שמחת עצמו ושל אחרים, כמתאים לשנת תשמח (תי\"ו בחיריק) ותשמח (תי\"ו בשבא) כל בנ\"י האנשים והנשים והטף<sup data-n=\"1875\">37</sup>, כמתאים לשנת הקהל (האנשים והנשים והטף), ובהדגשה מיוחדת של חינוך דהטף, הילד והילדה — מתחיל מהחלטות לפועל בזה להכנסת כל ילד וילדה — שהם: בן אברהם יצחק ויעקב<sup data-n=\"1876\">38</sup> ובת שרה רבקה רחל ולאה — לחינוך על טהרת הקודש.",[["1863","25","<b>מבנ\"י, ארץ חפץ</b>: ראה מלאכי ג, יב. כש\"ט הוספות סמ\"ד. וש\"נ."],["1864","26","<b>בבית. . התיישבות וקביעות</b>: ראה שמואל­ב ז, ה­ז (בית לגבי אהל). מפרשים (חדא\"ג מהרש\"א, עיון יעקב לע\"י, ועוד) לפסחים פח, א (בית לגבי הר ושדה)."],["1865","27","<b>דחכמה בינה ודעת</b>: אמות ומקור למדות (תניא רפ\"ג)."],["1866","28","<b>יתפרנסון</b>: לשון התקו\"ז ת\"ו בסופו. וראה לקו\"ש חכ\"ד ע' 136 הע' 35. וש\"נ."],["1867","30","<b>ושמא מילתא היא</b>: ראה ברכות ז, ב: שמא גרים. יומא פג, ב: דייק בשמא."],["1868","29","<b>רחובות. . כי ירחיב הוי'</b>: ראה תולדות כו, כב."],["1869","31","<b>להעלות בקודש</b>: ברכות כח, א. וש\"נ. זח\"ג קסב, ריש ע\"ב. וראה לקו\"ש חי\"ג ע' 250 הערה ד\"ה זה."],["1870","32","<b>יום טוב</b>: משנה סוף תענית וגמרא שם. ותוד\"ה יום — שם ל, ב."],["1871","33","<b>מוסיף. . חיים. . על חייו</b>: שם לא, א ובפרש\"י שם."],["1872","34","<b>וציבור</b>: דעיקרו בארצנו הקדושה, משא\"כ בחו\"ל \"דלית נשיא עמן\" שיגזור עליהם (ירושלמי תענית רפ\"ב. הובא במג\"א סתקע\"ה סק\"י (ובמ\"מ לרמב\"ם תעניות ספ\"ג מהרמב\"ן — משא\"כ לרש\"י פסחים נד, ב. תוד\"ה אין, תענית יא, ב. מאירי שם. הגר\"א לאו\"ח סתקע\"ו סי\"ד. ואכ\"מ))."],["1873","35","<b>מלכתחילה אַריבער</b>: פתגם הידוע דאדמו\"ר מהר\"ש — הובא באגרות­קודש אדמו\"ר מוהריי\"צ ח\"א מכתב שמ."],["1874","36","<b>בנתינה (בעין יפה)</b>: ראה ב\"ב נג, א. וש\"נ. רמב\"ם הל' מכירה פכ\"ה ה\"ד. הל' זכי' ומתנה פי\"א הכ\"ב."],["1875","37","<b>הקהל (האנשים והנשים והטף)</b>: וילך לא, יב."],["1876","38","<b>בן אברהם יצחק ויעקב</b>: ראה ב\"מ פג, א (במשנה)."]]],[1301550343,"ובמהרה בימינו ממש — נזכה לברכה העיקרית: גאולה האמיתית והשלימה<sup data-n=\"1877\">39</sup> ע\"י משיח צדקנו, ולקיום ההבטחה: ולציון יאמר איש ואיש יולד בה והוא יכוננה עליון<sup data-n=\"1878\">40</sup>.\nותחזינה עיננו בחינוך בית הבחירה, מקדש אדנ-י כוננו ידיך<sup data-n=\"1879\">41</sup>.\nבברכת הצלחה בכל הנ\"ל\nמקום החתימה\n<hr>\nב\"ה, יום הראשון פ' ראה<sup data-n=\"1880\">1</sup>,\nי\"ט<sup data-n=\"1881\">2</sup> במנחם אב,\nחודש דמזלי' ארי', ארי' שאג<sup data-n=\"1882\">5</sup> מי לא<sup data-n=\"1883\">4</sup> יירא<sup data-n=\"1884\">3</sup>,\nה'תשמ\"ט, ברוקלין, נ.י.\nלכל המשתתפים בכינוס השלוחים העשירי,\nבארצנו הקדושה תובב\"א,\nה' עליהם יחיו\nשלום וברכה!\nבנועם קבלתי ההודעה ע\"ד קביעות זמן כינוס השלוחים העשירי בארצנו הקדושה, \"ביום הראשון לס' \"כי תעשה הטוב והישר<sup data-n=\"1885\">21</sup>\", ערב כ\"ף מנחם-אב — יום",[["1877","39","<b>גאולה האמיתית והשלימה</b>: שאין אחרי' גלות — מכילתא עה\"פ בשלח טו, ב. הובאה בתוד\"ה ה\"ג ונאמר — פסחים קטז, ב."],["1878","40","<b>ולציון. . עליון</b>: תהלים פז, ה."],["1879","41","<b>מקדש. . ידיך</b>: בשלח טו, יז ובפרש\"י. וראה פרש\"י סוכה מא, סע\"א. ועוד. זח\"ג רכא, א. יל\"ש תהלים רמז תתמח בסופו. וראה תקו\"ז תי' יב (כז, א). אוה\"ת בשלח ע' תקסד ואילך."],["1880","1","<b>פ' ראה</b>: ראה לקו\"ת ריש פרשתנו. לקו\"ש ח\"ב ע' 696. ח\"ד ס\"ע 1339 ואילך."],["1881","2","<b>י\"ט</b>: במעלת מספר זה — בגימטריא \"חוה\" — ראה תו\"א בראשית ו, רע\"ד. לקוטי לוי\"צ הערות אאמו\"ר לזהר (כרך ב) ע' קעא. ובכ\"מ."],["1882","5","<b>ארי' שאג</b>: וידוע הר\"ת דארי' אלול ר\"ה יוהכ\"פ הו\"ר (של\"ה ריש מס' ר\"ה (ריג, א). הובא ונתבאר באוה\"ת ר\"ה ע' א'תכב), עבודת התשובה, דבתשובה נגאלין (סנהדרין צז, ב. רמב\"ם הל' תשובה פ\"ז ה\"ה) וארי' יבנה אריאל (יל\"ש שם). ובלקו\"ת ר\"פ עקב: וגם ימים נוראים נקראים ע\"ש ארי' כי ארי' אותיות יראה (קה\"י ערך יראה)."],["1883","4","<b>ארי'. . יירא</b>: עמוס ג, ח."],["1884","3","<b>דמזלי'. . יירא</b>: ראה יל\"ש ירמי' בראשו ובתחלתו (רמז נטר)."],["1885","21","<b>כי. . והישר</b>: פרשת השבוע (ראה יב, כח) בו חל הכינוס. וראה ספרי ופרש\"י עה\"פ."]]],[1301550344,"ההילולא של הרה\"ג והרה\"ח המקובל מוהר\"ר לוי יצחק ז\"ל נ\"ע, אביו של — יבלח\"ט — כ\"ק אדמו\"ר שליט\"א, ברמת ישי<sup data-n=\"1886\">27</sup><sup data-n=\"1887\">6</sup>\",\nכינוס אשר קבעו הנושא שלו \"שנת הארבעים<sup data-n=\"1888\">7</sup>. . לב לדעת, עינים לראות ואזנים לשמוע<sup data-n=\"1889\">8</sup>\".\nויה\"ר שיהא בהצלחה רבה בכל — והרי הודיעה תורתנו תורת אמת בקשר לאבוהן דכל שלוחים, שהוא לכל לראש \"משה רבנו\", שליח למסור תורת השם ומצוותי': לכה ואשלחך גו' ואנכי אהי' גו' והוריתי אתכם את אשר תעשון<sup data-n=\"1890\">9</sup>,\nובפרט שבמשך כל השנה שעברה, שכוללת כל שינויים האפשריים<sup data-n=\"1891\">10</sup>, בטח פעלו בהתאם להחלטות כל הכינוסים הקודמים.\nובאופן דכינוס<sup data-n=\"1892\">11</sup> — דיש בזה זכות ותוקף דרבים<sup data-n=\"1893\">12</sup>, ויתירה מזה — דציבור, שהרי בודאי יתאחדו כולם למציאות (חדשה<sup data-n=\"1894\">13</sup>) אחת בלב אחד<sup data-n=\"1895\">14</sup> ע\"י אהבת ישראל ועד לאחדות ישראל,\nובתור שלוחים של אחד, כ\"ק מו\"ח אדמו\"ר, נשיא דורנו, שהנשיא הוא הכל<sup data-n=\"1896\">15</sup> —\nהעשירי — ומקרא מלא דבר הכתוב \"העשירי יהי' קודש<sup data-n=\"1897\">16</sup>\",",[["1886","27","<b>ישי</b>: ר\"ת יחד שבטי ישראל (ל' הכתוב — ברכה לג, ה), וי\"ל ע\"ד הרמז דע\"י הכינוס, שענינו אחדות ישראל, עי\"ז נעשה ביטול סיבת הגלות (יומא ט, ב), ועי\"ז בטל ממילא המסובב, ובא דוד מלכא משיחא (אשר ישי הוליד את דוד). ועי\"ז ביאת המשיח היא באופן ד\"רמת\" — באופן דזכו — אחישנה (סנהדרין צח, א)."],["1887","6","<b>ביום. . רמת ישי</b>: ל' ההזמנה השלוחה להשלוחים שי' — ובמילא חל על זה אריכות הביאור בתורת"],["1888","7","<b>שנת הארבעים</b>: ראה סה\"ש תשמ\"ט ח\"א ע' 200 ואילך. וש\"נ. שיחות יו\"ד, י\"ג וט\"ו בשבט תשמ\"ט. ועוד."],["1889","8","<b>לב. . לשמוע</b>: תבוא כט, ג. וראה ע\"ז ה, ריש ע\"ב. פרש\"י עה\"פ."],["1890","9","<b>לכה. . תעשון</b>: שמות ג, י. שם ד, טו."],["1891","10","<b>כל השנה. . שינויים האפשריים</b>: ראה ביאורי מעלת אתרוג שדר באילנו כו' (סוכה לה, א) — סידור (עם דא\"ח) שער הלולב רסא, ג ואילך. שם רסד, סע\"ד ואילך. המשך וככה תרל\"ז פפ\"ז. סה\"מ — מלוקט ח\"א ע' תמב. וש\"נ."],["1892","11","<b>ובאופן דכינוס</b>: מתורת הבעש\"ט בתכלית פגישת שני אנשים (כש\"ט — הוצאת קה\"ת — הוספות סקכ\"ו) מובן גודל הענין דפגישה בכינוס דרוב עם."],["1893","12","<b>זכות ותוקף דרבים</b>: ראה ברכות ח, רע\"א. שו\"ע אדה\"ז או\"ח ס\"צ ס\"י. וראה ד\"ה פדה בשלום לאדמו\"ר האמצעי פי\"ב (שער התשובה ח\"א — שער התפלה — נו, ג­ד). ד\"ה עשרה שיושבים, תרפ\"ח (סה\"מ תרפ\"ח ע' קמח ואילך). וראה קונטרס החלצו, תרנ\"ט פ\"י. וראה גם שם פ\"ז (סה\"מ תרנ\"ט ע' סא. שם ע' נט)."],["1894","13","<b>דציבור. . למציאות (חדשה)</b>: ראה צפע\"נ — כללי התורה והמצוה ערך צבור."],["1895","14","<b>יתאחדו. . בלב אחד</b>: כלשון המכילתא עה\"פ ויחן שם ישראל (יתרו יט, ב). פרש\"י שם. וראה תו\"א ס\"פ נח. מאמרי אדה\"ז — ענינים ע' פו ואילך (ועם הגהות — באוה\"ת נח כרך ג תרלב, ב ואילך). תו\"ח נח ד\"ה ויהי כל הארץ שפה אחת פמ\"ב (עד, א) ואילך. ועוד."],["1896","15","<b>שהנשיא הוא הכל</b>: פרש\"י עה\"פ חוקת כא, כא (מתנחומא חוקת כג). וראה רמב\"ם הל' מלכים פ\"ג ה\"ו: לבו (של מלך) הוא לב כל קהל ישראל. וראה לקו\"ש חי\"ט ע' 165 ואילך."],["1897","16","<b>העשירי יהי' קודש</b>: בחוקותי כז, לב. וראה זח\"ב רעא, א. פרדס שער ב (שער טעם האצילות). ראב\"ע עה\"פ שמות ג, טו."]]],[1301550345,"ביום הראשון הנקרא בתורה אור<sup data-n=\"1898\">18</sup>, ובה עצמה ב\"פתח דבריך יאיר<sup data-n=\"1899\">19</sup>\", יום אחד, שלא הי' בעולם אלא אחד<sup data-n=\"1900\">17</sup>, ונמשך בכל הימים שלאחרי זה ע\"י אשר \"אתה הראת לדעת כי הוי' הוא האלקים אין עוד מלבדו<sup data-n=\"1901\">20</sup>\",\nלס' \"כי תעשה הטוב והישר\", ציווי נתינת כח<sup data-n=\"1902\">22</sup> וגם הבטחה<sup data-n=\"1903\">23</sup> בזה, שזוהי כוונת ומטרת השליחות לפעול בכאו\"א מבנ\"י, בלשון רבותינו \"נרות להאיר<sup data-n=\"1904\">24</sup>\", להאיר נר מצוה ותורה אור<sup data-n=\"1905\">25</sup>, כולל ובמיוחד — הפצת מאור שבתורה, פנימיות<sup data-n=\"1906\">26</sup>,\nרמת ישי — לרמז אשר עי\"ז ירם קרן משיחו<sup data-n=\"1907\">28</sup>, מגזע ישי<sup data-n=\"1908\">29</sup>.\nויה\"ר שיקיימו שליחותם בשלימות המתאימה לפעולות הבאות לאחרי החלטות הכוללות ומוסיפות (כהציווי להעלות בקודש<sup data-n=\"1909\">30</sup>) על ההחלטות הקודמות, וכציווי יום כתיבת מכתב זה — יום ראשון, יום אחד, שאין בעולם כל בנ\"י אלא רשות יחידו של עולם<sup data-n=\"1910\">31</sup>.\nובודאי תבואנה ברכות ה' לכאו\"א וב\"ב שי' לאורך ימים ושנים טובות — בשלימותם, שהרי כאו\"א פועל בכח ויכולת הכינוס וציבור<sup data-n=\"1911\">32</sup>, עשר (ויותר) מישראל,",[["1898","18","<b>בתורה אור</b>: משלי ו, כג."],["1899","19","<b>פתח דבריך יאיר</b>: תהלים קיט, קל. וראה ב\"ר רפ\"ג. פרש\"י עה\"פ."],["1900","17","<b>הנקרא בתורה. . יום אחד. . אלא אחד</b>: בראשית א, ה. פרש\"י עה\"פ (בשם ב\"ר — פ\"ג, ח)."],["1901","20","<b>אתה. . מלבדו</b>: ואתחנן ד, לה."],["1902","22","<b>ציווי נתינת כח</b>: כי הרי אינו מבקש אלא לפי כחן — במדב\"ר פי\"ב, ג."],["1903","23","<b>ציווי. . וגם הבטחה</b>: דכל הציווים שבתורה הם לשון עתיד (הבטחה). וראה תו\"א ס\"פ תשא (פו, ג). או\"ת להה\"מ הוספות סי' יב (וש\"נ); סה\"מ תרכ\"ו ע' קיב ואילך; תר\"ל ע' קמ ואילך; שם ס\"ע קמח ואילך — בנוגע ל\"ואהבת\". ובלקו\"ת במדבר יג, ג: כי העתיד והציווי שניהם משמשין בלשון אחד."],["1904","24","<b>נרות להאיר</b>: ראה או\"ת להה\"מ (הוצאת קה\"ת) ס\"פ עקב."],["1905","25","<b>נר. . אור</b>: משלי שם. וראה ל\"ת להאריז\"ל עה\"פ. אוה\"ת נ\"ך עה\"פ (ס\"ע תקסח ואילך). וש\"נ."],["1906","26","<b>מאור שבתורה, פנימיות</b>: ראה קה\"ע לירושלמי חגיגה פ\"א ה\"ז. יפה ענף לאיכ\"ר פתיחתא ב. המשך תער\"ב ח\"ג ע' א'שכב."],["1907","28","<b>ירם קרן משיחו</b>: ל' הכתוב — שמואל­א ב, י."],["1908","29","<b>מגזע ישי</b>: ישעי' יא, א."],["1909","30","<b>להעלות בקודש</b>: ברכות כח, א. וש\"נ. זח\"ג קסב, ריש ע\"ב. וראה לקו\"ש חי\"ג ע' 250 הערה ד\"ה זה."],["1910","31","<b>רשות יחידו של עולם</b>: שהו\"ע \"רשות היחיד\" — ראה תניא ספל\"ג. לקו\"ת במדבר טז, א. ובכ\"מ."],["1911","32","<b>וציבור</b>: דעיקרו בארצנו הקדושה, משא\"כ בחו\"ל \"דלית נשיא עמן\" שיגזור עליהם (ירושלמי תענית רפ\"ב. הובא במג\"א סתקע\"ה סק\"י (ובמ\"מ לרמב\"ם תעניות ספ\"ג מהרמב\"ן — משא\"כ לרש\"י פסחים נד, ב. תוד\"ה אין, תענית יא, ב. מאירי שם. הגר\"א לאו\"ח סתקע\"ו סי\"ד. ואכ\"מ))."]]],[1301550346,"מלכתחילה אַריבער<sup data-n=\"1912\">33</sup>, ויתירה מזה — בנתינה (בעין יפה<sup data-n=\"1913\">34</sup>) אל לבו<sup data-n=\"1914\">35</sup> מכל עניני התורה ומצוותי', שהם חיינו ואורך ימינו, וכמתאים לשנת הארבעים אשר נתן ה' לכאו\"א לב לדעת עינים לראות ואזנים לשמוע,\nולמילוי תפלת כאו\"א, גם לשון הבטחה: תבוא לפניך תפלתי הטה אזנך לרינתי<sup data-n=\"1915\">36</sup>.\nובמהרה בימינו ממש — נזכה, ובמיוחד ע\"י הפצת המעיינות חוצה<sup data-n=\"1916\">37</sup>, לברכה העיקרית: גאולה האמיתית והשלימה<sup data-n=\"1917\">38</sup> ע\"י משיח צדקנו.\nותחזינה עיננו בחינוך בית הבחירה, מקדש אדנ-י כוננו ידיך<sup data-n=\"1918\">39</sup>.\nבברכת הצלחה<sup data-n=\"1919\">40</sup> בכל הנ\"ל\nהה\"מ (לקו\"א סרי\"ג — נב, א) ש\"כל המקריות שיקרה לאדם. . זהו כמשל מי שרואה במראה שרואה כנגדו פרצופו וכו'\" — בכל תיבה.\n<hr>",[["1912","33","<b>מלכתחילה אַריבער</b>: פתגם הידוע דאדמו\"ר מהר\"ש — הובא באגרות­קודש אדמו\"ר מוהריי\"צ ח\"א מכתב שמ."],["1913","34","<b>בנתינה (בעין יפה)</b>: ראה ב\"ב נג, א. וש\"נ. רמב\"ם הל' מכירה פכ\"ה ה\"ד. הל' זכי' ומתנה פי\"א הכ\"ב."],["1914","35","<b>בנתינה. . אל לבו</b>: ע\"פ ל' הכתוב (קהלת ז, ב) והחי יתן אל לבו."],["1915","36","<b>תבוא. . לרינתי</b>: תהלים פח, ג."],["1916","37","<b>ובמיוחד ע\"י הפצת המעיינות חוצה</b>: כהבטחת מלך המשיח להבעש\"ט — ראה אגה\"ק הידוע דהבעש\"ט — נדפסה גם בריש ספר כתר שם טוב. ובכ\"מ."],["1917","38","<b>גאולה האמיתית והשלימה</b>: שאין אחרי' גלות — מכילתא עה\"פ בשלח טו, ב. הובאה בתוד\"ה ה\"ג ונאמר — פסחים קטז, ב."],["1918","39","<b>מקדש. . ידיך</b>: בשלח טו, יז ובפרש\"י. וראה פרש\"י סוכה מא, סע\"א. ועוד. זח\"ג רכא, א. יל\"ש תהלים רמז תתמח בסופו. וראה תקו\"ז תי' יב (כז, א). אוה\"ת בשלח ע' תקסד ואילך."],["1919","40","<b>הצלחה</b>: ראה אוה\"ת וישב רעח, א­ב (עה\"פ ויהי ה' את יוסף ויהי איש מצליח)."]]],[1301550347,"<h3>ראה</h3>\nאין ענטפער אויף אייער בריף פון יום א' פרשת ראה אנכי נותן לפניכם היום ברכה,\nהשם יתברך זאָל ממשיך זיין זיינע ברכות צו אייך און צו יעדערן פון דער פאַמיליע שי' ברכה בטוב הנראה והנגלה, אַזוי אַז מיט שמחה וטוב לבב, אָן קיינע ענינים המבלבלים זאָל מען טאָן ווי דער המשך פון פסוק, תשמעו אל מצות ה' אלקיכם, אַ הנהגה אין דעם טאָג טעגליכען לעבען לויט די אָנווייזונגען פון תורתנו תורת חיים און מקיים זיין אירע מצות, אויף וועלכע עס שטייט, וחי בהם.\nאון איינגעשלאָסען אין דעם פאַרשטענדליך און פון די עיקרים אַז דער לערנען מיט די תלמידים בחינוך על טהרת הקדש זאָל זיין מיט אַ איבערגעגעבנהייט ומתוך שמחה.\nוואָס אויב מעט אור דוחה הרבה חשך, געמיינט יעדער זאַך וואָס האַלט אָפּ אַ אידן פון דינען השי\"ת צוזאַמען מיט זיינע בני בית, בשמחה ובטוב לבב, עאכו\"כ אַז אַנשטאָט מעט אור, איז דאָ הרבה אור, תורה אור, ומאור שבתורה, פנימיות התורה תורת החסידות, הנהגה באורח חסידותי ללמוד חסידות בעצמו ועם אחרים.\nאון עס זאָל מקוים ווערן, דער שמחנו כימות עניתנו, אַז פון איצטער אָן און ווייטער, אך טוב וחסד ושמחה זאל זיין באַ יעדערן פון אייך און באַ אַלעמען צוזאַמען.\nאון בפרט אַז מיר דערנענטערן זיך צום חדש אלול, חדש הרחמים וואָס ווי רבנו הזקן זאָגט, אַז דענסטמאָל איז הקב\"ה מקבל כל אחד ואחת בסבר פנים יפות (לקו\"ת ד\"ה אני לדודי) און קומט אַראָפּ עד למטה מעשרה טפחים. . .\n<span data-k=\"q\">(ממכתב כ\"ב מנ\"א תשכ\"ב)</span>\n<hr>\nבמענה על מכ' אשר בו מספר על דבר אחד ממכיריו, הנמצא בסביבת א\"י, ונוסע ביום השבת לעיר שבה נמצאים יהודים, כדי לאכול, עכ\"פ בש\"ק, בשר כשר ולבלות איזה שעות בחברת אחב\"י,\nושואל אם טוב עושה מכירו לחלל את השבת, כדי לאכול מאכל כשר ולחזק"],[1301550348,"חבל התקשרותו בסביבה יהודית.\nהנה כלל אמרו חכמינו ז\"ל — אשר ירדו לעומק נפשו של כאו\"א, אף שאין דעות בנ\"א דומות זל\"ז — אל תהי יושב ושוקל במצותי' של תורה. ואמרו הוי זהיר במצוה קלה כבחמורה, אף אם דנים ע\"ד מצות שאחת מהן קלה ואחת חמורה.\nובפרט בנידון זה של מכירו ששני הענינים חומר רב יש בהם.\nכי ידוע אשר מאכלות אסורות, הרי לבד גודל העונש בבא, הנה גם עתה תכונה יש בהם, אף שלא בכל דבר יש להשיגה ע\"פ השכל, אשר מטמטמים הם את הלב ומוח של האדם האוכלם, עד שעניני תומ\"צ ווערן עם פרעמד און ווייט, ער ווערט אַלץ גרעבער און חומריות'דיקער, עד שיוכל להיות נמשך, מצד התכונות שהטביעו המאכלות אסורות בגופו, לעניני אסור כאלו שמעולם לא הי' שייך אליהם ואשר נבזים הם בעיניו ע\"ע גם מצד האנושיות ותורת המוסר.\nובגודל ערך קדושת השבת, הרי למותר להאריך במפורש בתנ\"ך ובדרז\"ל, אשר אות היא בין ה' ובינינו, ושמירתה היא ההכרזה וההודעה, אשר ה' ברא את העולם ומלואו והוא מקיימו ומנהיגו בכל עת ובכל רגע, גם עתה, אשר לכן אמרז\"ל שהמחלל שבת ועכו\"ם שתיהן שקולות כנגד שאר כל מצות התורה.\nומשל למה הנהגת מכירו דומה, למי שאירע בביתו שריפה גדולה, ר\"ל, עד שסכנה נשקפת לחייו, ו\"מכבה\" הוא את האש, ע\"י ש[שו]פך עליו נאַפט ופּעטראָלעאום!\nצריך לפקוח עיני מכירו ולהכירו מצבו הפרטי, ומצב כל עם ישראל — שכל ישראל ערבים זב\"ז — בכלל,\nמצב אחב\"י מעבר לים נורא הוא, וה' ברחמיו הרבים יאמר לצרותיהם די, ולא יתן לרעה להתפשט ח\"ו וח\"ו.\nאבל עלינו לדעת את חובתנו לה', חובתנו לעצמנו לב\"ב ולכל אחב\"י, לעמוד חזק בקיום התומ\"צ, ולהתגבר על כל מניעה ועיכוב בשמירתם.\nואף אם נדמה למכירו ששמירת מצוה זו או אחרת דבר שא\"א הוא במצבו עתה, הנה אם יתבונן בזה, כאדם המתעמק בדבר הנוגע לחיי נפשו, הנה בודאי ימצא דרך ואופן לקיום המצוה ולשמור על טהרת גופו ונפשו בכל שבעת ימי השבוע, ולא ע\"י קביעות סדר של חילול שבת בכל שבת ושבת.\nומצוה גוררת מצוה להיות קשור לעמו לדתו ולתורתו, דאורייתא ק' וישראל כ\"ח.\n<span data-k=\"q\">(ממכתב תש\"ב-תש\"ה)</span>\n<hr>"],[1301550349,"מאשר הנני קבלת מכתבו מא' משפטים, וכן ספרו נצני ניסן.\nויהי רצון אשר ימלא השי\"ת משאלות לבבו לטובה להצליח בחיזוק הכשרות במחנו הט' ובכל מקום שידו מגעת, ולהשפיע גם על אחרים בזה.\nובפרט ע\"פ המבואר בכ\"מ, אשר מהטעמים בכשרות המאכלים הוא, שמאכל בלתי כשר מטמטם הלב והמוח וכו' שמזה מובן שחיזוק בענין הכשרות הרי נוגע הוא לכל התורה ומצותי' וק\"ל.\nומענין לענין באותו ענין, מכשרות מאכלי הגוף לכשרות מאכלי הנפש, דיעות הטובות והפכם, היינו אשר מוחין שבראשו יהיו ממולאים מחב\"ד שבתורה, חכמת ה' ובינתו וכו' ולהוליד מהם מדות טובות בלבו, שבזה תלוי' הנהגת האדם לימוד התורה וקיום מצותי' ועד לקיום מ\"ש בכל דרכיך דעהו.\nשעפי\"ז מובן ביותר ענין החובה על כאו\"א בהפצת תורת חסידות חב\"ד ועד שתגיע גם — אל מה שלע\"ע עדיין הוא — חוצה.\n<span data-k=\"q\">(ממכתב ב' אדר תשכ\"ו)</span>\n<hr>\n... לשאלתו למנהגנו בנוגע לאכילת בשר לאחרי מאכלי חלב, בכלל נהגינן בהנ\"ל — ואפילו לאחרי חלב וחמאה — להמתין שעה (וגם — לא באותה הסעודה). וכ\"כ בשל\"ה מס' שבועות שלו (קפ, ב). — (ומש\"כ בדרכי תשובה יו\"ד ספ\"ט סוס\"ק י\"ט \"שעה ויותר\" צ\"ע שיעורא דויותר, והמקור ע\"ז) — אבל לא שמעתי אם זוהי הוראה לכל או רק מנהג יחידי סגולה, וראה פמ\"ג לשו\"ע יו\"ד ספ\"ט, שפתי דעת סק\"ז, דהפסק שעה — מחליף קינוח. . .\nנתעכב המכתב במשלוח, וז\"ע נתקבל מכתבו מעש\"ק, בו מעתיק מספר א' מקור למנהג אלו שממתינים חצי שעה לאחרי אכילת חלב וחמאה,\nמהשיעור בהנוגע לשלילת עשיית מלאכה קודם התפלה, שהלשון במשנה סמוך למנחה, והשיעור, כמבואר בפוסקים, חצי שעה, שבהפסק שיעור זה — פסקה הסמיכות.\nוכבוד בעל המחבר במקומו מונח, כי (עכ\"פ — כפי שהעתיק במכתבו) עיקר הראי' חסר, שהרי בנוגע לאכילת חלב ובשר לא מצאתי — לע\"ע — הלשון דסמוך כ\"א \"כחדא או בשעתא חדא או בסעודתא חדא\" (זהר ח\"ב קכ\"ה ע\"א). ואם נחפש דוקא למצוא סמוכים, הרי כל לשונות הנ\"ל שבזהר — קרובים יותר להלשון תיכף (ועוד יותר מזה כמובן). ושיעור תיכף — הרי הוא מהלך כ\"ב אמה, כפס\"ד בשו\"ע"],[1301550350,"או\"ח סי' קס\"ו. ולא עוד, אלא שגם מיקרי הפסק.\nלמש\"כ בדר\"ת הנ\"ל להמתין שעה ויותר — יש להעיר משיעור עיכול שהוא מהלך ד' מילין (עיין נ\"כ השו\"ע או\"ח סו\"ס קפ\"ד).\n<span data-k=\"q\">(ממכתב י\"ט תמוז תשכ\"א)</span>\n<hr>\n... ונעם לי להודע מהצלחת פעולתו בהנוגע לחלב ישראל במחנם הט' ובפרט ע\"פ סיפור הידוע מרבותינו נשיאינו<sup data-n=\"1920\">*</sup>, איך שחלב ישראל דוקא נוגע לחיזוק האמונה, וחלב שחלבו עכו\"ם ואין ישראל רואהו, מביא ח\"ו לספיקות באמונה, וק\"ל.\nויהי רצון שתהי' הצלחה מלאה בהאמור וזכות הרבים מסייע אותו וכל אלה המשתדלים בזה. . .\n<span data-k=\"q\">(ממכתב ט\"ז שבט תשכ\"ב)</span>\n<hr>\n... וואָס איר שרייבט אין דעם ענין פון חלב ישראל, — וויבאַלד מ'קען דאָך דורכקאָכען וכו' איז אויף דעם וועג פיל בעסער און געזינטער איידער דער פראָצעס פון פּאַסטערייז וכו' ובפרט אַז ס'איז דאָך באַוואוסט דער סיפור וואָס מיר האָבען געהערט פון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, וועגען דער גרויסער וויכטיקייט אַז עס זאָל זיין דוקא חלב ישראל.\n<span data-k=\"q\">(ממכתב ה' אייר תש\"כ)</span>\n<hr>",[["1920","*","ראה סה\"מ אידיש ע' 57. המו\"ל."]]],[1301550351,"... לשאלתו בדבר הצדקה — כנראה כוונתו למה שנדר בעת החולי — ומחמת חולי —\nידוע מאמר חז\"ל, אמירתו לגבוה כמסירתו להדיוט, ז.א. שאין לזה שייכות למה שהיורשים עושים לזכות ועילוי הנשמה או שמפרישים מהעזבון לעניני צדקה, ובמילא באם פונים אליהם מישיבת ת\"א בנוגע להעזבון והירושה, אין לזה שייכות להצדקה לנדר האמור, וק\"ל. . .\n<span data-k=\"q\">(ממכתב י\"ד אד\"ר תשכ\"ב)</span>\n<hr>\n... מה שהעיר בשולי מכתבו בענין החפזון, הנה מבואר בדא\"ח דיש בזה — לפעמים — מעלה, וכמו בחפזון דיצי\"מ וכי ברח העם (יעויין תניא פל\"א של\"ה מס' פסחים ד\"ג), ומבואר בד\"ה וככה תרל\"ז בארוכה דהיינו כל זמן שלא נגמרו הבירורים, ולכן לע\"ל, אדרבה, המעלה היא דלא בחפזון תלכו גו'. ועייג\"כ שיחת חה\"פ תש\"ג ס\"ב.\nוע\"ד הצחות י\"ל, שגם עתה כן צ\"ל — לא בחפזון — בכל השייך לקבלה וחסידות, שנק' עץ חיים, למע' מבירורים (עיין אגה\"ק סי' כ\"ו, הקדמה לבאוה\"ז, קונ' עץ [ה]חיים לאדנ\"ע ועוד).\nוצע\"ק במה שנשתבחו ישראל במ\"ת עמא פזיזא (שבת פח, א, שגם רבא הסכים ע\"ז) אף שאז הי' חרות מיצה\"ר.\n<span data-k=\"q\">(ממכתב יום ג', ב' שבט תש\"ה)</span>\n<hr>\n... צום אינהאַלט פון אייער בריף, וועגען דער מצוה פון עלי' לרגל.\nוויל איך זיין שטאַרק אין האָפענונג, וויבאַלד אַז איר טוט שרייבט אַזוי בנוגע אַ מצוה, וואָס פאַר אידען וועלכע געפינען זיך אין חוץ לארץ בזמן שבית המקדש הי' קיים, און ווער רעדט אַז משחרב בית המקדש, פאַר אַלע אידען, איז די מצוה זיכער ניט מדאורייתא, איז דאָך מכל שכן וקל וחומר אַז איר וועט טאָן מכאן ולהבא, אַלעס וואָס עס היינגט אָפ פון אייך, צו מקיים זיין די מצוה פון ואהבת לרעך כמוך,"],[1301550352,"וכביאור חכמנו ז\"ל אַז דאָס ענטהאַלט אויך, אַזוי ווי מ'וויל טאָן פאַר זיך, צו אויפפירען זיך אין טאָג טעגליכען לעבען לויט די אָנווייזונגען פון תורתנו הק' תורת חיים ובקיום מצותי' עליהם נאמר וחי בהם, דאַרפמען אויך אַזוי טאָן, בדרכי נועם, אַז אַלע אַרום זיך זאָלען מקיים זיין די אַלע מצות וועלכע זיינען זיכער מדאורייתא, אַלע מצות וועלכע זיינען מדרבנן, און דערנאָך אויך צוטרייען זיי צו הידור מצוה וכו' וכו' און מיר זיינען פאַרזיכערט געוואָרען, אַז דברים היוצאין מן הלב נכנסים אל הלב.\nאון לויט ווי איך האָב געהערט, אַז אין פּאַסייעק איז דאָ פיל צו אויפטאָן בנוגע חינוך על טהרת הקדש, וואָס פילע קינדער האָבען פאָרלויפיג נאָך ניט אַזאַ חינוך און אַזוי אויך צו אַנדערע ענינים על טהרת הקדש וכו' און איך האָף אַז ווי געזאָגט איר וועט טאָן אין דעם מיט גרויס ענערגיע והשי\"ת יצליחו. . .\n<span data-k=\"q\">(ממכתב י\"ח ניסן תשכ\"ב)</span>\n<hr>"],[1301550353,"<h3>אלול</h3>\n... ובפרט אשר יצאנו כבר מימים הראשונים דחדש מנ\"א ונכנסנו לימי הנחמה ומהם לחדש אלול חדש הרחמים רחמיו המרובים של יוצר האדם ומשגיח עליו בעין פקיחה ועין טובה וזן ומפרנס כל צרכיו הן בגשם והן ברוח ובאור פני מלך (מה\"מ) חיים, (וכל צרכי החיים) וע\"פ המבואר בזהר הק' עלמא עילאה כגוונא דעלמא תתאה, ואור פני האדם למטה ממשיך אור ברכה וישועה מעולם העליון.\n<span data-k=\"q\">(ממכתב י\"ד מנ\"א תשכ\"ד)</span>\n<hr>\n... וכמנהג בני ישראל לסיים מענינא דיומא, שמתקרבים אנו לראש חודש אלול, חודש הרחמים והרצון, ובפרט ע\"פ המובא מרבנו הזקן שאלו\"ל ר\"ת אני לדודי ודודי לי, שהמלך נמצא בשדה (לקו\"ת ד\"ה אני לדודי לב, ב'),\nיהי רצון שלמרות ההשתדלות בימים אלו לפרד הלבבות ולרחק אפילו קרובים, יתקרבו כל בני ישראל, בכל מקום שהם, אחד לאחד,\nובסגנון המסורתי, יעשו כולם אגודה אחת לעבדו ית' בלבב שלם,\nוכדרישת תורת החסידות — מתוך שמחה וטוב לבב.\n<span data-k=\"q\">(ממכתב כ\"ה מנ\"א תשכ\"א)</span>\n<hr>"],[1301550354,"<h3>שופטים</h3>\nביום זה הוא יום \"ראשית הגז\" של בנו שי', הנני לאחל אשר כל ברכות כ\"ק מו\"ח אדמו\"ר שליט\"א יקויימו במילואן, והוא וביתו יחיו יגדלו את בנם לתורה חופה ומעשים טובים. ובמהרה בימינו בעגלא דידן יוחזרו מתנות כהונה על מכונם, בבנין בית המקדש ועינינו תחזינה.\nבפ\"ש חותנו הרה\"ח וכו' הר\"ד שי' הלוי (וכתב האר\"י ז\"ל ע\"פ והכהנים הלוים שהלוים של עכשיו יהיו כהנים לעתיד, \"שהעולם יתעלה\" — תניא פ\"נ) ופ\"ש כב\"ב יחיו. . .\n<span data-k=\"q\">(ממכתב שושן פורים תש\"ט)</span>\n<hr>\n... כדאי אשר לערך כשנה — תפסיק לגמרי מעשיית \"חשבון\" חי' והיחסים אלי' ויחסה להעולם וכו'\nותקיים בפשטות מה שנאמר בתורתנו תורת חיים תמים תהי' עם השם — היינו חיי עקרת הבית בפשטות:\nכשרות האכו\"ש, טהרת המשפחה, הכנסת אורחים שיעורי חת\"ת וכו' וכנ\"ל כל זה בפשטות ממש — וכשתבוא מחשבה קשורה לחקירות בנפשה תענה לעצמה בהחלטיות ומבלי להכנס לפלפול כלל וכלל — שבזה תתענין לא קודם משנת תשמ\"ח — ועתה שליחותה שיהי' ביתה וחיי' דוקא בפשטות ובתמימות ומתוך שמחה.\n<span data-k=\"q\">(ממכתב כ' אלול תשמ\"ו)</span>\n<hr>\n... לשאלתה פירוש לתאריכי מאורעות כו'\nאמרה תורה (גם מלשון הוראה): תמים תהי' עם ה' אלקיך,"],[1301550355,"ובודאי השם עושה (בל' הכתוב) הכל יפה בעתו.\nולא כדאי לבזבז זמן חיפוש פירוש על הנ\"ל, כי אם רק — להפצת היהדות וקיום מצותי'.\n<span data-k=\"q\">(ממכתב ט\"ז אד\"ר תשמ\"ו)</span>\n<hr>\nבמענה על מכתבו, בו כותב ראשי פר[ק]ים מעבודתו בתור רב צבאי, ושואל הוראות איך יצליח בשליחותו,\nהנה על יסוד פעולות צעירי אגודת חב\"ד, שהי' להם נסיון משך כמה שנים, בביקורים במחנות צבא ובפגישות עם סטודנטים וכדומה, יש להציע הנקודות דלהלן:\nא. בשים לב לקוצר הזמן, כמו שכת\"ר שי' כותב, שנשארו לו רק מספר חדשים במקום — מחד, ואשר רוב אנשי הצבא היהודים אשר באים לשם נשארים רק ששה שבועות — מאידך, קשה לתכנן תכנית של עבודה ההולכת ומתקדמת מדרגה לדרגה וכו'. ולכן, קודם כל, צריך להשתדל לעורר התעוררות כללית בדברים היוצאים מן הלב ונכנסים אל הלב, באופן שכל אחד ואחד ישאל את עצמו מהו תפקידו בתור יהודי, ומה עליו לעשות למלא תפקידו, ועד כמה ממלא הוא את חובתו בזה. והעיקר לעורר בו תשוקה למלא תפקידו, שאם יהי' בו הרצון ויכיר את מעלתו וגאונו להיות יהודי, במילא ישתדל בעצמו להרחיב ידיעותיו גם לאחרי שיצא מתחת השפעת כת\"ר, והרי השפעת כת\"ר תהי' מנקרת בו גם אח\"כ.\nב. כדי שההשפעה לא תשאר בעולם הדיבור בעלמא, צריך להגיע לידי דבר ממשי בפועל, היינו מצוה מעשית בכל יום; שמלבד תועלת של כל דבר בפועל כמו שהוא לעצמו, הרי עוד זאת שמצוה גוררת מצוה. ויתר על כן, שהפועל-ממש שיגיע אליו המושפע יזכירו בתמידות אותם דברים המלבבים שהביאוהו לידי הפועל ממש. כגון הנחת תפילין בכל יום חול, ולכל הפחות לרגעים אחדים, קריאת שמע, הפרשת פרוטה לצדקה בכל בוקר חול, וכדומה.\nג. בנוגע אלה בעלי משפחה (רופאים וכו') הבאים לשם לשנה ויותר, כמובן שצריך לסדר תכנית מסודרת בקביעת עתים לתורה, ובשמירת המצוות, כגון כשרות, תפילין לגברים, טהרת המשפחה וכולי; ובפרט חינוך הילדים.\nד. צריך לשים לב לזה שלפעמים יש בין אנשי הצבא בחורים הבאים מחוגים שומרי מצוות, אלא חושבים שבצבא פטורים הם מעול מצוות, משום קושי וכו'. והרי ידוע שאדרבה, יש אפשרות בצבא לקיים המצוות; ועוד זאת שצריך להשפיע על"],[1301550356,"אלה שיכירו באחריות והזכות שיש להם להשפיע על זולתם, ומי יודע אם אין זה תפקידם העקרי שנתגלגלו למחנה פלוני בין חברים חדשים, וכו'.\nכיון שכת\"ר כותב שנשארו לו שם רק חדשים מספר, בודאי יוסיף אומץ בהשפעתו, באופן שכשיבוא ממלא מקומו יוכל לא רק למסור לו תכנית עבודה בפועל להמשיך בה, אלא גם להצביע על הצלחה ופירות מהשפעתו.\nבאם נצרך לסיוע נוסף, או עניני דפוס, וכיו\"ב, יוכל לפנות ישר לצעירי אגודת חב\"ד, ואולי יוכלו לסדר ביקור מאחד מחבריהם במחנה שלו אם יהי' בזה תועלת מיוחדת.\n<span data-k=\"q\">(ממכתב י\"ח שבט תשכ\"ה)</span>\n<hr>\n... — ובטח למותר להדגיש על הכרח הנהגה בחיי היום יומים שתהא מתאימה להוראות תורתנו תורת חיים וקיום מצותי' עליהם נאמר וחי בהם, שנוסף על העיקר שכן הוא ציווי הקב\"ה, הרי זה גם הדרך לקבלת הברכה בהמצטרך להאדם.\nובפרט כשנמצאים בצבא — הזקוק תמיד לברכה במיוחד מאלקי הצבאות, שהוא הוא נותן התורה ומצווה המצות, הרי זה נוגע ישירות בתוקף ובבטחון הצבא.\nופגיעה, ח\"ו בתוקף הצבא מחלישה הצבא, ר\"ל, אפילו אם הפגיעה היא מחוסר ידיעה ולא בזדון, כמובן.\n<span data-k=\"q\">(ממכתב ימי הסליחות תשמ\"ו)</span>\n<hr>\nדורך. . . האָב איך באַקומען אַ גרוס פון אייך. אויך שרייבט מיר. . . אַז אייער זון. . . שי' געפינט [זיך] אין מיליטער דינסט.\nזיכער איז איבעריג צו אויפמערקזאַם מאַכען אייך, צו ערוועקען אייער זון שי' און ערקלערען עם וועגען דעם קיום פון תורה ומצות בכלל אויף וויפיל עס איז דורכאויס נויטיג פאַר יעדער אידן, און בפרט פאַר אַזאַ וועלכער געפינט זיך אין מיליטער דינסט. און ספּעציעל איז דורכאויס אומבאַדינגט נויטיג צו אָפּהיטען לייגען תפילין יעדער וואָכען טאָג, לכל הפחות אויף עטליכע מינוט, אין פאַרלויף פון גאַנצען טאָג ביז זון אונטערגאַנג, וואָס דאָס איז אַ סגולה פאַר אַזאַ וועלכער"],[1301550357,"געפינט זיך אין מיליטער דינסט, צו קומען גאַנצערהייט און געזונטערהייט צוריק אַהיים, ווי מיר האָבען דאָס געהערט מערערע מאָל פון מיין שווער כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, און תודה לא-ל, אָט די אַלע וועלכע זיינען געווען אין מיליטער אין דער פאָריגער מלחמה און האָבען אויסגעפאָלגט מיין שווערס כ\"ק אדמו\"ר אָנזאָג וועגען לייגען תפילין זיינען געקומען גאַנצערהייט און געזונטערהייט אַהיים, ווי בכלל — ווען מען איז מקיים תורה ומצות, טוט מען דאָס ניט אַ טובה להשם יתברך, נאָר טאַקע זיך אַליין דער פאַמיליע און דער גאַנצער אומגעבונג. און איך האָף אַז איר וועט געפינען די פּאַסענדע ווערטער ווי צו ערקלערען דאָס אייער זון שי' און אויך צו איינווירקען אויף עם, פאַר זיין אייגענער טובה וועגען, און השי\"ת זאָל העלפען עס זאָל אייך אָנקומען גרינג און זאָלט קענען אָנזאָגען מיר אַ גוטע בשורה וועגען דעם.\nבברכה,\nנ\"ב. בייגעלייגט איז אַ מעסעדזש וועלכען מיין שווער כ\"ק אדמו\"ר האָט געשריבען — זיינער צייט — ספּעציעל פאַר די וועלכע האָבען זיך געפונען אין דער אַרמיי.\n<span data-k=\"q\">(ממכתב כ\"ד סיון תשי\"ג)</span>\n<hr>\nנתקבלה בקשתו לברכה בעד בנו אשר בצבא. . . ואזכירו בעת רצון על הציון שהשי\"ת ישמרהו בכל מקום שהוא וישוב לביתו שלום בעתו.\nבטח מצדו יסביר לבנו שי' אשר כדי להמשיך ולקבל ברכות השי\"ת צריך לעשות צנורות וכלים לזה שזהו ההנהגה על פי התורה ומצוותי', ואשר גם בהיותו בצבא אפשר להתנהג על פי התורה בהתאם לשיטת הדמוקרטי' של מדינה זו. ורשום למטה מאמרים בענין זה אשר כדאי לבנו שי' לקראם.\nובפרט צריך לחקוק על לוח לבו של בנו שי' החיוב להניח תפילין בכל יום שלזה צריך רק רגעים אחדים, ואם אי אפשר לעשות כן בבקר, הרי זמנו כל היום הוא, ומלבד חובת גברא שבזה הרי סגולה במצות תפילין לשמור על אחב\"י בצבא, וכמו שידוע לנו מהמלחמה האחרונה אשר כל אלה שפנו לכ\"ק מו\"ח אדמו\"ר [זצוקללה\"ה נבג\"מ זי\"ע] לברכה ושמרו פקודתו להניח תפילין בכל יום ששבו הביתה לשלום.\n<span data-k=\"q\">(ממכתב ח\"י מנחם אב תשי\"ד)</span>\n<hr>"],[1301550358,"<h3>תצא</h3>\nראה<sup data-n=\"1921\">*</sup> גם ע\"פ נגלה בס' החינוך ועוד.\nכוונתו רצוי' וכו' אבל מעולם לא שמעתי שיחפשו זה (ובכיו\"ב גם לא שמענו ראי', כמבואר בפוסקים), וע\"ד הצחות להעיר ממרז\"ל פרט למזומן (טושו\"ע יו\"ד סרצ\"ב).\nכפשוט כתוב הנ\"ל ע\"מ שלא לעשות מזה מחלוקת וכו'.\nיברר דעת מבין שאינו נוגע בדבר — ובאם יאשר שהמצב כנ\"ל —\nאזי יעשה כרצונו שכותבו.\n<span data-k=\"q\">(ממכתב כ\"ק אדמו\"ר שליט\"א)</span>\n<hr>\n... במענה לשאלותיו: בנוגע לבתו תי' — הרי דתיות פטורות מגיוס (ע\"פ מש\"נ דברים כב, ה. שם כג, י. טו). והאומרות שאעפ\"כ כיון שרוצות הן לעזור לאה\"ק — לכן תתגייסנה, הנה ע\"פ מש\"נ כנ\"ל — הוא בדוגמת הרוצה לכבות שריפה, ר\"ל, ע\"י שפיכת נפט, מכיון שגם זה. . נוזל כמים. וד\"ל.\n<span data-k=\"q\">(ממכתב ז' שבט תשכ\"ד)</span>\n<hr>\nבנועם ובשעתו קבלתי מכתבו מח\"י מנ\"א, בו מודיע אשר ביום ד' אלול הבע\"ל תהי' חתונת בנו בכורו שליט\"א:\nוהנני בזה להביע ברכותי מקול\"ע, ברכת מזל טוב מזל טוב, שתהי' החתונה בשעה טובה ומוצלחת ויעלה הזיווג ליפה ויבנו בנין עדי עד על יסודי התורה",[["1921","*","מענה בנוגע לקיום מצות שילוח הקן (בזה\"ז) וכו'. המו\"ל."]]],[1301550359,"והמצוה כפי שנתבארו בתורת החסידות הוא תורת דא\"ח, ויראו מהם ומשאר ילידיהם שי' רוב נחת ועונג בגשמיות וברוחניות גם יחד.\nידוע אשר ענין הזיווג הוא למעלה מסדר ההשתלשלות, וכמרז\"ל שדומה לקרי\"ס, דבעתיקא תליא מילתא, היינו שזהו המשכה מאור המקיף.\nוי\"ל שזהו שמצינו בענין הנשואין ענין המקיפים: א) מקיף ע\"ג הכלה לבד, שזהו ענין נתינת הטבעת,\nוכידוע, שאף שבמשנה אי' נקנית בכסף אבל כבר אמרו בתקו\"ז תיקון ה' בתחלתו ותיקון יו\"ד ותיקון כ\"א (נ\"ה ע\"ב): ובגינא איתמר לגבי כלה תהא לי מקודשת בטבעת זו, וכדאי' ג\"כ בכמה מקומות אשר בני ארץ ישראל מקדשים בטבעת (חילוף מנהגים שבין בני בבל לארץ ישראל, בים של שלמה, ובכ\"מ).\nאשר נתינת הטבעת הוא מקיף על (אצבע) הכלה ובא מהחתן.\n[ב)] הכלה מסובבת את החתן ז' פעמים, שזהו מקיף על החתן הבא מהכלה. וע\"ד דלע\"ל נקבה תסובב גבר.\nושני מקיפים אלו באים תחת החופה, שזהו מקיף כללי על החתן והכלה גם יחד, היינו מקיף בינה לזו\"נ, ומבואר הענין בלקו\"ת שה\"ש ד\"ה על כל כבוד חופה, ואין כאן מקום להאריך.\nהחותם מעין הפתיחה בברכת מז\"ט מז\"ט, ש\"ב מכבדו ומוקירו.\n<span data-k=\"q\">(ממכתב כ\"ה מנ\"א תשי\"א)</span>\n<hr>\nנ\"ב: בתור דרשה געשאַנק, מוסג\"פ סערטיפיקאט על חבילה. וענין השייכות דדרשה געשאַנק למקיף יעויין לקו\"ת פ' נשא דכ\"ט ע\"ב.\n... להשמועה בשם הרגוצבי<sup data-n=\"1922\">*</sup>: ראי' דבע\"ת גדולים מצד\"ג מקדושין (מט, ב) — גם אני שמעתי', אבל נ\"ל דאינה אמיתית, שהרי המקדש ע\"מ שאני לוי ונמצא כהן ג\"כ אינה מקודשת. [והטעם בקידושין עכצ\"ל מפני שבלשון בנ\"א גם בע\"ת נקרא צדיק. וגם בל' חז\"ל בל' המושאל שהרי זכה בדין — תניא פ\"א].\n<span data-k=\"q\">(ממכתב יו\"ד כסלו תשכ\"ה)</span>\n<hr>",[["1922","*","ראה גם לקו\"ש חי\"ד ע' 363. חי\"ז ע' 186 הערה 46­45. המו\"ל."]]],[1301550360,"1) א\"כ<sup data-n=\"1923\">*</sup> אף שצ\"ל טעם הדבר, אבל למעשה — אין נפק\"מ.\n2) לא<sup data-n=\"1924\">**</sup> שמעתי בכ\"ז — אבל הרואה בפועל ממש למה נשתלשלו בימינו אלה בפועל בכו\"כ חתונות — רואה הטעם.\n3) גבוה<sup data-n=\"1925\">***</sup> מזה מפורש בתורתנו הנצחית בנוגע למצבה החביבה בימי האבות (ועד\"ז אבותינו כפשוטם) ובכ\"ז אמחז\"ל כו'.\n<span data-k=\"q\">(ממענה בערך שנת תשמ\"ו-ז) </span>\n<hr>\nבנוגע<sup data-n=\"1926\">*</sup> לניקוד שמח תשמח — כמדומה ברור שאומרים שמח כולו פתח. לא העירותי עד\"ז בסי' כי רשום בזכרוני שיש מכ' כ\"ק מו\"ח אדמו\"ר והנני מחפשו.\n<span data-k=\"q\">(ממכתב תחילת אלול תשכ\"ה) </span>\n<hr>\nהגיעתני שמועה אשר כאילו יש נוהגים בקהלתם-קדישא במסיבת רבים (אנשים ונשים), ובפרט לפני חופה ולאחרי' בסעודת הנשואין, אשר אשה ג\"כ מנגנת, אם מברכות הקבועות או ברכה סתם, אבל בכל אופן בקול ניגון.\nומובנת הפליאה והתמי' שעוררה אצלי ידיעה זו, שהרי ידועים דברי חכמינו ז\"ל בזה בכמה מקומות (ומהם בתחילת הש\"ס במסכת ברכות כד, א ובפוסקים) ששוללים את האמור בתכלית ובהחלט.\nוביותר גדולה הפליאה בידעי חביבותו של ספר הזהר הקדוש בתוככי אחינו בני ישראל הספרדים, שהרי גם בזהר הקדוש פ' נשא, בקדש הקדשים בו — באידרא רבא קדישא שם (דף קמב, רע\"א) הפליגו בשלילת ענין האמור.",[["1923","*","מענה על השאלה: למה אין נוהגים חסידי חב\"ד ב\"מצוה טאַנץ\" הנזכר בכמה ספרים. המו\"ל."],["1924","**","הנ\"ל הביא מספרים שמזכירים המנהג. המו\"ל."],["1925","***","הנ\"ל כ' שבספרים קדושים כ' ע\"ז \"טעם כמוס יש בדבר בגנזי הנסתרות לה\"א\". המו\"ל."],["1926","*","ראה בזה לקו\"ש חכ\"ט ס\"ע 455. המו\"ל."]]],[1301550361,"ואם בכל מקום ומצב הדברים אמורים, על אחת כמה וכמה ברבים, ובענין השייך לנשואי בן ובת ישראל, שבזה ביחוד הדגישו חכמינו ז\"ל איש ואשה זכו שכינה ביניהם, ואף כי בתחילת ויסוד הענין — בשעת הארוסין קדושין ונשואין, אשר אז הונח היסוד לבנין עדי עד, והתחלת ברכות נשואין היא שהכל ברא לכבודו<sup data-n=\"1927\">1</sup>, וסיומן בברכות רבות לחתן וכלה וכולי, עד שאומרים אשר אז השמחה במעונו<sup data-n=\"1928\">2</sup> — במעונו של השם יתברך ויתעלה — הרי בודאי ובודאי שצריכה להיות טהרה יתרה וקדושה יתרה, ועד כדי כך שיהי' מתאים לדוגמא (בנוסח שקבעו אנשי כנסת הגדולה בברכות האמורות) לכשמחך יצירך בגן עדן מקדם (קודם חטא הראשון וכו'). ועוד זאת — שהזמן אז אך ורק לרחמים ולברכה ולחסד, הרי נוסף על שלילת הענין בהחלט מצד עצמו, נתוסף שהענין — כלשון האידרא רבא קדישא — הוא דינין (ועוד) שהם מתפשטין ברמ\"ח אורחין, ולא עוד אלא שהתחלתם בראשית מדון<sup data-n=\"1929\">3</sup> — הוא קול באשה, וכל' חכמינו ז\"ל שם: תני כו' ודינין ה' אתפשטן ברמ\"ח אורחין והכי תאנא קול כו' שער כו'. עיין שם.\nובבואנו מימי חנוכה, אשר כל' המורה הגדול הוא רבינו הרמב\"ם, ריש הלכות חנוכה, גזרו גזרות כו' ופשטו ידם בבנותיהם — ומסרו בנ\"י נפשם על זה וגברו ונקבעו ימי שמחה והלל מאז ועד סוף כל הדורות, שהרי אפילו כשהמועדים בטלים ימי חנוכה קיימים<sup data-n=\"1930\">4</sup>, תקותי חזקה שעל דרך זה גם בענין האמור יתוקן הדבר בתכלית, ואף הן (נשי קהלתו קדישא) תהיינה באותו התיקון (עיין רש\"י שבת כג, רע\"א, ד\"ה היו: ועל יד אשה נעשה הנס), באופן שמסיבות מצוה האמורות תהיינה מתאימות במלואן למאמר חכמינו ז\"ל על כל בי' עשרה שכינתא שריא, על אחת כמה וכמה בתוככי כמה וכמה פעמים עשרה, ויקויים הנאמר שהשמחה במעונו, ובשמחת מלכו של עולם — הרי מברך ומשפיע לכל אחד ואחת שפע ברכות מידו המלאה הפתוחה הקדושה והרחבה.\nבכבוד ובפ\"ש הנהלת קהלתו קדישא והרבנים — שליט\"א — בראשם, ובברכה לבשורות טובות בכל האמור.\n<span data-k=\"q\">(ממכתב זאת חנוכה תשכ\"ד)</span>",[["1927","1","<b>שהכל ברא לכבודו</b>: עיין רש\"י כתובות (ח, א) ד\"ה שמח: אסיפה זו כבוד המקום היא."],["1928","2","<b>השמחה במעונו</b>: ראה ב\"ח וב\"ש (אה\"ע סס\"ב סקי\"א) דאין אומרים (ואין שמחה) כשיצה\"ר שולט. וראה שדי חמד — להחח\"ם — אספ\"ד מע' חו\"כ (סוס\"ק יב)."],["1929","3","<b>בראשית מדון</b>: דינו של אדם (קדושין מ, סע\"ב)."],["1930","4","<b>ימי חנוכה קיימים</b>: מדרז\"ל הובא בס' החיים ח\"ג רפ\"ז. ובכ\"מ. וראה רמב\"ן ר\"פ בהעלותך דמרז\"ל \"הנרות לעולם לא רמזו אלא לנרות חנוכה\"."]]],[1301550362,"<hr>\nבמענה למכתבה בו כותבת על שהשתדכה עם מר. . שי' שומר מצוות, בעל מידות טובות, וקבעו זמן החתונה בעוד איזה שבועות, אבל מצטערת שאינו נוהג בכיסוי הראש, ואינו רוצה לעשות זה גם עתה, אף שמבטיח שיתנהג כן כשיצא ממרוקו באמצע הקיץ, באמרו אשר זהו, כיסוי הראש, רק חסידות.\nכיון שככתבה בעל מידות ושומר מצוות הוא, הרי בוודאי יקבל ההסברה, אשר אפילו את\"ל שאין בהאמור אלא עניין של חסידות, הנה כשמתכוננים להתחתן, ז.א. לבנות בניין עדי-עד, כנוסח ברכת נישואין, שלזה צריכים ברכה מיוחדת מנותן התורה ומצוה המצוה, אשר כאמרנו בכמה תפילות, לך ה' הצדקה ולנו בושת הפנים, ובכל זה הרי מבקשים מהקב\"ה שיברך הזוג בכל הפרטים, אף שכנ\"ל לנו בושת הפנים.\nוכיוון שמידתו של הקב\"ה היא מידה כנגד מידה כדברי חכמינו ז\"ל, בוודאי שעל האדם הזקוק לברכה האמורה, להתנהג לא רק מה שנדרש ממנו בתוקף חומר הדין, אלא לעשות אף זה שאין בזה אלא חסידות, ובפרט שאומר שלאחרי משך זמן יכסה ראשו, הרי אין בכל העניין אלא הקדמת הנהגה האמורה לאיזה חודשים, ובחילוף זה — הרי יקבלו הוספה בברכת השם.\nבגוף העניין, שאומר אשר כיסוי הראש הוא רק מידת חסידות, הנה כבר נפסק הדין, אשר העניין דכיסוי הראש מחוייב בזה כאו\"א משומרי תורה ומצווה, לא רק לדעת אלה הפוסקים אשר כן הוא עפ\"י דין הגמרא והראשונים, אלא אפילו אלו שחולקים עליהם ואומרים אחרת, גם הם מודים אשר בדורותינו אלה, עניין גילוי הראש, זהו הוראה על פריקות עול [ואשר עי\"ז משתדל שלא יכירו בו שהוא בן אברהם יצחק ויעקב, לומד תורה ומקיים מצוות, ושיאמרו עליו אשר ח\"ו לא מבני ישראל הוא, שהרי הילוכו ולבושו דומה לאינו יהודי], אשר מזה מובן, שלא רק אשר ע\"פ דין מחויב לכסות הראש, אלא שבין הדינים עצמן — זהו דין מיוחד ונוגע בהאמור דאתה בחרתנו מכל העמים, ופשוט שאין מקום להתדמות אליהם (להעמים) ולהתנהג שיטעו שאין הוא ח\"ו מבני-ישראל.\nמוסג\"פ חוברת המדברת בעניין כיסוי הראש, ובוודאי ימצאו בהסביבה המבינים אנגלית להסבירם תוכן החוברת.\nויהי רצון שתבשר טוב בכל האמור.\n<span data-k=\"q\">(ממכתב אדר\"ח אדר א' תשכ\"ב)</span>\n<hr>\nבאם<sup data-n=\"1931\">*</sup> שניהם [האח השלישי והאחות השלישית] יר\"ש (שבתקופתנו — שאינו מצוי",[["1931","*","מענה לשאלה אודות שני אחים הנשואים לשתי אחיות והאח השלישי רוצה לישא האחות השלישית. המו\"ל."]]],[1301550363,"כ\"כ כבדורות שלפנינו, זהו טעם עיקרי להשתדל בהשידוך) יגמרו השידוך בטוב, אבל לא ידורו בעיר אחת עם שאר האחים.\nכ\"ז — בנוגע לאשכנזים. בנוגע לספרדים — יש לברר האם בכלל קבלו עליהם סעיף זה מצוואת ר\"י החסיד. כן יש לצרף לעשית השידוך: א) מש\"כ בהצוואה ומסתמא ב' אחים לב' אחיות — לזרעו<sup data-n=\"1932\">**</sup>. ב) הענין דכיון דדש (שכבר נשואים ב' אחים לב' אחיות) דש.\nולהחמיר כיון שמדובר באח שלישי — בכיו\"ב בנסתר אין למדין סברות דנפשי'.\nוהעיקר — שיתנהגו ביר\"ש.\n<span data-k=\"q\">(ממכתב תחלת שבט תשל\"ח)</span>\n<hr>\n... לכתבו ע\"ד הוספת שם ואיזה — יבחר בשם ע\"פ עצת רב מורה הוראה במקומו (היינו — מקום שלומד תורה ומתפלל וכו').\nוגוף הערתו יש לברר האם אחב\"י הספרדים מלכתחילה לא קיבלו עליהם צוואת רי\"ח, וראה שד\"ח אס\"ד מ\"ע חתן וכלה אות ה' ואילך.\n<span data-k=\"q\">(ממכתב ה' אד\"ר תשכ\"ו)</span>\n<hr>\nבמענה למכתבו מג' כסלו, בו כותב ע\"ד המאורע ל\"ע ול\"ע שקרה במשפחת בת גילו תחי', ואשר לכן נתעורר ספק אם לעשות החתונה במועד שנקבע.\nלפלא גדול הספק בדבר המפורש בפוסקים ככתבו גם במכתבו זה ע\"ד פסק דין רב מורה הוראה בישראל, לעשות החתונה.\nויש עוד להוסיף שמנהג ישראל, שלא לדחות מועד זמן החתונה, והרי מנהגם של ישראל תורה היא, ובפרט בענינים כהנ\"ל, וק\"ל.",[["1932","**","ראה פסקי דינים להצ\"צ יו\"ד סי' קטז. וש\"נ. המו\"ל."]]],[1301550364,"בעת רצון יזכירום על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע כבקשתו.\nותקותי שלא רק שלא יאחרו החתונה מהמועד שמזכיר במכתבו, אלא יקדמוה כפי האפשרי ומכמה טעמים, ויהי רצון שיהי' בשעה טובה ומוצלחת.\n<span data-k=\"q\">(ממכתב ו' כסלו תשכ\"א)</span>\n<hr>\nבמענה למכתבה מי\"ט כסלו, בו כותבת אודות ההיכירות שלה אשר מחשבתה בזה הוא לשם שידוך, והצדדים החיובים שבזה וכן אלו אשר להיפך, ובזה גם שכאילו יש התנגדות ממשפחת האברך, אבל אינה מבארת למה הם מתנגדים וטעמי ההתנגדות.\nלשאלתה דעתי על הטעמים שכותבת, הנה הקורבה המשפחתית שביניהם רואים במוחש ובפרט בדורות האחרונים, שאין כל מקום לחשש בזה, בעת שהמדובר והמדוברת בריאים הם.\nב) לכתבה שבגיל הנוכחי צריך לחכות כשנה ועוד יותר עד לנשואין, מובן גם פשוט שאין זה מתאים להשקפתי, שהרי אין זה השקפת תורתנו תורת חיים בכלל, ובפרט בתוככי אחב\"י הספרדים שגם הם שניהם נמנים על עדתם, ועוד וגם זה עיקר, שאינו רצוי כלל וכלל להיות מכירים וידידים ועל מנת להנשא, וביחד עם זה להחליט שמוכרח לחכות עד הנשואין בפועל כמה וכמה חדשים ואולי עוד יותר, וכאמור אין זה רצוי כלל וכלל ועל הצעירים היראים וחרדים לדבר ה' להכיר כו' ולהתידד רק בהקדם החלטה שכבר באה העת להנשא בפועל, והרי ברור שהוראות תורתנו תורת חיים הם לא רק לשם טובה בעולם הבא לאחרי מאה ועשרים שנה, אלא שזהו טובתו של איש הישראלי גם בעולם הזה, לחיות חיים מאושרים בגשמיות וברוחניות.\nג) לכתבה איך להביא הענין יותר קרוב להאברך — כנראה ממכתבה ודאי שמבין הוא יחסה הרציני אל הענין, וכיון שממשיך בהפגישות, בטח זהו סימן, שגם לו יחס רציני בזה, אף שאפשר לא כל כך כמו אצלה, והרי פרטים אלו יש לברר ע\"י ידידים לשניהם גם יחד, וכמו אלו שמזכירה במכתבה.\nע\"פ סגנון מכתבה בטח למותר להאריך אודות ההכרח בחיים על פי הוראות תורתנו תורת חיים ורק להוסיף, שכשנמצאים במבוכה וזקוקים לתוספת ברכה מהשי\"ת נותן התורה ומצוה המצוה, יש להוסיף בעניני יהדות ועד לחיי היום יומים,"],[1301550365,"והרי בעניני טוב וקדושה ככל שלא יהי' גם טוב בזה, תמיד יש מקום להוסיף כיון שקשורים בהקב\"ה שהוא אין סופי...\n<span data-k=\"q\">(ממכתב כ\"ב כסלו תשכ\"א)</span>\n<hr>\n... הדגשתי וכ\"פ — שמוכרח לעשות מה בנוגע להיתר נשואין [באחב\"י הספרדים] בגיל מוקדם להמותר ע\"פ החוק דכנסת, ומכמה טעמים: לכל לראש — כיון שגם עתה ישנם כו\"כ מקרים דאירוסין וקדושין וגם נשואין, ושמפני החוק נעשים בצנעא, ומובן הקלקול שבדבר. ועוד —\nוגם זה עיקר — שבדורנו, הלואי שגם האשכנזים היו משיאים בניהם ובנותיהם קרוב לפרקם ולא כהמצב בהווה, ועאכו\"כ בנוגע הספרדים שמאז ומקדם הורגלו בכהנ\"ל. וגודל התקון — אין די באר. והבטיח שבהזדמנות יתענין בהאפשריות עכ\"פ להוריד גיל הנשואין לשנה וכיו\"ב...\n<span data-k=\"q\">(ממכתב עש\"ק ג' תמוז תשכ\"ד)</span>\n<hr>\nסדר החיים כשהבעל לומד תורה חלק מיומו (עכ\"פ) — מובן שזוהי ההתחלה הנכונה ושצ\"ל בבנ\"י [כיון שהחתונה היא ההתחלה דבנין עדי עד] — אבל מובן ג\"כ, שזהו קשור בהגבלה ומדידה וקצת צמצום בנוגע לגשמיות, וכיון שזהו נרגש בחיי יום יום ומאידך — צ\"ל החיים דבנ\"י — כמש\"נ — מתוך שמחה וט\"ל ובטחון —\nהרי צ\"ל ההסכמה על סדר חיים כזה — מראש והסכמה מלאה ומתוך שמחה (על שמתחילים חייהם — בחיי תורה, תורת חיים).\nואם יסכימו שניהם ע\"ז ובאופן הנ\"ל — יה\"ר שיהא כ\"ז בשטומו\"צ.\n<span data-k=\"q\">(ממכתב שלהי מרחשון תשכ\"ה)</span>\n<hr>"],[1301550366,"... לשאלותיו בנוגע לפרטים בהנהגתו ובפרט בהנהגת הבית לאחרי חתונתם בשטומו\"צ באותם הענינים שיש מחמירים ומקילים — מובן שאין כל הענינים והסביבות והאישים שווים, ובסגנון חז\"ל דיש חומרי המקום שהלך משם ושבא לשם (ועד\"ז בנוגע למשפחות וכו').\nוידבר כ\"ז עם הרב מרא דאתרא. — ומה נפלאת מעלת קדש עצמך במותר לך שמבואר בדא\"ח שעי\"ז דוקא נמשך מבחי' עצמות אוא\"ס שלמעלה מבחי' ותו\"א, הגילוי דלעת\"ל (סד\"ה ואתם תהיו לי תר\"ס).\n<span data-k=\"q\">(ממכתב מ\"ח תשכ\"ו)</span>\n<hr>\nמה ששומע מכמה אנשים שמדברים שכשמתחתנים קמות כמה פּראָבלעמען, קישוים וכו' — הוא לא מפני שמקרים כאלו הם גדול, כי אדרבא הם מיעוטא דמיעוטא (שאפילו לר' מאיר אין חוששין לזה) — אלא שכל אלה שאין אצלם פּראָבלעמען וכו', אין מדברים כלל עד\"ז, כי זהו נחשב למצב נורמאַלי. שלהתחתן טוב הוא (וגם מוכרח) — מפורש בכתוב (בראשית ב, יח). ורואים גם במוחש, מזה — שלועגים לאלו שלא נישאו (בחור זקן, בחורה זקנה). כשיתבונן בעבר שלו — יראה איך שניצול מכמה צרות, וכמעט באופן למעלה מדרך הטבע. ואדרבא התבוננות זו, באם תהי' אמתית — תחזק בטחונו.\nבהיפך מכתבו — ע\"ע לא השתדל בנוגע לשידוכים, כ\"א רק להראות (גם לעצמו) שיכול לעשות רושם טוב כו'. אבל כשהי' מתקרב להבפועל ולהחלטה — הי' משתמט (בכדי להשאר חפשי, בלי אחריות).\n<span data-k=\"q\">(ממכתב שנת תשכ\"ב)</span>\n<hr>\nבמענה למכתבו מיום השני, בו כותב אודות הבחורה תחי' אשר נפגשה עם א\"י וכו' ולאחרי רוב הדבורים ואריכות זמן, אומר הא\"י שרוצה להתגייר כדרוש ומוכן לקבל עליו עול מצות וכו' וכו', ומסופק איך יהי' היחס להצעה האמורה, כיון שתחלת הענין בא ע\"י ההיכירות עם הבחורה האמורה וכו'."],[1301550367,"והנה בכלל אין עניני לפסוק דינים, והרי כו\"כ הראוים לשמם לזה בעיר רבתי כנויארק, ובכ\"ז כיון שכבר כתב, ובתור הצעת סברא, ולא פסק דין, אבוא בשורות דלהלן.\nוכנראה ממכתב כת\"ר השייכות שבין הנ\"ל חזקה ביותר ומי יודע וכו', ולאידך גיסא אפילו בנוגע לגירות שאין בה כל פקפוק, ידוע מאמר חז\"ל אודות סורם וכו', ובכהאמור בודאי יש מקום גם לשאלת פגם המשפחה וכו'.\nולכאורה המוצא הכי ישר בהאמור הוא, להציע להא\"י, כיון שלדבריו — כוונתו גירות לשמה, ובודאי גם הוא מודה שאי אפשר לשער מראש עול המצות בחיי היום יום עד שמנסים זה בפועל, ובפרט שגם הוא מודה שתחלת הסיבה היתה שלא לשמה, ובמילא משוחד הוא בההשערה אודות עצמו שיקיים כל האמור בפועל,\nלכן העצה הכי ישרה, שההתחלה תהי' הנהגתו בחיי היום יומים עפ\"י השו\"ע משך זמן חשוב, ושבמשך זמן זה לא יבלבלו זא\"ז (הוא והבחורה) ע\"י פגישות וכו', ומה טוב שלא יהיו בעיר אחת, ולאחרי נסיון האמור יוכל להחליט בעצמו, באם באמת יחי' חיים כדת משה וישראל או וכו'.\nומה טוב שבינתים ישתדלו שהבחורה תסע לאה\"ק ת\"ו וכיו\"ב, וההסברה כאמור בכדי שכל אחד מהם ישער בעצמו אמיתת כוונתו בהאמור.\nכבקשת כת\"ר נשלח המכתב מבלי לחכות על התור.\n<span data-k=\"q\">(ממכתב ל' תשרי תשכ\"ה)</span>\n<hr>\nבמענה למכ' מיום. . רבו מלספור מרז\"ל וגם פס\"ד למעשה שיסודם זה ששקדו חכ' על תקנת בנות ישראל בעניני נישואין ואישות, ובפרט — בתיקון עגונות. ואם בכ\"ז ישנו מצב שאין התורה מתרת העגונה — פשוט שזהו גם נגד שכל הבריא להכניס רעפארם כפה\"נ לאדם פלוני. וממנ\"פ האדם המשנה פס\"ד התורה ז.א. שלדעתו האדם למע' ממנה — וא\"כ מה לו בכלל תורה כזו שתצווהו מה לעשות. ואם יודע האמת שתורה מן השמים — איך זה שכל מוגבל של בנ\"א — בא לשנות פס\"ד של הבורא הבלתי מוגבל ושאינו בערכו כו' ולומר שדין זה ישר בעיניו ודין זה לא כו'. ומסוג זה הם גם ההצעות שנשללו בהחלט ע\"י גדולי הדורות שלפנינו וכן אלו שאגוה\"ר דכאן המונה מאות רבנים שעסקו בתורה רוב שנותיהם ובהתמדה וכו' ואסרום.\nתקותי שמזמן לזמן מוסיף בתומ\"צ כהציווי להעלות בקודש ואין דבר העומד"],[1301550368,"בפני הרצון. מוסג\"פ קטע משיחת יו\"ד שבט<sup data-n=\"1933\">*</sup> שבטח יענינו וינצלו באופן המתאים.\n<span data-k=\"q\">(ממכתב כ\"ז שבט תשכ\"א)</span>\n<hr>\n... מובנת התמי' על כתבו אשר י\"א שיש חילוק בין שם הניתוסף לשם מעריסה. וראה שו\"ע אה\"ע סקכ\"ט סי\"ח דאדרבה שם השינוי עיקר, ובכלל אדם בעה\"ב בענין קריאת שמות ליו\"ח שי' ולעצמו.\n<span data-k=\"q\">(ממכתב ט\"ז שבט תשכ\"ב)</span>\n<hr>\nמאשר הנני קבלת מכתבו בצירוף ספר באר יעקב על מס' יבמות וקנים, שיטה מענינת בהסברת ד\"ת.\nויהי רצון אשר רבות בשנים ירבה חילו לאורייתא להפיץ לימוד התורה בהסברה הבנה והשגה,\nהן נגלה דתורה והן פנימיות התורה שבדורנו נתגלתה בתורת החסידות,\nשגם בזה הציווי בדורותינו אלה, ללמוד עד שיבין וישיג כמבואר בכ\"מ, וראה ג\"כ הלכות ת\"ת לרבנו הזקן בעל התניא והשו\"ע, סוף פרק ב' ושם פרק א' סוף סעיף ד'.\nבכבוד ובברכה.\nנ.ב. כדרכי אבוא באיזה הערות, והם:\nגם בתרשימים משתדלים באם רק אפשרי, שתהי' שייכות בין הסימן והדבר המסומן, ועפי\"ז לכאורה בסימן לאיסור צ\"ל בהיפך מהסימן לזיקה,\nלכאורה הסימן ליבום ולאיסור היינו הך בספרו.\nבהחליצה צ\"ל ענין של הפסק קו בהפסקים משא\"כ ביבום שהוא קישור (קו בלתי נפסק).",[["1933","*","לקו\"ש ח\"ב ע' 521. המו\"ל."]]],[1301550369,"ע\"פ הנ\"ל ג\"כ מובן שבנשואין אין מקום לקו בהפסק.\nועוד להעיר משטח אחר לגמרי, שלא נראה לי מרובע לסימן (זכר), שהרי אין מרובע מששת ימי בראשית<sup data-n=\"1934\">*</sup>.\nמצו\"פ רשימה<sup data-n=\"1935\">**</sup> שתקותי שתעניין את כת\"ר שי'.\n<span data-k=\"q\">(ממכתב כ\"ז תמוז תשכ\"ב) </span>\n<hr>\n... הכתוב במכתבי הקודם, בהחילוק שע\"פ שו\"ע וכו' לא היתה כוונתי לשלול לגמרי נתוח הפראסטאטא, באם רופא מומחה מייעץ לעשות אותו, כי אם להורות על חילוק אופני הנתוח בזה, אשר ישנם רופאים שבכלל אין מנתקים את השביל.\nועל זה הבאתי המועתק באוצר הפוסקים חלק א' [מהדורא שני' עם הוספות, ירושלים תשט\"ו].\nב) אפילו מהמנתקים — כמה עושים זה לאחרי שנעשה חלק העיקרי של הנתוח, שאז כבר יש צורך בפועל [לדעתם, עכ\"פ] לשמירה מסיבוכים, משא\"כ כשמתחילים בנתוק. וק\"ל.\nכן להוסיף אשר ישנם נתוחים דכיס השתן שמפני אותו הטעם דלהשמר מסיבוכים מפסיקים ומנתקים כו' בסמיכות למקום הנתוח ולפעמים גם במקומות שיש לדון בזה עפ\"י השו\"ע, שלכן העירותי על זה, אף שבמכתב כת\"ר הא' לא היה נזכר אלא הנתוח האחרון, ועל כת\"ר הסליחה על ההערה עוה\"פ.\n<span data-k=\"q\">(ממכתב ב' אייר תשכ\"א)</span>\n<hr>",[["1934","*","ראה גם לקו\"ש חט\"ז ע' 513. המו\"ל."],["1935","**","שיחת ש\"פ חו\"ב תשכ\"ב (נדפסה בלקו\"ש ח\"ב ע' 599 ואילך). המו\"ל."]]],[1301550370,"<h3>תבוא</h3>\nבהמשך להמדובר<sup data-n=\"1936\">*</sup> — מצאתי לאח\"ז בפיה\"מ לדמאי (פ\"א, מ\"ב) דלא אכלתי באוני היינו קודם הקבורה (וכ\"פ הרא\"ש סוף מע\"ש<sup data-n=\"1937\">*</sup>)...\nזה עתה ראיתי בפיה\"מ שהו\"ל הרב קאפח (ירות\"ו. תשכ\"ג) שמעיר המו\"ל שבכת\"י שביד המו\"ל מחק הרמב\"ם (?) הנוסח שהעתקתו בדפוסים שלנו כנ\"ל, וכתב בשולים נוסח שמעתיקו \"ביום המיתה בלבד הוא אונן מה\"ת\" — כלשונו ביד החזקה. ומסיימים בטוב:\nבריש ס' המאמרים תרכ\"ט (ברוקלין, תשי\"ט) מבואר (וכנראה מיוסד על מאמר אדמו\"ר הצמח צדק) איך שברכתו של ה' יש בה גם המעלה דתפלה, יהי רצון, להמשיך רצון חדש לרפאות ולברך.\n<span data-k=\"q\">(ממכתב ערב חג הסוכות בעלות המנחה תשכ\"ה)</span>\n<hr>",[["1936","*","בעת הביקור לניחום אבלים על אמו הרבנית הצדקנית מרת חנה ע\"ה. המו\"ל."],["1937","*","פ\"ה מי\"ב (ופליג על הרע\"ב שם)."]]],[1301550371,"<h3>ח\"י אלול</h3>\nבמענה על מכתבו אשר כיון שאין הוא שבע רצון מפרטים אחדים בסדרי הישיבה, ולפי דעתו מבלבלים פרטים אלו מהתמדה בלימוד כדבעי, וכן בהנוגע להתפלה, הרי יש אצלו סברא אודות נסיעה לישיבת תומכי תמימים באה\"ק ת\"ו, ושואל חוות דעתי בזה.\nוהנה למותר להאריך בהידוע ופשוט, אשר הענינים המפריעים לתורה עבודה או גמילת חסדים, סיבתם הוא השאור שבעיסה, היינו היצר הרע המבלבל את האדם בכמה אופנים ודרכים, כי אף שנקרא כסיל, הנה בכל זה בהנוגע לעבודתו — אומן מומחה הוא, וכידוע פתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, אשר היצר הרע בא לכל אחד ואחד בטענות מתאימות לתכונת נפש אדם פרטי זה עד שגם לפעמים הוא מתלבש באצטלא של צורבא מרבנן, ירא שמים וכו', ולכן על כל אחד לבדוק הדק היטב היטב הדק את הנופל בדעתו בהנוגע שינויים בעבודת השי\"ת, ולדעת מי הטוען טענות אלו, אם מצד ימין או מצד שמאל. ובטח ידוע לו הסיפור אודות הרה\"צ מטשערנוביל, שנדפס בשיחת פסח תש\"ג, ואחת הבחינות היא אם השינוי יגרום לביטול תורה ועבודה — או לאו.\nובנידון דידי' — כיון שנמצא הוא בישיבה שנתייסדה על ידי צדיקים נשיאי הדור ומתנהלת ברוחם, היינו לימוד התורה ביראת שמים, הנה קרוב הדבר, גם מבלי ידיעות פרטיות בזה, שלימוד בה תועלת גדולה כרוכה בזה, ובמילא מובן גם כן אשר היצה\"ר מתקומם בזה בכמה מיני תחבולות לבטל ולבלבל אותו מלהתנהג מתאים לפי דרישת הישיבה בכל הפרטים.\nמובן גם כן, שאם יבוא היצה\"ר ויגלה כוונתו שאינו רוצה להניחו להיות שוקד בלימוד תורת הנגלה ותורת החסידות, הרי בטח לא ישמע לו, ומתאים למה שנאמר והנחש הי' ערום, הרי בא בערמומיות, שאדרבה הישיבה מבלבלת אותו משקידה בתורה ומענינים דעבודת השם ביראת שמים כדבעי, שאז תקוותו שיתקבלו הטענות שלו, ויבלבל אותו מתורה ותפלה. ואף שצריך היצה\"ר להבטיח לו שאם יבוא לישיבה אחרת הרי אז לא יבלבל אותו ויוכל לשקוד בתורה ולהדר בתפלה, הרי מובטח הוא היצה\"ר, שכיון שישמע לקולו בתחלה — שכל התחלות קשות — הרי בטח גם אחר כך ימצא אופן איך להמשיכו עוד יותר ברשתו.\nכי הרי נתנה לאדם הבחירה חפשית ושני דרכים לפניו, וכמאמר הכתוב ראה נתתי לפניך את החיים ואת הטוב את כו', אבל ביחד עם זה ניתן לו לאדם סיוע מיוחד שיבחר בטוב, וכמאמר הכתוב ובחרת בחיים. ובודאי גם בנידון דידי' הרי אף שהיצה\"ר הוא ערום ביותר, ניתנו לו הכוחות לבטל כל הטענות שלו ולהתאמץ"],[1301550372,"במסירה ונתינה על ידי היסח הדעת גמור מהטענות המבלבלות שאין הסביבה מתאמת לפניו ושהכל אשמים בביטול תורה ותפלה שלו ולא הוא בעצמו כו' וכו'.\nמובן גם כן שבין חביריו בישיבה ישנם כמה ענינים הדורשים תיקון, כי אין שלם בתכלית השלימות אלא הקב\"ה בורא העולם, אבל העצה לזה הוא שישפיע על חביריו בתיקון עניניהם, ולא שהוא יהי' מושפע מהם, אשר זהו ג\"כ סגולה שיתתקנו חסרונותיו הוא על ידי חביריו, וכמאמר — וכמבואר — בהענין דכל ישראל ערבים זב\"ז, שהם קומה שלימה ויש מעלה בזה מה שאין בזה, ועל ידי אהבת ישראל משלימים כל אחד את חבירו.\nהמורם מכל הנ\"ל, שיסיח דעתו ממחשבות המבלבלות מתורה ועבודה וישקיע את עצמו בלימוד תורת הנגלה ותורת החסידות ובעבודת התפלה — מתאים לסדרי הישיבה ודרישותי', ותקויים בו הבטחת רז\"ל אשר יגעת — הרי אז — ומצאת.\nאינו מזכיר אם גם בנוגע לחבירו. . שי' הרי גם אותו מבלבלים אלו הטענות שכותב בהנוגע לענינו, ואם כן הוא — הרי מובן שגם אליו שייך מענה הנ\"ל.\nבברכת הצלחה בלימוד התורה וביראת שמים.\n<span data-k=\"q\">(ממכתב כ\"ה אד\"ר תשי\"ד)</span>\n... ועל של עתה באתי לעוררם על היום הצח והבהיר הוא יום ח\"י אלול הבע\"ל, אשר בטח ינצלו אותו במרץ וחיות שהם מסגולות הצעירים, להפיץ את רעיון הבעל שם טוב ואדמו\"ר הזקן, אשר יום הולדתם, ברוחניות ובגשמיות, הוא יום ח\"י זה. ולהפיץ רעיון זה בחוגים היותר רחבים ואף שהם לעת עתה עדיין רחוקים מסביבותינו שלנו.\nוידוע פתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע בהחילוק שבין העולמ'שע וחב\"ד, אשר בגדולים של עולמ'שע הי' שהיו יושבים בביתם ובמקומם, וכל התאב לתורה הי' בא אליהם ליהנות בזיו תורתם, משא\"כ הבעש\"ט ואילך, שהם הנהיגו את הסדר שהי' הבעש\"ט מסבב בעיירות ואינו מחכה עד שיבואו אליו ויאמרו נצבים אנו לדבר הוי' אלא הוא בכבודו ובעצמו הי' מכתת ברגליו ממקום למקום מעיר לעיר ומכפר לכפר והי' מפיץ את תורת דברי אלקים חיים (ספר השיחות קיץ ת\"ש, אחרון של פסח בסעודת היום).\nב) לסדר תכנית עבודה איך לנצל את חודש תשרי הבע\"ל, וכנ\"ל ע\"י הסיבוב במקומות שונים, באה\"ק ת\"ו או במשך הימים נוראים, או בימים דזמן שמחתינו, והעיקר שיהי' באופן מסודר, ובאופן שי[... ] שמחים היותר גדולים ומספר אנשים ונשים וטף היותר גדול...\n<span data-k=\"q\">(ממכתב ט' אלול תשי\"ד)</span>\n<hr>"],[1301550373,"<h3>נצבים</h3>\nבמענה למכתביו בם מציע לפני להשתתף בקובץ מאמרים מוקדש לעניני תשובה,\nהנה בכלל אין זה בנוהג בית הרב כ\"ק מו\"ח אדמו\"ר, ומסורת אבותינו בידינו.\nבכל זה, לגודל חשיבות הענין ומפני כבודו דמר, אשתמש בהזדמנות זו להביע, על כל פנים בקיצור, רחשי לבבי אשר הבעתי בדיבור בכמה הזדמנויות ומהן גם באסיפת רבים, ובהקדם נקודת ענין התשובה, אשר בסגנונו של כ\"ק רבינו הזקן בעל התניא והשלחן ערוך, שהשנה היא שנת המאה וחמשים להסתלקות-הילולא שלו, שענין התשובה הוא שאינה על עבירות דווקא, שהרי אמרו רבותינו ז\"ל שיהי' כל ימיו בתשובה, אלא הוא ענין השבת הנפש, כי הנשמה חלק הוי' וירדה מאגרא רמה לבירא עמיקתא להתלבש בגוף, וענין התשובה שהרוח תשוב אל האלקים אשר נתנה, על ידי מסירת נפש, מסירת הרצון וכו'.\nכל תקופה ותקופה יש לה ענין המיוחד לאותה תקופה בפרט, ובתקופתנו אנו ובפרט בשנים הכי אחרונות רואים התעוררות רוחנית בבחינת ניבא ולא ידע מה ניבא, שקראו לזה \"שיבה אל המקורות\", שבאמת ובפנימיות הדברים אינה אלא כנ\"ל — ענין של והרוח תשוב אל האלקים. ובעיקר רואים התעוררות זו בתוככי הנוער, שאצלם הענין עוד חשוב יותר מצד שהוא ביתר פנימיות וביתר תוקף וגם מפני שאינם מפחדים מהשנוי באורח חיים אם רק יש להם ההרגש שנותנים להם האמת בלי פשרות ובלי כחל ושרק וכו'.\nובמדינה זו במיוחד — תכונת הנוער לא כתכונת הנוער בשאר מדינות ששם הי' צריך עבודה כפולה, ראשית לשרש דיעות כוזבות שהיו מושרשות בכמה חוגים גם בין הנוער, ורק לאחרי זה היתה האפשריות לנטוע בתוכם דיעה הישרה והנכונה. מה שאין כן במדינה זו, שהנוער הוא בגדר קרקע בתולה, ובלבד שיתנו להם הענין כמו שהוא. ורואים בעליל שאלו שאינם מפחדים \"ומגישים\" האמת בלי פשרות, מצאו הד נכון בקרב הנוער.\nואף שאין רצוני לקטרג ח\"ו, אבל מוכרחני להדגיש שלצערנו הרב עד עתה לא ניצלו (כדבעי למיעבד) כלל התעוררות האמורה ביחוד על ידי אלו שצריכים להיות רועי העם מוריו ומדריכיו הרוחניים, וד\"ל.\nועל פי הוראת רבותינו ז\"ל מעשה הוא העיקר, מובן שבכל הכתוב לעיל אין כוונתי לדרשה וכו', אלא כולי האי ואולי, בהשתדלות כת\"ר ועד\"ז כיוצא בו, תבוא פעולה רחבה ובמרץ הכי גדול לחזק התעוררות האמורה ובעיקר — להביאה לידי פועל ועד לחיי היום-יום אצל כל אלו אשר הקול והדיבור יכול להגיע אליהם."],[1301550374,"ובענין של פיקוח נפשות הרי אפילו מספק וס\"ס — צריך גם כן לעשות. ויהי רצון אשר התעמולה והפעולה הזאת תגלה ותעורר את פנימיות נקודת הנפש שבכל אחד ואחת מבני ישראל, אשר תמיד היתה באמנה אתו, את ה' אלקינו, ועד לקיום התורה והמצוה בפועל; וכידוע דברי המורה הגדול הרמב\"ם, אשר כל אחד ואחת מבני ישראל רוצה הוא לעשות כל המצוות ולהתרחק מן העבירות (רמב\"ם הל' גירושין סוף פ' ב'). וכשיעשה כל אחד ואחד כל התלוי בו, ומתוך בטחון חזק שעושה בשליחותו של מקום, הוא המושל ושולט בכל מקום ומקום, ובדברים היוצאים מן הלב שאז נכנסים אל הלב ופועלים פעולתם, מובטח לו שהוא מצליח.\n<span data-k=\"q\">(ממכתב י\"ג תמוז תשכ\"ג)</span>\n<hr>\nלהערתו באגה\"ת רפ\"א 1) בהסגנון אבל לענין תשובה כו' — ההמשך הוא: עבר על מ\"ע ושב מוחלין לו, במל\"ת — תולין. ואף שעשה דוחה ל\"ת — זהו מצד הענין דעולמות והנפש אבל בענין המצות (אורם) מל\"ת גבוהים יותר (עיין לקו\"ת פקודי ו, ד) אבל לענין תשובה — (תשובת) מ\"ע גדולה יותר כי אף כו' (ראה לקו\"ת ד\"ה מה טובו פ\"ב)<sup data-n=\"1938\">*</sup>.\n2) איך יתאים מש\"כ כאן עם הידוע דיוהכ\"פ ממלא כל הפגמים כו' ויש להוסיף עם מרז\"ל דאין דבר העומד בפני התשובה.\nאבל כאן מדבר בתשובה סתם, ויוהכ\"פ — מצד עיצומו של יום, מבלי עבודת האדם בזה, כדמוכח גם בש\"ס. ועיין ד\"ה מה טובו הנ\"ל.\n<span data-k=\"q\">(ממכתב ר\"ח מנ\"א תשכ\"א)</span>\nעוד להוסיף, מחלק כאן בין מ\"ע למל\"ת בג' ענינים: בענין הכפרה — כפרת מ\"ע קודמת. כן לענין קיום — קיום מ\"ע קודם. — אבל (בהיפך משני הנ\"ל) לענין תשובה תשובת מל\"ת קודמת.\n<hr>\nאינו בהחלט — כיון שתורת חיים מודיעה שבכל יום ויום צ\"ל ואפשרית יצי\"מ. אלא שניתנה לבנ\"י דוקא — מתנה, שבה דומים לבוראם — ענין הבחירה. ורצה הק'",[["1938","*","באופן אחר קצת: הנקודה שלפני \"אבל\" מפסיקה הענין ואבל לענין תשובה — קאי על הברייתא."]]],[1301550375,"שגם יצי\"מ הנ\"ל תהי' דוקא ע\"י מתנה זו — בבחירת האדם, וכמש\"נ: ובחרת בחיים (הוראה וגם נתינת כח והבטחה). א\"כ, כנ\"ל, יבחר בחיים האמתיים (והבלעדיים — בנוגע לבנ\"י) חיי תומ\"צ, ויצליח בנקל יותר ובמדה גדולה יותר מאשר משער. — וכיון שאדם קרוב אצל עצמו — יפרט ענינו לפני הנהלת תו\"ת ויעשה כהוראתם בשמחה וט\"ל.\n<span data-k=\"q\">(ממכתב דשנת תשכ\"ב)</span>"],[1301550376,"<h3>ר\"ה</h3>\nאף שכן<sup data-n=\"1939\">*</sup> הוא בהנהגות שלעצמו — צע\"ג אם כן הוא במה שעושה להוציא אחרים (עכ\"פ — גם אחרים) ובמ\"ע מה\"ת, ובפרהסיא. ועאכו\"כ — בתק\"ש (ולא בהברכה) שכאו\"א מקיים המצוה, והרי שומע השברים באופן כו'. וק\"ל.\nסו\"ס — איך נהגו בביהכנ\"ס דחב\"ד בכ\"מ, בהנוגע לשברים?\n<span data-k=\"q\">(ממכתב מ\"ח תשכ\"א)</span>\n<hr>",[["1939","*","מענה למ\"ש א' אודות סדר תקיעת השברים בליובאוויטש, שאדנ\"ע תקע יותר מג', והוסיף הכותב מה ששמע מא' \"מה איכפת לך — ער בלאָזט דאָך\". המו\"ל."]]],[1301550377,"<h3>ר\"ה-יו\"כ</h3>\n... אקוה ג\"כ שיבשרני שקבל משרת ש\"ץ לימים נוראי[ם] הבע\"ל ובטח נוהג הוא בזה כמו שנהגו מאז שהש\"ץ ילמד פירוש המלות של כל הפיוטים (נוסף על פירוש המלות של התפלה), ולאו מלתא זוטרתא היא, ובפרט בפיוטים המיוסדים על מרז\"ל אשר במדרשים וכו'...\n<span data-k=\"q\">(ממכתב ט\"ו אלול תיש\"א)</span>"],[1301550378,"<h3>שבת תשובה</h3>\n... ז\"ע נתקבל גם נרות השעוה לשבת שובה הבא עלינו ועל כל ישראל לטובה,\nוידוע סיפור הרבנית הצדקנית מרת רבקה, מענה כ\"ק חותנה אדמו\"ר הצמח צדק (אשר היום הוא יום הולדתו) — לבנה כ\"ק אדמו\"ר (מוהרש\"ב) נ\"ע אשר שבת תשובה, הפירוש אַ שבת'דיגע תשובה, בכל ימות החול, הרי מה שאסור אינו בבית, משא\"כ בשבת הלא גם זה ישנו בבית, ולכן צריכים לידע תחלה — בכל דבר שרוצים לעשות — האם מותר זה. וזה שהניחו לשמו פתילה בהנר של תשובה ובהנר של חיים נותן כח, שיכולים למלאות זאת (קונטרס צו<sup data-n=\"1940\">*</sup>).\n<span data-k=\"q\">(ממכתב ער\"ה תשכ\"ו)</span>\n<hr>",[["1940","*","סה\"מ תש\"ט ע' לו ואילך. המו\"ל."]]],[1301550379,"<h3>וילך</h3>\nבמענה למכתבו מיום הראשון, בו כותב אודות ההנהגה בהכנסת ספר תורה לבית הכנסת.\nוכבר יש נדפס בזה מכתבו של כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1941\">*</sup> ע\"ד הסדר בכלל, אלא שבכל ענין יש להביא בחשבון מנהג העיר, כוונתי האם דרים בשכונת ישראל או שכונת עכו\"ם וכיו\"ב ובהתאם לפרטי העיר לסדר ההכנסה, האם להרבות בהליכה בחוצות או לא וכו'.\nלכתבו אודות מכירת אותיות (לעניני ביהכ\"נ או לצדקה בכלל), כמדומה שנוהגים כן בכל תפוצות ישראל, בכל זה כאמור כדאי להוודע הנוהג בארצוה\"ב ביחוד, כמובן בתוככי החרדים לדבר ה' ושומרי מצותיו.\nלכתבו שיום המתאים יהי' בין המצרים או גם תיכף לאחרי ר\"ח מנ\"א, מובן שהסברא האחרונה דלעשות זה לאחרי ר\"ח מנ\"א מושללת, וגם בנוגע לבין המצרים יש להתענין בדבר, האם אי אפשר לעשות בזמן מתאים יותר, ומגלגלין זכות ליום זכאי.\nלהוסיף שמות על העצי חיים של הס\"ת — מובן שזהו תלוי באם הס\"ת (והעצי חיים בכלל זה) ברשותו הוא, יכול להוסיף שמות. ומה טוב ככתבו במכתבו, לא ביחד ובאותו המקום שנרשמו כבר שמות המנדבים הראשונים.\nובעמדנו בימי סיום וחותם דימי תשלומין דזמן מתן תורתנו יהי רצון שתומשך לתמיד ההתעוררות שבכל יום יהיו בעיניך חדשים, בלא כ\"ף הדמיון (עיין רש\"י דברים כו, טו).\n<span data-k=\"q\">(ממכתב י\"ד סיון תשכ\"א)</span>\n<hr>",[["1941","*","אג\"ק ח\"ו אגרת א'תריב. סה\"מ מלוקט ח\"א ע' שצט. המו\"ל."]]],[1301550380,"<h3>סוכות</h3>\nבמענה למכתבו ובהמשך למה שנדבר עם הוריו שי' בשיחתנו, בו שואל:\nא) מאנ\"ש וחסידים המתעסקים באתרוגי קאלאברי הוא הרה\"ח רב פעלים הרר\"י שי' דזייקאבסאן (אשר כמדומה היו בקשרים זע\"ז מכבר) אשר הנ\"ל בעצמו ביקר בהפרדסים של אתרוגים אשר באיטליא ובחן בהם.\nב) כן להנ\"ל ידוע בנוגע להסימנים והאופן איך להכיר שהאילן אינו מורכב.\nג) במ\"ש אודות אופן גידול העוקץ וכן בנוגע להבליטות — יש לברר האם גדלים באותו אילן עצמו בבליטות וגם בלי בליטות, כן בהנוגע להשינוים בהעוקץ, כי כמדומה שבספרים לא נמצא ע\"ד פרטים כהנ\"ל שכותבם בתוככי סימנים באם נמצאו באותו האילן וצריך לברר אצל מי שהי' על אתר וראה בעצמו...\nנ.ב. כבר מובא מס' בכורי יעקב סו\"ס תרמ\"ח דאין לסמוך על הסימנים גם לא להחמיר. ואף שהוא היפך דעת כו\"כ מהאחרונים — י\"ל שעכ\"פ גם לדעתם כשיש מסורת על המדינה ובאותו אילן עצמו גדלים אתרוגים בסימנים — גם שאר האתרוגים שבאילן כשרים (שהרי לכל הדעות סימנים אלו — לבד קליפתו עבה להחת\"ס — אינם מובהקים וכו').\n<span data-k=\"q\">(ממכתב כ\"ג סיון תשכ\"ד)</span>\n<hr>\n... הציור (לנוי סוכה) נתקבל ות\"ח.\nלכאורה כדאי להוסיף בו אזהרה לשמור על קדושתו — ובפרט לשלול בהחלט הרגיל בהנהגות בנוי סוכה (לאחרי חה\"ס בפרט).\n<span data-k=\"q\">(ממכתב כ\"ב תמוז תשמ\"ו)</span>\n<hr>"],[1301550381,"<h3>ברכה</h3>\n... לההערות בספרי ר\"פ ברכה: מה שאמר הקב\"ה לבני עשיו (על השאלה מה כתיב בתורה) — לא תרצח ועד\"ז לבני עמון ומואב — לא תנאף ולבני ישמעאל — לא תגנוב, והרי לא זהו החידוש במתן תורה, כי כהנ\"ל הם מז' מצות ב\"נ.\n— ולהעיר מיבמות (מז, ב) אסיר לן ע\"ז וראה שם במפרשים.\nי\"ל כי הוכרח לומר להם דוקא ע\"ד מצות אלו. כי הם דוקא החמורות בשבילם היפך ענינם (כדמוכח מהמענה דכאו\"א מהנ\"ל \"כל עצמו\").\nואף שבלאה\"כ נצטוו ע\"ז (בז' מצות ב\"נ) — י\"ל בפשטות שהרי בשעת מ\"ת שאלם הקב\"ה היקבלו תורה ברצון וע\"ז ענו כל עצמו כו' ולכן א\"א לקבל כו'.\nועפ\"ז מובנת בפשטות המכילתא (יתרו כ, ב) דגם שם איתא כהנ\"ל בספרי ומסיים: ארשב\"א אם בז' מצות שנצטוו ב\"נ שקבלו עליהן אינן יכולין לעמוד בהן ק\"ו למצות שבתורה. ועד\"ז משמע גם בספרי שמסיים יכול שמעו וקבלו (התורה) ת\"ל ואותם לא יעשו ואומר כו' אלא אפילו ז\"מ שקיבלו עליהם ב\"נ לא יכלו לעמוד בהם עד שפרקום ונתנום לישראל. וק\"ל.\nלתרץ הספרי שכוונת הכתוב בהלא תרצח כו' היינו מה שמוסיף בציווי זה לבנ\"י — על האיסור דשפ\"ד דב\"נ — דוחק קצת, דא\"כ העיקר חסר מן הספר. אלא שקצת ראי' לזה ממענה בני עמון ומואב בשלילת לא תנאף ממש\"נ ותהרינה שתי בנות לוט מאביהן, דניתוסף איסור זה בג\"ע במ\"ת, אבל מותר לב\"נ. כן ממענה בני עשיו ממש\"נ על חרבך תחי', דפשיטא דלא תהי' ברכת יצחק לעבור על מצות ב\"נ.\nלמרז\"ל בשמו\"ר (פ\"ל, ט) דלעכו\"ם ניתנו מצות גולמיות — יש להעיר מפי' הרמב\"ן (וישלח לד, יג): ועל דעתי הדינין שמנו כו'. וראה ג\"כ חולין (צב, סע\"א) ל' מצות שקיבלו עליהם ב\"נ כו'.\n<span data-k=\"q\">(ממכתב אדר\"ח תמוז תשכ\"ד)</span>\n<hr>\n... ולסיום המכ' דמר לראות כהן כו' — וללוי אמר, להעיר ממש\"כ האריז\"ל (בלקוטי תורה ובשער הפסוקים ליחזקאל) שלעת\"ל יהיו הלוים כהנים. — ועיין תניא פ\"נ שהוסיף בזה \"שהלוים של עכשיו יהיו כהנים לעתיד\" — וי\"ל דבזה מיישב"],[1301550382,"הקושיא שהרי התורה אמרה לנו ולבנינו עד עולם [רמב\"ם הל'] יסוה\"ת רפ\"ט. ומבאר דאלה שעכשיו (ולא בזמן ההוא) הם לוים יהיו (כי יולדו) כהנים לעתיד. . .\n<span data-k=\"q\">(ממכתב ערב חג הסוכות בעלות המנחה תשכ\"ה)</span>\n<hr>\nבסוף הס'<sup data-n=\"1942\">*</sup> ע' 274 סמיכות התורה סופה לתחילתה בשם גדול אחד. הל' צריך תיקון, כי כנראה כוונתו להפי' הידוע שגודל הנס דמרע\"ה על הנסים דלאח\"ז אף שהיו באותו ענין עצמו (וכמו קרי\"ס וגינאי חלוק לי מימיך — דחולין ז, א), כי נס דמשה הי' בראשית — הראשון. והיסוד לפי' זה — הוא פי' הבעש\"ט במרז\"ל כל העולם ניזון בשביל (שפתח ועשה) חנינא בני (ראה ס' תולדות יעקב יוסף ר\"פ קדושים. ועיין ג\"כ מש\"כ רבנו הזקן בלקוטי תורה ס\"פ תזריע).\n— בסמיכות הנ\"ל יל\"פ ע\"פ קושית רז\"ל (נדרים לט, ב) והכתיב אין כל חדש תחת השמש. וזהו המשך הכתובים: לכל האותות והמופתים גו' אשר עשה גו' (ואין זה חדש כ\"א) בראשית ברא גו' כי תנאי התנה הקב\"ה עם כל מע\"ב בעת הבריאה בנוגע לנסים (כדרז\"ל (ב\"ר פ\"ה, ה. זח\"ב קצח, ב) פיהמ\"ש ותויו\"ט אבות פ\"ה מ\"ו).\n<span data-k=\"q\">(ממכתב יו\"ד מ\"ח תשכ\"ב)</span>\n<hr>\nבסופו<sup data-n=\"1943\">*</sup> רמו-ז דמשה כללות כל הנשמות ויהושע כללות כל הרוחות. — כ\"כ באוה\"ח (פנחס כז, יח). וצ\"ע וחיפוש המקור ע\"ז.\nשם. נעיצת סוף התורה לתחלתה. ע\"פ מה שמפרש עשה משה — ענין הסמיכה, יל\"פ הקישור ל\"בראשית\" — ע\"פ ת\"י (וזח\"א ג:) \"בחוכמא\", שבזה הו\"ע הסמיכה. ויומתק יותר עפמש\"כ אדמו\"ר הצ\"צ בס' המצות שלו מצות קדוש החודש (וש\"נ) דעין ועיני העדה ה\"ז חיצוניות החכמה (נו\"ה דאבא) וסמיכה צ\"ל ע\"י פנימיות החכמה (יסוד דאבא) — וזהו שמוסיף \"בראשית\" על מש\"כ לפני זה \"עיני כל ישראל\".\n<span data-k=\"q\">(ממכתב כ\"ה שבט תשכ\"ב)</span>\n<hr>",[["1942","*","רעיונות נתן עה\"ת. המו\"ל."],["1943","*","שאר ישוב עה\"ת. המו\"ל.\n<hr>"]]],[1301550383,"<h3>שמח\"ת</h3>\nנעם לי לקבל מכתבו, בו כותב אודות השמחה בשמחת תורה בקהלה קדישא דילי' בהשתתפות אנ\"ש שי' וכו'.\nויהי רצון ע\"פ דברי כ\"ק מו\"ח אדמו\"ר שחדש תשרי הוא חדש הכללי של כל השנה, ובפרט המועדים שבו, שמכל רגל בחדש זה ממשיכים ענינו בכל ימות השנה.\nהרי גם משמחה האמורה ביום זכאי האמור, תומשך שמחה של תורה ומצוה בכל ימי השנה הבע\"ל.\nוע\"פ מאמר חז\"ל אשר שמחה פורץ גדר, יבטלו המניעות והבלבולים ללימוד התורה בשופי וקיום מצותי' בהידור.\nובלשון המורה הגדול הוא הרמב\"ם, תרבה הדיעה והחכמה והאמת שנאמר כי מלאה הארץ דעה את ה' (תשובה ט, ב).\n<span data-k=\"q\">(ממכתב ל' תשרי תשכ\"ה)</span>\n<hr>\nהרב רחמ\"א שי' חדקוב מסר לי הידיעה על דבר נסיעתו ביחד עם זוגתו שתחי', והנני מאחל להם נסיעה בהצלחה, שהצלחה במושג היהודי היינו שבכל מקום שיהודי בא שמה ממלא שליחות בורא עולם ומנהיגו, שליחות של השפעה באורח חיים על פי תורת חיים ומצוותי' עליהן נאמר וחי בהם, חיים כפשוטו גם בעולם הזה.\nובטח שמע שהי' מנהג ליובאוויטש שבמוצאי שמחת תורה, בסיום הימים טובים דחודש השביעי והכנה לימי החול, להכריז ויעקב הלך לדרכו, פירוש לדרכו דרך הראוי לו מהשם יתברך המשגיח על כל אחד ואחד בהשגחה פרטית, שאז זוכה לסיום הכתוב ויפגעו בו מלאכי אלקים, לשמרו בדרך ולהגיעו למחוז חפצו.\nויהי רצון שימסור לאחינו בני ישראל בכל מקום שהם דברי התעוררות, בפרט אחרי ביקורו במדינות שמאחורי המסך, שיכול ללמד להם ק\"ו, ומה שבתנאים ההם יהודים מתלבטים להשאר נאמנים לה' ולתורתו במסירות נפש ממש, על אחת כמה וכמה שכל יהודי הזוכה לגור במדינות שיש בהן חופש הדת שמחובתו וזכותו לנצל"],[1301550384,"האפשריות במילואה בכיוון הנ\"ל ולהיות עינו טובה גם בשל אחרים עד כמה שידו מגעת ובאופן דמוסיף והולך.\n<span data-k=\"q\">(ממכתב כ' מרחשון תשכ\"א)</span>\n<hr>\n... בשאלתו:\nא) איך לתקן את מה שקרה בשמחת תורה, אשר בין הבאים להשתתף בהקפות דישיבת אהלי יוסף יצחק היו אחדים שבאו במכונות כו'.\nהתיקון בזה פשוט, ולפלא שגם בשנה זו לא עשו זה, והוא שאיזה ימים לפני מועד כהנ\"ל ידפיסו מודעה בעתונים (ומה טוב ביחד עם ההודעה ע\"ד זמני ההקפות וכיו\"ב), אשר בודאי פשוט וידוע איסור נסיעה במכונה בשבת ויו\"ט, והסתירה שמני' ובי' להשתתף בענין תורני באופן היפך התורה.\nב) ע\"ד העלי' לתורה של כאלו שאין ברור אופן שמירתם התורה והמצוה.\nכבר שאלוני פעם עד\"ז מביהכ\"נ דישיבת אהל יוסף יצחק במעלבורן, ועניתי אז, ומענה זו גם עתה בתקפו הוא, שהחלטה בזה תלוי' בכו\"כ פרטים, הן בהנוגע לאופן הנהגתו של זה הרוצה לעלות לתורה והן בהנוגע להנמצאים בביהכ\"נ והרושם עליהם, שככל הענינים הנעשים בפרהסיא גם זה צריך להביאו בחשבון, ובהתאם להבירור בהאמור יש על אלו הנמצאים על אתר להחליט, אלא שמובן ע\"פ מרז\"ל לעולם תהא ימין מקרבת ושמאל וכו' שבאופן כזה צריך להתנהג גם בשאלה האמורה, ובפרט כשיש ספק אם צריך בכלל לדחות אפילו בשמאל, והרי כבר נאמר, דרכי' דרכי נועם וכל נתיבותי' שלום.\n<span data-k=\"q\">(ממכתב י\"ח מ\"ח תשי\"ז)</span>\n<span data-k=\"q\"> </span>\n<span data-k=\"q\"> </span>\n<hr>"],[1301660002,"<h1>כרך לה</h1>\nספרי' — אוצר החסידים — ליובאוויטש\n——————————————————————————————\nקובץ\nשלשלת האור\nהיכל שער\nתשיעי שלישי\nלקוטי שיחות\n— ל\"ה —\nעל פרשיות השבוע, חגים ומועדים\nמכבוד קדושת\nאדמו\"ר מנחם מענדל\nשניאורסאהן\nמליובאַוויטש\nספר תשיעי — כרך ראשון\nבראשית\n— הוצאה חדשה ומתוקנת עם הוספות —\nיוצא לאור על ידי מערכת\n\"אוצר החסידים\"\n770 איסטערן פארקוויי ברוקלין, נ.י.\nשנת חמשת אלפים שבע מאות חמשים ושש לבריאה"],[1301660003,"לקראת יום העשירי \"בעשתי עשר חודש הוא חודש שבט\"<sup data-n=\"0\">1</sup> הבעל\"ט\nבו ימלאו מ\"ו שנה לנשיאות כ\"ק אדמו\"ר מלך המשיח —\nהננו מוציאים לאור בזה — בהמשך לספרי לקו\"ש שהופיעו<sup data-n=\"1\">2</sup> — ספר לקוטי שיחות חלק לה על ספר בראשית (הכרך הראשון של הספר התשיעי של לקו\"ש).\n* * *\nכרך זה כולל:\nא) הלקו\"ש על פרשיות התורה (והמועדים) ד(זמן קריאת) ספר בראשית שנדפסו בקונטרסים בודדים מדי שבוע בשבוע, במשך שנות תש\"נ — תשנ\"ב<sup data-n=\"2\">3</sup>.\nב) שיחת ד' מרחשון אור ליום וערש\"ק פ' נח תשל\"ז (נדפסה בלקו\"ש לפ' נח תשנ\"ה)<sup data-n=\"3\">4</sup>.\nג) מכתבים שתוכנם שייך לפרשיות השבוע (ומועדים) הכלולים בספר. וכדאי לציין, שמדור זה לפ' חיי שרה כולל לקט מכתבים בעניני ניחום אבלים: י\"ט כסלו — בלימוד פנימיות התורה והפצתה: פ' ויחי — בעניני פטירה אבילות וכו'.\nוזאת למודעי: חלק גדול מהמכתבים שבכרך זה נדפסו בסדרת \"אגרות­קודש\" מכ\"ק אדמו\"ר מלך המשיח, שהולכת ונדפסת כעת על סדר השנים (לע\"ע יצאו לאור כ\"ג כרכים<sup data-n=\"4\">5</sup>). וע\"פ בקשת רבים נלקטו כאן מהמכתבים שתוכנם שייך לפרשיות השבוע (ומועדים) דספר בראשית.\nד) לתועלת המעיינים הוספנו בסוף הספר (כמו בכרך ל­לד) מפתח ענינים, פסוקים, מחז\"ל וספרים.\n* * *\nויה\"ר שנזכה בקרוב להו\"ל עוד שיחות ומאמרים של כ\"ק אדמו\"ר מלך המשיח, וזכות לימוד והדפסת תורתו הקדושה, תוסיף בחיזוק התקשרות שלנו עם כ\"ק אדמו\"ר מלך המשיח, ובחודש שבט זה תקויים בו המרומז בחודש שבט — גאולה האמיתית והשלימה ע\"י משיח צדקנו,\n[כמבואר בשיחת כ\"ק אדמו\"ר מה\"מ<sup data-n=\"5\">6</sup> אשר\n\"ענין הגאולה מרומז בשמו של החודש — \"שבט\" — שהוא (א) מלשון \"שבטי מושלים\"<sup data-n=\"6\">7</sup>, ובפרט הממשלה דמלכות בית דוד, כמ\"ש<sup data-n=\"7\">8</sup> \"לא יסור שבט מיהודה (מדוד ואילך אלו ראשי גלויות שבבבל שרודין את העם בשבט) . . עד כי יבוא שילה\" (מלך המשיח), עליו נאמר<sup data-n=\"8\">9</sup> \"וקם שבט (מלך רודה ומושל) מישראל\", \"זה מלך המשיח\"<sup data-n=\"9\">10</sup>, (ב) מלשון ענף אילן<sup data-n=\"10\">11</sup>, כמ\"ש<sup data-n=\"11\">12</sup> \"ויצא חוטר מגזע ישי ונצר משרשיו יפרה\"<sup data-n=\"12\">13</sup>, \"יצא שבט מלוכה משורש ישי מזרע דוד הוא מלך המשיח<sup data-n=\"13\">14</sup>]\nוכ\"ק אדמו\"ר מלך המשיח יקום ויגאלינו ויוליכנו קוממיות לארצנו הקדושה, ונלמוד תורה מפיו של משיח צדקנו<sup data-n=\"14\">15</sup>, \"תורה חדשה מאתי תצא\"<sup data-n=\"15\">16</sup>, ומלך ביפיו תחזינה עיניך<sup data-n=\"16\">17</sup> בהתגלות מלכותו לעין כל, תיכף ומיד ממש, והיתה לה' המלוכה<sup data-n=\"17\">18</sup>, אמן כן יהי רצון.\nועד להפצת שיחות\nג' שבט, ה'תשנ\"ו.\nברוקלין, נ.י.\n<hr>\nספר ראשון\nחלק א — בראשית שמות ויקרא: תשכ\"ב. הוצאה שני' — תשכ\"ז. הוצאה שלישית — תשל\"ה. הוצאה רביעית — תשל\"ט. הוצאה חמישית — תשמ\"ה. הוצאה ששית — תנש\"א. הוצאה שביעית — תשנ\"ו.\nחלק ב — במדבר דברים. הוספות: שיחות בראשית­דבריםמכתבים בראשית­דבריםמפתחות לכרכים א­ב: תשכ\"ב. הוצאה שני' — תשכ\"ז. הוצאה שלישית — תשל\"ה. הוצאה רביעית — תשל\"ט. הוצאה חמישית — תשמ\"ה. הוצאה ששית — תשנ\"ב.\nספר שני\nחלק ג — בראשית שמות ויקרא: תשכ\"ד. הוצאה שני' — תשכ\"ח. הוצאה שלישית — תשל\"ה. הוצאה רביעית — תשל\"ט. הוצאה חמישית — תשמ\"ה. הוצאה ששית — תשנ\"ב.\nחלק ד — במדבר דבריםפרקי אבות. הוספות: מכתבים ושיחות— בראשית­דבריםמפתחות לכרכים ג­ד: תשכ\"ד. הוצאה שני' — תשכ\"ח. הוצאה שלישית — תשל\"ה. הוצאה רביעית — תשל\"ט. הוצאה חמישית — תשמ\"ה. הוצאה שישית — תשנ\"ג.\nספר שלישי\nחלק ה' — בראשית. הוספות: מדור שיחות (תשכ\"ה)מכתבים ושיחות: י\"א ניסן תשל\"ב. הוצאה שני' ומתוקנת — ט\"ו מנ\"א תשל\"ח. הוצאה שלישית ומתוקנת — כ\"ה מ\"ח תשמ\"ט.\nחלק ו' — שמות. הוספות מכתבים ושיחות: יו\"ד שבט תשל\"ג. הוצאה שני' ומתוקנת — ט\"ו מנ\"א תשל\"ח. הוצאה שלישית ומתוקנת — מוצש\"ק כ\"ב שבט תש\"נ.\nחלק ז' — ויקרא. הוספות מכתבים ושיחות: עש\"ק כ\"ף מנ\"א תשל\"ג. הוצאה שני' ומתוקנת — ט\"ו מנ\"א תשל\"ח. הוצאה שלישית ומתוקנת — י\"ב תמוז תשנ\"ב.\nחלק ח' — במדבר. הוספות מכתבים ושיחות: עש\"ק יו\"ד שבט תשל\"ד. הוצאה שני' ומתוקנת — ט\"ו מנ\"א תשל\"ח. הוצאה שלישית ומתוקנת — ח\"י אלול תשנ\"ב.\nחלק ט' — דברים. הוספות: מכתבים ושיחותמכתבים כלליים לר\"ה: יו\"ד כסלו תשל\"ה. הוצאה שני' ומתוקנת — ט\"ו מנ\"א תשל\"ח. הוצאה שלישית — ט'­יו\"ד כסלו תשנ\"ד.\nספר רביעי\nחלק יו\"ד — בראשית. הוספות מכתבים ושיחות: י\"א ניסן תשל\"ה. הוצאה שני' ומתוקנת — ו' תשרי תשמ\"ב.\nחלק י\"א — שמות. הוספות מכתבים ושיחות: יו\"ד שבט תשל\"ו. הוצאה שני' ומתוקנת — י\"ג ניסן תשמ\"ג.\nחלק י\"ב — ויקרא. הוספות מכתבים ושיחות: יו\"ד שבט תשל\"ז. הוצאה שני' ומתוקנת — עשק\"מ אדר ראשון, תשד\"מ.\nחלק י\"ג — במדבר. הוספות מכתבים ושיחות: פורים קטן תשל\"ח. הוצאה שני' ומתוקנת — י\"ג ניסן תשמ\"ה.\nחלק י\"ד — דברים. הוספות: מכתבים ושיחותמכתבים כלליים לר\"ה: ימי הסליחות תשל\"ח. הוצאה שני' ומתוקנת — ג' סליחות תשמ\"ו.\nספר חמישי\nחלק ט\"ו — בראשית. הוספות מכתבים ושיחות: מוצש\"ק ר\"ח שבט תש\"מ. הוצאה שני' ומתוקנת — מוצש\"ק ט\"ו בשבט תשמ\"ז.\nחלק ט\"ז — שמות. הוספות מכתבים ושיחות: עש\"ק ח\"י אלול תש\"מ. הוצאה שני' ומתוקנת — ועש\"ק ג' כסלו תש\"נ.\nחלק י\"ז — ויקרא. הוספות מכתבים ושיחות: י\"ג אייר תשמ\"א. הוצאה שני' ומתוקנת — ט\"ו אלול תש\"נ.\nחלק י\"ח — במדבר. הוספות מכתבים ושיחות: שבת מברכים ופ' החודש תשמ\"ב. הוצאה שני' ומתוקנת — ערב ש\"ק פ' יתרו, כ\"ב שבט תש\"נ.\nחלק י\"ט — דברים. הוספות: מכתבים ושיחותמכתבים כלליים לר\"ה: ט\"ו מ\"ח תשמ\"ג. הוצאה שני' ומתוקנת — ט\"ו בשבט, תשנ\"ב.\nספר ששי\nחלק כ — בראשית. הוספות: מאמרים ושיחות תשל\"חמדור שיחות (תשל\"ח­תשמ\"ב)מכתבים ושיחות: ימי חנוכה תשמ\"ג. הוצאה שני' ומתוקנת — ימי חנוכה תשמ\"ט.\nחלק כ\"א — שמות. הוספות: מדור שיחות (תשל\"ח­תשמ\"א)מכתבים ושיחות: ר\"ח ניסן תשמ\"ג. הוצאה שני' ומתוקנת — ט\"ו תמוז, תנש\"א.\nחלק כ\"ב — ויקרא. הוספות: מדור שיחות (תשל\"ט­תשמ\"ג)מכתבים ושיחות: ה' מנ\"א תשמ\"ג. הוצאה שני' ומתוקנת — ג' טבת תשנ\"ה.\nחלק כ\"ג — במדבר. הוספות: מדור שיחות (תשל\"ט­תשמ\"ג)מכתבים ושיחות: ר\"ח ניסן תשד\"מ. הוצאה שני' ומתוקנת — כ\"ח אלול תש\"נ.\nחלק כ\"ד — דברים. הוספות: מדור שיחות (תשל\"ט­תשמ\"א)מכתבים ושיחותמכתבים כלליים לר\"ה: ש' חזון תשמ\"ה.\nספר שביעי\nחלק כ\"ה — בראשית. הוספות: מדור שיחות (תשמ\"ג­תשמ\"ז)מכתבים: ר\"ח ניסן תשמ\"ז.\nחלק כ\"ו — שמות. הוספות: מדור שיחות (תשד\"מ­תשמ\"ו)מכתבים: מוצש\"ק ר\"ח ניסן תשמ\"ח.\nחלק כ\"ז — ויקרא. הוספות: מדור שיחות (תשד\"מ­תשמ\"ו)מכתבים: כ\"ה אדר א' תשמ\"ט.\nחלק כ\"ח — במדבר. הוספות: מדור שיחות (תשד\"מ­תשמ\"ו)מכתבים: עש\"ק פ' ויקרא תש\"נ.\nחלק כ\"ט — דברים. הוספות: מדור שיחות (תשמ\"ג­תשמ\"ו)מכתביםמכתבים כלליים לר\"ה: מוצש\"ק פ' החודש תנש\"א.\nספר שמיני\nחלק ל — בראשית. הוספות מכתבים ומפתחות: י\"א ניסן תשנ\"ב.\nחלק ל\"א — שמות. הוספות מכתבים ומפתחות: כ\"ף מנ\"א תשנ\"ב.\nחלק ל\"ב — ויקרא. הוספות מכתבים ושיחות ומפתחות: כ\"ה אדר תשנ\"ג.\nחלק ל\"ג — במדבר. הוספות מכתבים ושיחות ומפתחות: ר\"ח ניסן תשנ\"ד.\nחלק ל\"ד — דברים. הוספות מכתביםמכתבים כלליים לר\"המפתחות: ג' ניסן תשנ\"ה.\nספר תשיעי\nחלק ל\"ה — בראשית. הוספות מכתבים ושיחות ומפתחות: ג' שבט תשנ\"ו.",[["0","1","זכרי' א, ז. וראה לקמן בסוף הפתח דבר מסה\"ש תשנ\"ב ובהערה 6."],["1","2","ראה רשימה מפורטת לקמן בסוף הספר."],["2","3","וזאת למודעי, אשר השיחות שנאמרו בשנים הנ\"ל ויצאו לאור בשעתם בקונטרסים בפני עצמם — לא נכללו בהוספות דספר זה, אלא נדפסו ב\"ספר השיחות תש\"נ\" ו\"ספר השיחות\" תשנ\"א­ותשנ\"ב — כל שנה — בשני כרכים."],["3","4","כ\"ק אדמו\"ר מה\"מ הגי' את השיחה בשעתה, אלא שנשארו איזה ענינים (הערות 2. 72) שלא השלים (נוסף על סימנים שרשם על גליון העמודים בכמה מקומות (בסעיף ג' סוף קטע הא'. הערות 8. 19. 45. 60), שבדעתו הק' לחזור ולעיין כו'), וכמו\"כ באיזה מקומות לא פתר ספיקות רושם השיחה (ס\"ח קטע ב' (אם האמהות בכלל). הערות 39. 40. 94). וכפי הנראה זוהי הסיבה שלא נמסרה להו\"ל אז.\nהשיחה נמצאה בשבועות שלאחרי ג' תמוז תשנ\"ד, ונדפסה לש\"פ נח תשנ\"ה."],["4","5","הכוללים המכתבים עד סוף שנת תשכ\"ה."],["5","6","ספר השיחות תשנ\"ב ע' 264, וש\"נ. וראה שם לפנ\"ז \"תכלית השלימות דלעתיד לבוא המרומזת בחודש האחד עשר, אחד שלמעלה מעשר ספירות\"."],["6","7","יחזקאל יט, יא."],["7","8","ויחי מט, יו\"ד ובפרש\"י."],["8","9","בלק כד, יז ובפרש\"י."],["9","10","רמב\"ם הלכות מלכים רפי\"א."],["10","11","ראה (לדוגמא) ישעי' כח, כז."],["11","12","שם יא, א."],["12","13","ובהמשך הכתובים (שם, ד) — \"והכה ארץ בשבט פיו\"."],["13","14","מצו\"ד על הפסוק."],["14","15","ראה רמב\"ם הלכות תשובה פ\"ט ה\"ב. לקו\"ת צו יז, א­ב. שער האמונה פנ\"ו ואילך. ועוד."],["15","16","ישעי' נא, ד. ויק\"ר פי\"ג, ג."],["16","17","ישעי' לג, יז."],["17","18","עובדי' בסופו."]]],[1301680001,"<h3>בראשית</h3>\nשיחה א (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 1\nפלוגתת המפרשים אם אדם הראשון קרא שמות גם לדגים (רד\"ק וחזקוני ב, יט. מדרש חסר ויתיר); הביאורים השונים בתוכן ענין קריאת שמות ע\"י אדה\"ר\nשיחה ב (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 7\nההבדל בין חנוך בנו של קין שבו נאמר (ד, יז) \"ויהי (קין) בונה עיר ויקרא שם העיר כשם בנו חנוך\" — יישוב העולם, וחנוך מצאצאי שם שנאמר בו (ה, כד) \"ואיננו כי לקח אותו אלקים\"; ב' התקופות — לפני המבול ואחרי המבול — בעבודת בנ\"י וההתכללות ביניהן\n<h3>נח</h3>\nשיחה א (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 15\n\"נח איש צדיק תמים הי' בדורותיו\" — \"אבל בדרין אחרנין אינו נחשב לכלום כגון דרא דאברהם . . דמשה . . דדוד\" (זהר ח\"א ס, א) — ענינם של ג' הדורות דאברהם משה ודוד ושייכותם לנח, וביאור בלקוטי לוי\"צ לזהר שם\nשיחה ב (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 24\nההבדל בין פסול בעל מום שלא נאסר לב\"נ (זבחים קטו, ב), לפסול מחוסר אבר שאסור גם בב\"נ (זבחים שם); שיטת הרמב\"ם (הל' איסורי מזבח רפ\"ג) דפסול מחוסר אבר בעוף הוא לפי ש\"אין מקריבין חסר כלל\"; הטעם הפנימי שהדוגמא הרגילה דבעל מום שמותר בב\"נ ועוף היא \"דוקין שבעין\" דוקא\nשיחה ג (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 31\nההבדל בין שיטת הב\"ר (פל\"ה, ב) ופרש\"י (ט, יב) אודות הדורות שלא נראתה הקשת בימיהם; כיצד אפשר לומר שרק בדור של צדיקים גמורים אין צריכים לאות הקשת\n<h3>לך לך</h3>\nשיחה א (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 39\nחמשה קנינים קנה הקב\"ה בעולמו . . תורה . . שמים וארץ . . אברהם . . ישראל . . ביהמ\"ק (אבות פ\"ו, י) — גדרו של \"קנין\" ש\"קנה הקב\"ה בעולמו\", ויישוב כמה דיוקים בלשון הברייתא\nשיחה ב (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 45\nהשייכות בין הבטחת ירושת הארץ וברית מילה ע\"פ מ\"ש בלקוטי לוי\"צ (לקוטי לוי\"צ על זהר ח\"ב ע' מז) שע\"י המילה \"יירשו הארץ, ירושה אין לה הפסק\"; שני גדרים בברית מילה — ברית של אאע\"ה ששייך להפירה ובריתו של הקב\"ה שאין בה הפסק, ודוגמתן בירושת הארץ\nשיחה ג (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 53\nג' הלימודים שמילה דוחה שבת — מגז\"ש \"אות ברית ודורות\" (דפרשתנו יז, יא­יב); מהכתוב (תזריע יב, ג) \"ביום השמיני ימול\"; מ\"ושמרו בנ\"י את השבת\" (תשא לא, טז ובמכילתא שם) — הנפק\"מ בין ג' הלימודים בהלכה וע\"ד החסידות; הטעם שכח המסירת נפש שישנו בכל ישראל הוא ירושה מאבותינו (תניא פי\"ח), היינו קודם מ\"ת\n<h3>וירא</h3>\nשיחה א (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 61\nשקו\"ט בהא דאין חובת חינוך אלא דרבנן, ואילו מה\"ת אין חיוב להכין את הקטן לזמן גדלותו; איך אפ\"ל דאצל אברהם היו \"יומין שלימין\" (זח\"א קכט, א. ועוד), והרי לא הכיר את בוראו רק בהיותו בן ג' שנים (נדרים לב, סע\"א)\nשיחה ב (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 70\nטעם ההבדל בין סדום ועמורה שנשרפו וד' הערים שרק נהפכו (יט, כד­כה וברש\"י שם) ע\"ד הפשט; הביאור הפנימי במ\"ש בנבואת יחזקאל (טז, נג) שלעתיד ישובו ערי סדום\nשיחה ג (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 76\nפרש\"י כב, יב ד\"ה כי עתה ידעתי (הא'): א\"ר אבא א\"ל אברהם אפרש לפניך את שיחתי אתמול אמרת לי כו' וחזרת ואמרת כו' א\"ל הקב\"ה לא אחלל בריתי כו' — ההכרח בפשוטו של מקרא לכל דו\"ד אלו בין אברהם והקב\"ה, והשייכות לשיטת ר' אבא (חגיגה טז, א) ד\"כל שלא חס על כבוד קונו\" היינו \"זה המסתכל בקשת\"\n<h3>חיי שרה</h3>\nשיחה א (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 82\nפרש\"י כג, יז ד\"ה ויקם שדה עפרון — \"תקומה היתה לו שיצא מיד הדיוט ליד מלך\" — ע\"פ פשט, וההוראה מזה בעבודת כאו\"א\nשיחה ב (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 89\n\"ואברהם זקן בא בימים\" (כד, א) — והרי כבר נאמר (וירא יח, יא) \"ואברהם ושרה זקנים באים בימים\"; פירוש ד\"בא בימים\" ע\"ד הפשט והתאמתו לפירוש הזהר (פרשתנו קכט, א); ביאור לשון הכתוב \"ויהיו חיי שרה\" (ולא \"ימי שרה\") ולשון רש\"י (ריש פרשתנו) ש\"כולן שוין לטובה\"\nשיחה ג (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 94\nהנס שנעשה לאברהם שנולדו לו עוד ששה בנים (מקטורה) לעת זקנותו, והנסים שקרו בעת לידת יצחק (רש\"י וירא כא, ו); שני האופנים בפעולה על אומות העולם, הנרמזים בשני פרקים האחרונים דס' היד להרמב\"ם\n<h3>תולדות</h3>\nשיחה א (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 101\nביאור דברי ר' יהודה החסיד (הובאו במדבר קדמות להחיד\"א בתחילתו) שט\"ו שנים למדו האבות תורה ביחד בכל יום ט\"ו שעות, ובס' חסידים (סי' קס\"ה) שעסקו בעבודת השם כל כ\"ד שעות היום, ותיווך החיד\"א דט\"ו שעות למדו תורה וט' שעות עסקו בתפלה; דוגמת התחברות זו בג' אבות החסידות — הבעש\"ט הרב המגיד ממעזריטש ואדמו\"ר הזקן\nשיחה ב (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 107\nההבדל בין דברי המשנה (סוף קידושין) \"עשה א\"א את כל התורה כולה עד שלא ניתנה\", ומאמרו של רב (יומא כח, ב) \"קיים אברהם אבינו כה\"ת כולה\"; דוגמת שני אופנים הנ\"ל בתומ\"צ דאברהם בלימוד התורה שלנו (אחרי מ\"ת)\nשיחה ג (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 113\nפרש\"י סוף פרשתנו ד\"ה על נשיו — \"הוסיף רשעה על רשעתו כו'\"; השינוי בין שיטת רש\"י ושיטת המד\"ר כאן בטיב רשעתו של עשו בלקיחת מחלת וכן אם מחלת היתה מרשעת; ההוראה בגודל הזהירות מענין ה\"צביעות\" ורע הנעלם וביאור במאמר אדמו\"ר הזקן (מאמרים הקצרים ע' תנב) בטעם אריכות גלות זה האחרון\n<h3>ויצא</h3>\nשיחה א (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 119\nפרש\"י ר\"פ \"יציאת צדיק מן המקום עושה רושם כו' . . פנה הודה כו'\"; השינויים לגבי ל' הב\"ר (פס\"ח, ו) וכן השינוי בפרש\"י רות א, ז; פירוש ג' הענינים ד\"הדרה\" ו\"זיוה\" ו\"הודה\" לפי פשוטו\nשיחה ב (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 125\nב' הסדרים בג' התפלות — שחרית מנחה ערבית או ערבית שחרית מנחה; שני הגדרים בעבודת התפלה ע\"פ הלכה ובעבודה רוחנית ע\"ד החסידות\nשיחה ג (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 131\nפרש\"י עה\"פ לא, י ד\"ה וברודים; הטעם שלפי שיטת רש\"י נתחדשה צורה זו ד\"ברודים\" בחלום יעקב; התאמת פרטי לשון רש\"י בפירוש \"ברודים\" לענינו של \"עולם הברודים\" המבואר בספרי קבלה\n<h3>וישלח</h3>\nשיחה א (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 137\nהטעם לשינוי השם — \"פניאל\" או \"פנואל\" — ע\"פ שיטת רש\"י בפשוטו של מקרא; ביאור בדברי הצ\"צ (אוה\"ת עה\"פ) ד\"פניאל\" היא העבודה דפנימיות הלב ו\"פנואל\" היא המשכת אלקות בעולם\nשיחה ב (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 143\nפרש\"י עה\"פ לג, טז ד\"ה וישב עשו גו' — ההכרח בפשוטו של מקרא ש\"ד' מאות איש שהלכו עמו נשמטו מאצלו אחד אחד\", והטעם שהביא רש\"י שהקב\"ה פרע להם בימי דוד והשינויים בל' רש\"י לגבי ל' הב\"ר (פע\"ח, טו); הקשר לגאולת אדה\"ז בי\"ט כסלו באופן של \"פדה בשלום נפשי גו'\"\nשיחה ג (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 150\nפרש\"י עה\"פ לד, א ותצא דינה — יציאת דינה כיציאת לאה שהיתה למעליותא; ההבדל בין רחל ולאה בעבודה רוחנית — צדיקים ובע\"ת\n<h3>וישב</h3>\nשיחה א (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 156\nפרש\"י עה\"פ לז, י ד\"ה הבוא נבוא; שקו\"ט בהכלל ד\"אין חלום בלא דברים בטלים\"; איך יתכן שיעקב הי' ממתין ומצפה מתי יתקיים החלום שישתחווה לבנו יוסף; צפיית יעקב למלוכת יוסף על אחיו ע\"פ פנימיות הענינים\nשיחה ב (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 163\nפרש\"י עה\"פ מ, א אחר הדברים האלה; פירוש הלשון \"הדברים האלה\" בפשוטו של מקרא; הצורך בשני פירושים ע\"פ פשט ובפנימיות הענינים; ביאור החידוש בדרשת ר' ירמי' בר אבא (חולין צב, א) עה\"פ (מ,י) ובגפן שלשה שריגים, והשייכות אליו וכן לרב ש\"דריש להני קראי כוותך\" (חולין שם); הקשר לי\"ט כסלו\nוישב — חנוכה (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 169\nביאור בפלוגתת רש\"י והרמב\"ן (לז, יז) אם יוסף הלך לבקש את אחיו בידעו שהם מבקשים להמיתו או לא — ע\"ד ההלכה; דוגמת מס\"נ דיוסף אצל החשמונאים בימי חנוכה; דיוק הלשון בנוסח \"הנרות הללו\" שהתשועות כו' היו \"על ידי כהניך הקדושים\"\n<h3>מקץ</h3>\nשיחה א (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 176\nפרש\"י עה\"פ (מא, יד) ויגלח — \"מפני כבוד המלכות\"; ההבדל בין גילוח וחליפת השמלות בפשוטו של מקרא; שני הענינים ע\"ד ההלכה וע\"פ פנימיות הענינים, והקשר לראש השנה (שאז יצא יוסף מבית האסורים — ר\"ה י, ב)\nשיחה ב (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 181\nוטבוח טבח והכן (מג, טז) — \"פרע להם בית השחיטה כו'\" (חולין צא, סע\"א); שקו\"ט בשיטת רש\"י בפירושו עה\"ת אם היתה שחיטה כשירה או לאו\nחנוכה (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 187\nשקו\"ט בספיקו של כ\"ק אדמו\"ר הריי\"צ נ\"ע (אג\"ק שלו ח\"ב ע' שח) אם מזכירים פסוקי ר\"ח בהפטרת שבת חנוכה שחל בר\"ח; הספק הנוסף לגבי הוספת גם פסוקי מחר חודש\n<h3>ויגש</h3>\nשיחה א (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 192\nהפלוגתא בדין \"לא ישמיע קולו\" בתפלה, אם היינו אפילו לעצמו (ע\"פ זהר פרשתנו רי, א) או רק לאחרים (רמב\"ם הל' תפילה פ\"ה ה\"ט) ופלוגתת הטור והב\"י (או\"ח סק\"א) מתי הותר להשמיע קולו לאחרים; כמה אופנים בטעם האיסור להשמיע קולו לאחרים וביאור דברי אדה\"ז (תו\"א סוף פרשתנו) דלעת\"ל יהי' שמו\"ע בקול רם\nשיחה ב (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 198\nאל תרגזו בדרך (מה, כד) — אל תתעסקו בדבר הלכה (תענית י, ב), \"אל תעמידו עצמכם מדברי תורה\" (ב\"ר פצ\"ד, ב) או \"אל תפסיקו מדבר הלכה\" (מדרש הובא בתוס' תענית שם); שקו\"ט בגדר חיוב ת\"ת בעת הליכה בדרך\nשיחה ג (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 206\nהפטרת פרשתנו: ועבדי דוד מלך עליהם . . ודוד עבדי נשיא להם לעולם (יחזקאל לז, כד­כה) — ההבדל בין שני הענינים ד\"מלך עליהם\" ו\"נשיא להם\"; ביאור דברי הש\"ס (סנהדרין צח, ב) \"עתיד הקב\"ה להעמיד להם דוד אחר . . כגון קיסר ופלגי קיסר\"\n<h3>ויחי</h3>\nשיחה א (תש\"נ) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 211\nפרש\"י עה\"פ מז, לא ד\"ה וישתחו ישראל — \"תעלא בעידני' סגיד לי'\"; ההבדל בין זה ללשון רש\"י להלן (מח, ב) \"מכאן שחולקין כבוד למלכות\"\nשיחה ב (תשנ\"ב) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 216\nסיום מס' נזיר — ביאור הפלוגתא אם מברך עדיף או גדול העונה אמן כו'; השייכות דסוגיא זו לתוכן מס' נזיר, ע\"פ דברי הצפע\"נ עה\"ת (בפ' וישב) בגדר נזירות יוסף (פרשתנו מט, כו)\nשיחה ג (תנש\"א) . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 223\nביאור בסיפור הש\"ס (תענית ה, ב) רב נחמן ורב יצחק הוי יתבי בסעודתא כו' אין מסיחין בסעודה כו' יעקב אבינו לא מת כו' מה זרעו בחיים אף הוא בחיים; שקו\"ט בהא שפעולת התומ\"צ צ\"ל באופן טבעי דוקא\n<h3>הוספות</h3>\n<h4>בראשית</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 231\nביאור בדברי המדרש רבה ר\"פ בראשית — ואהי' אצלו אמון כו' אני הייתי כלי אומנתו: ד' מדריגות שבתורה (פרד\"ס) ומהם נמשך בעולם; פירוש \"בראשית\" בשביל התורה או ע\"י התורה ראשית הכל יראת ה' וידיעת ה' הלימוד מזה שבריאת העולם היא ע\"י ב' אותיות בלבד, ג' אופנים בהפלאת הבורא מהנברא ההפרש בין בריאה ואצילות צמצום כפשוטו אינו בסתירה לעבודה בחב\"ד אל תקרי מחי' אלא מהווה הערה בשער היחוד והאמונה ספ\"ד בענין בוצינא דקרדוניתא; אגה\"ק ס\"ה דה' תתאה מורה על ד' סטרין הרמז בזה שבכל מקום בכדור הארץ האדם מרגיש עצמו למעלה ביאור מ\"ש בתניא פ\"ט שבחלל הימני שבלב אין דם ביאור מ\"ש בתניא ספ\"א שנפשות או\"ה אין בהם טוב כלל וההתאמה עם ענין שבע מצוות ב\"נ וחסידי או\"ה (ביאור ברמב\"ם בענין חיוב ז' מצוות ב\"נ) עוד בענין הנ\"ל בירור הגירסא במרז\"ל שלשה אמרו אמת ואבדו מן העולם מדוע נק' ק\"נ עה\"ד טו\"ר, והרי עה\"ד הי' אסור, גקה\"ט תערובת טו\"ר בכל דבר הא דחסד הוא גם למי שאינו ראוי\n<h4>נח</h4>\nשיחת ד' מ\"ח אור לועש\"ק פ' נח — תשל\"ז . . . . . . . . . . . . . . . . . . . . 240\nמעלת ההתוועדות באופן שנשמעים הדברים בכל העולם ע\"י שידור (בדוגמת \"וראו כל בשר\" דלע\"ל); הקשר לחידושי חכמת האומות \"בשנת שש מאות שנה לחיי נח\" ע\"פ דברי הזהר, דקאי גם על גילוי פני' התורה, ובפרט כשהפצת פני' התורה היא ע\"י חידושי המדע, דהוי הכנה אל הגילוי דלעתיד . . . . . . . . . . . . . . . . . . . ס\"א­ג\nהכרזת \"ויעקב הלך לדרכו\" בד' אמות דנשיא הדור באופן שנשמע בכל העולם; בפרט שביום זה עשו הקפות בקרית ארבע היא חברון ובירושלים העתיקה, בהמשך להקפות דכאן; נקודת מועדי חודש תשרי וההקפות — אחדות ישראל, וענין זה בהדגשה ב\"קר­ית ארבע היא חברון\" (חיבור ד' היסודות) ומערת המפלה שכפולה בזוגות . . . ס\"ד­ח\nביטול ושלילת הסברא ה\"פראית\" ד\"חלוקת\" מערת המפלה שקנה אברהם בכסף מלא עוד לפני מציאות דת ישמעאל, וכן בנוגע לשלימות כל ארץ ישראל . . . . . . . ס\"ט­י\n\"שלימות הארץ\" קשורה עם שלימות התורה — וכל המבצעים וכל תרי\"ג מצוות עד לעסק לשם שמים בעניני רשות, \"ויעקב הלך לדרכו\"; וזהו החידוש דהכרזת \"ויעקב הלך לדרכו\" שבחודש חשון . . . . . . . . . . . . . . . . . . . . . . . . . . . . . סי\"א­יג\nכל התפלות עולות למעלה דרך מערת המכפלה, ומזה מובן מעלת ההקפות שם; ההמשך לאח\"ז בירושלים העתיקה כמו דוד שמלך בחברון לפני ירושלים; נתינת תודה ויישר כח למשתתפים . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . סי\"ד­טז\nהתעוררות ג' המבצעים דנשי ובנות ישראל, שהם כנגד ג' האבות שבחברון — ג' רגלי המרכבה, וזה מביא רגל הרביעי דוד (השייך לאדה\"ר — זוג הד' שבחברון); שלילת חוק \"מיהו יהודי\"; חלוקת צדקה ע\"י הטנקיסטים . . . . . . . . . . . . . . . . . סי\"ז­כד\n<h4>לך לך</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 255\nעידוד שלוחי חב\"ד שמקיימים בעצמם \"לך לך מארצך גו'\" מזה ש\"אחד הי' אברהם וירש את הארץ\" יש עידוד בעבודת כאו\"א ושלילת ייאוש וכיו\"ב מכתב ארוך בענין השטחים המשוחררים בארץ הקודש ביאור הטעם שנקט אד\"ש התואר \"ארץ ישראל\" ולא \"מדינת ישראל\" גורלה של העיר חברון המצור הפנימי על ירושלים תיקון על נתינת תעודת מילה לילד אסופי אין נוהגין לכבד אותו אדם בסנדקאות פעמיים\n<h4>וירא</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 263\nסיפור אדמו\"ר רש\"ב שבכה בילדותו על שלא נגלה אליו ה' ומענה הצ\"צ על זה יישוב הסתירה בין מ\"ש אד\"ש בשיחה שבמלאכים דאברהם לא נזכרה שתי' להיותה טפלה ומ\"ש בסה\"מ תקס\"ב שטעם הדבר הוא כי לא הוצרכו לשתי' מעלת המס\"נ דאברהם שלא חיפש אותה זריזות מתחילה לא לפני הבוקר\n<h4>חיי שרה</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 266\nסיפור הצ\"צ שהתנחם בעת פטירת זוגתו ע\"פ דברי בנו שהורהו על מרז\"ל וראה חיים עם אשה זו תורה ביאור בסיפור הנ\"ל — הטעם שהוצרך שבנו יודיעו המארז\"ל, משום שאין חבוש מתיר עצמו עוד בענין הנ\"ל ביאור לשון \"בתוך שאר אבלי ציון וירושלים\": אבלות הציבור ונחמת הציבור והיחיד חד הם עוד בענין הנ\"ל הנחמה היא בוודאות (כמו נחמת ציון וירושלים) והקב\"ה נותן כח להמשיך בחיים באופן המתאים ענין נחמה בכפליים באיכות שהאבלות תשתכח מן הארץ יפה שיחתן כו' — המשכה מעצמות חכ' שלמע'; הרמז בהא דהגמלים היו זמומין; המספר דעשרה גמלים נקרא לנערה ונשאלה את פי'\n<h4>תולדות</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 271\nדמיון יצחק לאברהם גם בפנימיות, ענין המשך הדורות; מוסד \"ברית אברהם\" חוברת \"באהלי רבקה\" (דבית רבקה בכפ\"ח ב') — רבקה היתה \"כשושנה בין החוחים\"\n<h4>ויצא</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 274\nמכתב לדינער דתומכי תמימים: תכלית כוונת ירידת הנשמה נרמזת ביציאת\nיעקב מבאר שבע לחרן כדי לבנות את בית ישראל \"נחלה בלי מצרים\" למעלה מ\"ופרצת\" ביאור בתניא פמ\"ה בענין \"וישק יעקב לרחל\"\n<h4>וישלח</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 276\nבבר­מצוה מגיעים למדריגת \"איש\" והיא הכנה לבוא לדרגת \"אדם\" שלילת הסברא לסדר נסיעת טיול ליתומי צה\"ל המגיעים לגיל מצוות סידור חגיגת בר מצוה שחל בט\"ו ניסן חגיגת בר מצוה צ\"ל ביומו\n<h4>י\"ט כסלו</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 278\nביאור הברכה \"לשנה טובה בלימוד החסידות וכו'\" שאינה סתירה למרז\"ל שבראש השנה נכתב ונחתם האדם על כל עניניו; מדוע אין כיו\"ב בחגה\"ש זמן מ\"ת; ביאור השם \"חג החגים\"; מקור השמועה שהגר\"ח מבריסק והגרח\"ע מוילנא התייחסו בכבוד לי\"ט כסלו ושנק' ר\"ה לחסידות הלימוד ביט\"כ צ\"ל בתורת בעל הגאולה, וגם להפיץ מעיינותיו ברכה ועידוד למתוועדים ביט\"כ חלוקת הש\"ס ואמירת תמניא אפי שבתהלים התוועדות י\"ט כסלו בכפר חב\"ד גם עבור אלה שבגדר \"חוצה\" מעלת ההתוועדות של ציבור בי\"ט כסלו ובפרט מתוך שמחה הכרח התוועדות ביט\"כ מענה למי שמתלבט אם ההכנה והצלחת ההתוועדות היתה כדבעי זמן סגולה להחלטות טובות שלילת השתתפות במסיבה לכבוד רב קונסרבטיבי ענין ה\"מעמד\" ומעלתו; שיטת כל נשיאי חב\"ד שמסרו נפשם לטובת כל יהודי סידור החשמל בכפר חב\"ד והרמז בזה לי\"ט כסלו; חשיבות הפרט; תניא ראשון שנדפס בחצי כדור התחתון יום התחלת הפצת המעיינות באופן מיוחד הכרח לימוד פנימיות התורה, בפרט בארץ הקודש \"מצוה לגלות זאת החכמה\" הנסיון הראה שיש הכרח ללמד בישיבות גם מוסר או חסידות מעלת לימוד חסידות בבית כנסת בעת רעוא דרעוין; מעלת מי שזכה ללמוד תורה ולקבל מאדמו\"ר סגולה לרפואת הבת — הוספה בהפצת חסידות חב\"ד לימוד פני' התורה צ\"ל לא רק בבוקר אלא גם בלילה, וכמו בנגלה דתורה — למיגרס ולעיונא הכרח לימוד תניא בכל יום ביטול הספק \"מי אני ומה אני\" ללמוד חסידות; גניבה דד\"ת — מותרת היא לימוד ספרי קבלה — שהובאו בחסידות אפילו אם לוקח מהחסידות רק החיצוניות ה\"ז עדיף על לא כלום; להזדרז בהפצת המעיינות ביטול מחשבות המבלבלות — ע\"י לימוד החסידות העדר לימוד החסידות מביא לקרירות במצוות לימוד החסידות צ\"ל בעיון ובהתבוננות וגם בחיות מעלת המתייחס למשפחת אדמורי\"ם; \"חסיד מקצועי\" הם שני הפכים; שלילת מעלת מי שלימד חסידות באופן ששינה את תוכנה לגמרי טעמי המתנגדים לחסידות בטלו לגמרי בזמננו בזמן הזה אין מתנגדים במובן הישן שיטת חב\"ד היא נחלת כל עם ישראל שלא להתפעל ממנגדים המפריעים בהפצת המעיינות בין בני תורה ביטול ושלילת הטענה שדי לו להקב\"ה בר\"ן איש וכו' ואי\"צ לעסוק בקירוב כל בנ\"י הבעת צער על רצון לבטל לימוד חסידות חב\"ד בבית כנסת מברקים למשתתפים בהתוועדויות הגדולות דיט\"כ תש\"נ לאנ\"ש — תש\"נ לאנ\"ש — תנש\"א; למשתתפים כו' — תנש\"א לאנ\"ש — תשנ\"ב; למשתתפים כו' — תשנ\"ב\n<h4>וישב</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 308\nביאור בדברי הרמב\"ן בריש הפרשה \"והכוונה להגיד כי הם בוחרים לגור בארץ הנבחרת\" אסור לדבר לה\"ר על עצמו, מצב האדם כבחלומות שאפ\"ל חיבור ב' הפכים פתרון חלומות גשמים בחלום\n<h4>י\"ט כסלו — חנוכה</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 309\nג' הענינים שבנס חנוכה — שמן טהור, מוסיף והולך, הארת החושך — בהפצת המעיינות המלחמה נגד שינוי הלוח ע\"י או\"ה (באופן המהרס עניני יהדות), והלימוד ע\"ז מחנוכה וי\"ט כסלו הצד השוה שבנס חנוכה וי\"ט כסלו ימים שבין י\"ט כסלו וחנוכה — מסוגלים לקביעת שיעור בחסידות והליכה בדרכי' עבודת נשי חב\"ד בג' הפרטים ד\"יפוצו\", \"מעיינותיך\", \"חוצה\", והקשר לחנוכה מכתב לדינער דתומכי תמימים: הקשר לב' הימים; ג' הפרטים שבחנוכה — \"נר מצוה\", \"מוסיף והולך\", \"על פתח ביתו מבחוץ\" מטרת נר חנוכה להגיע ולהשפיע גם על המורדים בה', ושייך במיוחד למחנכים הסברת תפילת ועל הנסים ע\"פ עיקרי תורת חסידות חב\"ד; ניצול ימי הסגולה על הפצת המעיינות כסלו הוא חודש סגולה לנסים דנשמה ודגוף בטחון בה' ובפרט בימי סגולה אלה, בחודש כסלו החודש החסידי שלילת העצבות בתכלית; בפרט בימים אלה\n<h4>חנוכה</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 318\nההפרש בין נרות חנוכה ונרות שבת ונרות המקדש ימי חנוכה מספרם שמונה אף שהם לזכר מנורה בת שבעה קנים; אורה ושמחה — מן האורה באה השמחה מכתב לדינער דבית רבקה: ג' פרטים בנר חנוכה: הארת החושך, הארת החוץ, מוסיף והולך שלימות התורה, העם והארץ, גם משתשקע החמה \"בסדר\" אצל יהודי היינו מוסיף והולך ההכרח בזמננו להתאסף ולדבר בענין נס חנוכה מצות הימים — לימוד רזין דרזין ובאופן שמאיר גם בחוץ אור החסידות יאיר את תושבי כפר חב\"ד מנהגי חב\"ד בחנוכה ברכה ומענה לדו\"ח על \"מבצע חנוכה\"\n<h4>טבת</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 326\nירח שנהנה גוף — עצמותו ית' — מן הגוף, הבחירה שלמעלה בגוף דוקא\n<h4>ויחי</h4>\n. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 327\nשקו\"ט בדברי הרמב\"ן ר\"פ ויחי בהא דיעקב לא מת רשימת מנהגי אבילות הלל ע\"י אבל העובר לפני התיבה; מעלת אמירת קדיש ע\"י נכד אף שהוא חיוב על אביו השתדלות להעמיד המצבה בהקדם הפירוש בנוסח הקדיש \"בעלמא דברא כרעותי'\" העמדת מצבה בהקדם והשתתפות בהוצאות כשאין ידוע מקום מנוחת האם כדאי להזכיר שמה במצבה יישוב סתירת מאמרי רז\"ל לאחר כמה זמן המת משתכח מן הלב (מו\"ק ח, א. ברכות מח, א) ענין ירידה צורך עלי' בהסתלקות ואבילות יישוב הסתירה בין ב' ההלכות דאין מתקשין יותר מדאי וכל מי שאינו מתאבל הרי זה אכזרי; ב' ענינים בפטירה: שחרור הנפש מכבלי הגוף, וגרעון וחסרון בגוף אסור להרבות באבלות עלית הנשמה ע\"י חיזוק באמונה העיקר היא התוצאה: אם הזכרון או האבל מביא להוספה בקדושה או לא; האם יש הבדל אם יש לנפטרים מעלות מיוחדות; מעלת אנשים פשוטים; ההוראה מסיפור מאסר וגאולת י\"ב תמוז נחת רוח לנשמת האח הנפטר על ידי התעסקות בהבאת תועלת לילדי ישראל הקשר עם אח לא נפסק ע\"י פטירתו ביטול מחשבות שיש על אדם גזירה רעה הנצחון נגד המות ע\"י עבודת החינוך במקום שבו קרה מאורע זה הקשר עם הנשמה גם לאחר פטירתה, נח\"ר ע\"י עסק בתומ\"צ אופני קורת רוח שעל הבנים לגרום לנשמת האב מעלת המשך שיעורו של הנפטר הדפסת חידושי תורה של הנפטר ניחום על פטירת בעל \"תורה שלימה\" ע\"י המשך פעלו קורת רוח לנשמה ע\"י תומ\"צ כל דעביד רחמנא לטב עביד, אך אין נברא מבין את הבורא; להמשיך בפעולות דקדושה; ימי סגולה שבין יו\"ד כסלו וי\"ט כסלו אם לגלות לילדים ע\"ד פטירת אמם ואיך פטירת בת קטנה בערב פסח, כך שנדחה האבילות אשה שנפטרה במסיבת סיום והכנסת ספר תורה להודיע על ציון אדמו\"ר ע\"ד פטירת האב"],[1301670063,"<h3>שיחה א</h3>\nא. \"ויקרא האדם שמות לכל הבהמה ולעוף השמים ולכל חית השדה\"<sup data-n=\"1\">1</sup> — ולא נזכרו דגים. ומצינו בזה ב' דיעות<sup data-n=\"2\">2</sup>: יש מפרשים<sup data-n=\"3\">3</sup> שלא קרא להם שמות (ובטעם הדבר כתב הרד\"ק<sup data-n=\"4\">4</sup> \"ולא זכר דג הים כי לא יתכן לפי הטבע שנתן בהם הא­ל שיבואו לפני האדם כי אין חיותם כי אם במים וכשיוצאים מן המים ימותו, גם אין להם כלי הליכה אלא כלי השיטה\"), ויש אומרים<sup data-n=\"5\">5</sup> שגם לדגים קרא אדה\"ר שמות (אלא שלא נתפרש בקרא).\nולכאורה יש לומר, שב' דעות אלו תלויות בהגדרת ענינה של קריאת שמות. ובהקדם:\nאיתא במדרש<sup data-n=\"6\">6</sup> שאמר הקב\"ה למלאכי השרת שחכמתו של אדם מרובה משלהם, \"הביא לפניהם את הבהמה ואת החי' ואת העוף א\"ל זה מה שמו ולא היו יודעין העבירן לפני אדם א\"ל זה מה שמו (אמר) שור זה חמור זה סוס זה גמל כו'\".\nותוכן הענין שחכמת אדה\"ר היתה שהכיר את תכונתם וטבעם של כל ה­נבראים וקרא להם שמות המורים על מהותם וטבעם של הנקראים בשמות אלה, וכמבואר בארוכה במפרשי התו­רה<sup data-n=\"7\">7</sup> ומפרשי המדרש.\nויש לפרש זה בשני אופנים<sup data-n=\"8\">8</sup>: א) קריאת השמות היא לתועלת האדם, שע\"י השמות יכיר ויודיע את תכונות הנקראים בשם<sup data-n=\"9\">9</sup>. ב) קריאת השמות היתה בשביל הנבראים עצמם, דלפני שיש לנברא שם מיוחד הרי תכונות שלו אינן בגילוי (כ\"כ), וע\"י שנקרא בשם מיוחד הרי הם מתגלים וכו'<sup data-n=\"10\">10</sup>. ולפי זה, השם הוא (גם) לתועלת הנקרא בשם (וי\"ל שקריאת ה­שמות עצמה פועלת גילוי טבעו ותכונתו של הנקרא בשם).\nולכאורה י\"ל שזהו טעם החילוק בין הדיעות, אם קרא אדם שמות גם לדגים או לא:\nלהדיעה שלא קרא שמות לדגים — טעם הדבר הוא, לפי שקריאת השמות היא בשביל האדם, בשביל שיוכל ל­השתמש בהם וכו', וזה לא שייך (כ\"כ) בדגים, וכמ\"ש בחזקוני<sup data-n=\"11\">11</sup> \"דגים לא הביא כי בתוך המים הם ואינם יוצאים ואם יוצאים מתים ואין לו רדיי' עליהם\" [ד­",[["1","1","פרשתנו ב, כ."],["2","2","ראה תוד\"ה כל שיש לו — חולין סו, ריש ע\"ב, שנסתפקו בדבר."],["3","3","רד\"ק, חזקוני עה\"פ ב, יט. פענח רזא פ' שמיני. ועוד."],["4","4","ועד\"ז בחזקוני שם (כדלקמן בפנים)."],["5","5","מדרש חסר ויתיר, הובא בתו\"ש כאן (אות רסה). וראה בהנסמן שם מתנחומא שמיני ועוד, שקרא שמות \"לכל הבריות\" (אלא שאינו מפורש שם בנוגע לדגים במיוחד)."],["6","6","ב\"ר פי\"ז, ד."],["7","7","ראה רמב\"ן ובחיי כאן פסוק כ. רד\"ק ומנחה בלולה פסוק יט. ועוד."],["8","8","ראה צפע\"נ עה\"ת כאן ב, יט."],["9","9","ראה גם פי' ר\"י בכור שור כאן. — נוסף לזה שנוגע לכמה דינים דאיסור והיתר וטומאה כו'. וראה פרש\"י שמיני (יא, כא): וצריך שיהא שמו חגב. פ' ראה יד, יג. ועוד."],["10","10","ראה נזר הקדש (השלם) לב\"ר שם."],["11","11","כאן יט. וראה גם רד\"ק שם בתחלתו. ול­העיר שבחזקוני שם מסיים \"וכל אשר יקרא לו גו' כדי שידע מעצמו להזכיר שמותם כשיצטרך להם, שאילו קרא להן הקב\"ה שמות ומלמד אותם לאדם לא הי' יודע הדבר מהר וקשה לו ליכנס בדבר\", והיינו דהשם הוא לתועלת האדם."]]],[1301670064,"אע\"פ שמפורש בכתוב<sup data-n=\"12\">12</sup> \"וירדו בדגת הים\" — הרי אינו דומה הרידוי בדגים<sup data-n=\"13\">13</sup> להרידוי בכל חית השדה וכו', שבהם שולט האדם בעודם בחיים ומשתמש בהם, משא\"כ בדגים שהרדיי' בהם היא באופן שמוציאם מן המים ועי\"ז מתים ואוכלם<sup data-n=\"14\">14</sup> כו'] — וכיון שהיא השתמשות מועטה, אין צורך שאדה\"ר יקרא אותם בשמות.\nולדיעה שקרא שמות גם לדגים, ה\"ז לפי שקריאת שמות היא (בעיקר) בשביל הבע\"ח עצמם, שעי\"ז מתגלה טבעם ו­תכונתם<sup data-n=\"15\">15</sup>, וזה שייך גם בדגים.\nב. ויש לומר, שזהו תוכן פרש\"י עה\"פ<sup data-n=\"16\">16</sup> \"וכל אשר יקרא לו האדם נפש חי' הוא שמו\" — \"סרסהו ופרשהו, כל נפש חי' אשר יקרא לו האדם שם הוא שמו לעולם\", דלכאורה מאי קמ\"ל רש\"י במה שהוסיף שזהו שמו \"לעולם\"? ואמאי לא פי' (כפשטות הלשון) שהשם שקרא אדה\"ר הוא ע\"י זה שהכיר טבעו ותכונתו של הדבר, בלשון הרד\"ק \"הוא שמו — הוא שמו הנאות לו לפי טבעו\", או כמ\"ש בחזקוני \"הוא השם הראוי לו, שהסכימה דעתו לדעת בוראו\"<sup data-n=\"17\">17</sup>.\n[ובעומק יותר איתא בספרים פירוש \"הוא שמו\", דשמו אשר קרא אדה\"ר הוא שמו האמיתי והעצמי, ולדוגמא שור שנקרא שמו כך ע\"ש שורשו שהם ג' אותיות שור בלה\"ק וכן כולם ולכן אדה\"ר שהי' בו חכמה יתירה והשיג וידע השורש והתוכן של כל מין ומין הי' יכול לקרותם בשם האמיתי, כפי שהא­ריך הרב המגיד<sup data-n=\"18\">18</sup>],\nוי\"ל ששיטת רש\"י היא כאופן הב' הנ\"ל, דבקריאת השמות היתה פעולה ע\"י אדה\"ר לגלות תכונות אלו, וע\"פ זה מפרש רש\"י \"הוא שמו לעולם\", שפעולת אדה\"ר היא פעולה תמידית ונצחית בדבר הנקרא בשם זה<sup data-n=\"19\">19</sup>.\nג. והנה התחלת הענין בתורה ע\"ד קריאת השמות היא \"ויצר ה' אלקים מן האדמה כל חית השדה ואת כל עוף השמים ויבא אל האדם לראות מה יקרא לו וכל אשר יקרא לו האדם נפש חי' הוא שמו\", ואח\"כ ממשיך אודות קריאת השמות בפועל — \"ויקרא האדם שמות גו'\".\nולכאורה מזה שהכתוב מתחיל בענין \"ויצר ה\"א גו'\" (אף שסיפור בריאת הנבראים כבר נאמר לפנ\"ז בפרשה), יש להביא ראי' שקריאת השמות היא דבר הנוגע ופועל בגוף הנבראים, ולכן נאמר זה כהמשך ל\"ויצר ה\"א גו'\" — יצירת הנבראים — כיון שקריאת שמותם הוי כגמר יצירתם.\nאבל הרי כבר הביא רש\"י<sup data-n=\"16\">16</sup> מ\"דברי אגדה\"<sup data-n=\"21\">20</sup>, ד\"יצירה זו לשון רידוי וכבוש",[["12","12","א, כו. שם, כח."],["13","13","ועד\"ז \"בכל רמש\" ואפילו בעוף שמים (ולהעיר מפרש\"י א, כו: בחיות ובהמות (ואינו מזכיר עוף ורמש)). אבל לכאורה בדגים הוא פחות גם מזה. וראה סנהדרין שבהערה הבאה."],["14","14","ראה סנהדרין נט, ב (צויין בצפע\"נ שב­הערה הבאה). אבל מובן שאינו דומה להרדי' בחיות ובהמות."],["15","15","להעיר מב' האופנים שבצפע\"נ עה\"ת כאן (א, יט. כ), דהשם שנתן לו אדה\"ר הוא מין הסגולה שיש בו, או שהוא בכדי לקנותם. ע\"ש. וראה צפע\"נ למס' סופרים פ\"א (הועתק בצ\"פ כללי התוהמ\"צ ערך ש כלל קכב)."],["16","16","ב, יט."],["17","17","ראה גם מדרש תהלים מזמור ח."],["18","18","בספר אור תורה בתחלתו ד, סע\"ב ואילך. וראה מדרש תהלים שם. של\"ה יד, א. לט, ב — בהגהה. פני דוד עה\"ת כאן אות ט. ועוד."],["19","19","וראה פי' ר\"י בכור שור."],["16","16","ב, יט."],["21","20","ב\"ר פי\"ז שם."]]],[1301670065,"כמו כי תצור אל עיר<sup data-n=\"22\">21</sup> שכבשן תחת ידו של אדם\", ולכאורה כן צריך לפרש לפי הדיעה שקריאת השמות היא רק לתועלת האדם, וכמובן גם ממ\"ש בחזקוני, כנ\"ל, דהשם שייך לרדיי' עליהם<sup data-n=\"23\">22</sup>.\nאבל מ\"מ משמע מכללות תוכן הפר­שה שקריאת השמות הייתה בה פעולה בהנקרא בשם — שהרי הפסוקים ע\"ד קריאת שמות נאמרו בתוך הפרשה ד­עשיית עזר כנגדו (יצירת חוה), שמזה משמע שגם קריאת שמות להנבראים הוא שייך לדבר הנקרא בשם בדוגמת יצירת חוה שהיא גמר בריאתה (ודהאדם).\n[ואף שמפרשים<sup data-n=\"24\">23</sup> המשך הכתובים, דכשאמר הקב\"ה \"אעשה לו עזר כנג­דו\"<sup data-n=\"25\">24</sup>, הביא לפניו כל חית השדה וכו' לקרות להם שמות היינו להתבונן ול­הכיר טבעם, ולאחרי שראה והבין אדם בהם ובשמותם וראה שאין בנבראים הראוי להיות לו עזר כנגדו, \"ולאדם<sup data-n=\"1\">1</sup> לא מצא עזר כנגדו\", אז \"ויפל<sup data-n=\"27\">25</sup> ה\"א גו' ויקח אחת מצלעותיו גו' ויבן ה\"א את הצלע גו' ויביאה אל האדם\"<sup data-n=\"28\">26</sup> — הרי\n(נוסף על זה שצ\"ע בעצם הפירוש, דכיון שכלפי שמיא גליא שאין בנבראים מי שראוי להיות עזר כנגדו, מה טעם הביא אותם כולם לפני אדה\"ר שהוא יתבונן בטבעם כו' (ע\"י קריאת שמות) עד שיבוא לידי הכרה שאין עזר כנגדו — הרי)\nכיון שכל עניני התורה הם בתכלית הדיוק, מסתבר לומר, דזה שנאמר ע\"ד קריאת שמות בתוך פרשת בריאת חוה הוא (לא רק לפי שע\"י קריאת השמות נתברר לאדה\"ר שאין בהם מי שיהי' עזר כנגדו, אלא) בעיקר לפי שיש בזה שייכות גם בתוכן ענינם].\nד. ונ\"ל שלכו\"ע קריאת שמות ד­אדה\"ר היתה בזה פעולה בהנקראים בשם, אלא שיש בזה שני אופנים, כד­לקמן.\nובהקדים: בבריאת העולם — ב' עני­נים: א) עצם הבריאה ע\"י הקב\"ה היא באופן שנתהווה דבר בפ\"ע, שלא ניכר בו שמציאותו היא מהקב\"ה. ב) מטרת הבריאה היא — \"ויניחהו בגן עדן ל­עבדה ולשמרה\"<sup data-n=\"29\">27</sup>, שהאדם ע\"י עבודתו יפעול בעולם ובכל דבר שבו שיהי' בטל להקב\"ה [וכמו שעשה אדה\"ר תיכף כשנברא — ביום ו' — שדרש מכל הנב­ראים שיקבלו על עצמם מלכותו ושל­טונו של הבורא בהכריזו \"בואו נשתחווה ונכרעה נברכה לפני ה' עושנו\"<sup data-n=\"30\">28</sup>], ועד שיגלה בו אמיתית מציאותו, בלשון הרמב\"ם<sup data-n=\"31\">29</sup> ש\"כל הנמצאים. . לא נמצאו אלא מאמיתת המצאו\".\nועפ\"ז י\"ל שהם שני האופנים בפירוש תוכן קריאת השמות ע\"י אדה\"ר — אם הוי המשך וגמר גוף הבריאה שע\"י",[["22","21","שופטים כ, יט."],["23","22","ובלשון הצפע\"נ הנ\"ל \"כדי לקנותם\"."],["24","23","ראה רמב\"ן כאן פסוק יט, כ. צרור המור ואברבנאל כאן. ועוד."],["25","24","ב, יח."],["1","1","פרשתנו ב, כ."],["27","25","ב, כא­כב."],["28","26","ולכאורה זהו הטעם שרש\"י בפשש\"מ אינו מתרץ מדוע לא קרא אדה\"ר שמות להדגים, כיון שהפסוקים דקריאת שמות בפשש\"מ הם בפרשה ד\"אעשה לו עזר כנגדו\" אולי ימצא מחית השדה וכו' שיוכל להיות לעזר (ולהשתמשות) לו, ובנוגע לדגים אין קס\"ד כזה, וכמ\"ש באברבנאל כאן."],["29","27","ב, טו. וראה תיב\"ע ות\"י שם."],["30","28","תהלים צה, ו. וראה זח\"א רכא, ב. ח\"ג קז, ב. תקו\"ז תנ\"ו (צ, ב). ועד\"ז בפדר\"א פי\"א. וראה אוה\"ת וארא ס\"ע רלו ואילך."],["31","29","ריש הל' יסוה\"ת."]]],[1301670066,"הקב\"ה, או שהוא בכלל מטרת הבריאה ופעולת האדם.\nה. ביאור הענין:\nמצד עצם בריאת הקב\"ה, אין בנב­ראים התחלקות למינים פרטיים אלא רק התחלקות כללית, לסוגים כללים. וכדמ­צינו בעשרה מאמרות שבהן נברא העו­לם<sup data-n=\"32\">30</sup>, שנתפרטו רק סוגים כללים [כמו: ביום ג' — תדשא הארץ דשא גו' עץ פרי גו'<sup data-n=\"33\">31</sup>; ביום ה' — ישרצו המים שרץ גו' ועוף גו'<sup data-n=\"34\">32</sup>; ביום ו' — בהמה ורמש וחיתו ארץ<sup data-n=\"35\">33</sup>] — ולא<sup data-n=\"36\">34</sup> שמות של מינים פרטיים (כמו בבע\"ח: שור, חמור, וכיו\"ב).\nוזהו תוכן ענין קריאת שמות ע\"י אדה\"ר, שעי\"ז<sup data-n=\"37\">35</sup> נעשה כל מין ומין ניכר ונפרד בפ\"ע.\n[וכמו שהוא ע\"ד ההלכה<sup data-n=\"38\">36</sup>, שע\"י קרי­אה בשמו הרי הוא קונה הדבר, והיינו שבזה מוציאו ומעתיקו מרשות אחרת (או מהפקר) לרשותו, וכן הוא בנתינת ה­שמות שבזה \"מוציאים\" אותו משייכותו (הכללית) למין הכללי שיהי' דבר פרטי].\nולפי זה, פעולת אדה\"ר בקריאת ש­מות היתה להשלים את הבריאה עצמה, שרק אז נגמר כל מין בתכונתו המבדלת אותו ממינים אחרים (שבאותו סוג).\nויש לפרש ענין קריאת שמות ע\"י אדה\"ר בעומק יותר — שזהו חלק מ­עבודתו דהאדם, לפעול ביטול בנב­ראים:\nידועים דברי רבינו הזקן<sup data-n=\"39\">37</sup>, שכל הנבראים שבעולם, השמות שנקראו בהם בלשון הקודש הן הן אותיות הדיבור של הקב\"ה המהוות והמחיות נברא פרטי זה, ומקור כל השמות הוא מעשרה מאמרות שבתורה (שבהם נברא העולם), כי אף שלא נזכרו כל שמות הנבראים בעשרה מאמרות, הרי הם משתלשלים מעשרה מאמרות ע\"י צירופים וחילופים ותמורות האותיות — שלפי זה מובן, ששמות הנבראים הם ענין עצמי בהם, שתיכף בתחלת התהוותו של הנברא יש לו שמו שהוא חיותו.\nואם כן, הרי קריאת שמות ע\"י אדה\"ר לאחרי התהוותם הו\"ע נעלה יותר.\nויש לומר הביאור בזה:\nאף שכל נברא יש בו כח אלקי המחי' אותו, והוא שמו אשר נקרא בו בלה\"ק (שמקורו מעשרה מאמרות כנ\"ל), מ\"מ, אין חיות זה בגילוי בהנברא, ובפרט שאין הנבראים מרגישים החיות האלקי שבהם ואיך שכל מציאותם אינה אלא מאמיתת המצאו, ועד שיש מקום לטעות ש\"לי יאורי ואני עשיתיני\"<sup data-n=\"40\">38</sup>. וזהו\"ע \"ויקרא האדם שמות גו'\" — שקריאה מורה על גילוי<sup data-n=\"41\">39</sup> — שאדה\"ר קרא וגילה בכל נברא את החיות האלקי (שהוא \"שמו\"), ועי\"ז פעל ביטול בכל הנב­ראים<sup data-n=\"42\">*39</sup>.",[["32","30","אבות רפ\"ה."],["33","31","א, יא."],["34","32","א, יט."],["35","33","א, כד."],["36","34","ראה גם דברי רבינו הזקן (בשער היחוד והאמונה) — הובאו לקמן בפנים."],["37","35","להעיר מהמבואר בענין \"והלא במאמר אחד יכול להבראות אלא כו'\" (אבות שם), שמצד המאמר אחד לא היתה התחלקות בנבראים ונחלקו ע\"י שאר ט' המאמרות (ראה מפרשי המשנה. וראה לקמן בפנים בסוף הסעיף)."],["38","36","ראה צפע\"נ כאן, ומביא \"ע' קידושין כב, ב קורא לה\" (כיצד במשיכה קורא לה והיא באה)."],["39","37","שער היחוד והאמונה פ\"א. ע\"ש בארוכה. וראה שם פי\"ב."],["40","38","יחזקאל כט, ג. ועד\"ז שם, ט."],["41","39","ראה תניא ספל\"ז."],["42","*39","ראה לקו\"ת נצבים (מז, ב) בפי' \"וירדו ב­דגת הים ובעוף השמים\"."]]],[1301670067,"ובעומק יותר יש לומר: החיות ה­מתלבש בכל נברא הוא חיות מצומצם, שזהו תוכן ענין השתלשלות השמות מעשרה מאמרות שבתורה ע\"י חילופים ותמורות כו' — שזהו צמצום וירידת החיות ממדרגה למדרגה \"עד שיוכל להתצמצם ולהתלבש ולהתהוות ממנו נברא פרטי\"<sup data-n=\"43\">40</sup>. אבל, ע\"י שאדה\"ר קרא להם שמות, הרי קרא והמשיך וגילה בכל נברא גם מקור ושרש של שמו מעש\"מ, למעלה מכפי שיורד ומתצמצם להוות נבראים פרטים אלה, ועד ל\"(מו­צא) פי ה'\"<sup data-n=\"44\">41</sup> בעצמו, \"שעליו אמרו<sup data-n=\"32\">30</sup> ו­הלא במאמר אחד יכול להבראות, הוא המאמר הכולל כל העשרה מאמרות וממנו נמשכו ונתחלקו עשרה מאמרות פרטיים\" (וכמבואר בלקו\"ת<sup data-n=\"46\">42</sup>).\nו. ויש לומר שזהו היסוד לשתי הדיעות (הנ\"ל) אם אדה\"ר קרא שמות גם לדגי הים, או רק לכל הבהמה ולחית השדה גו':\nלפי האופן הא' (כמשמעות פשטות הכתובים) שקריאת השמות ע\"י אדה\"ר היתה להגדיר טבעו הפרטי של כל נברא, והיינו הפרדת מציאותם ממקורם — ה\"ז רק בברואים שביבשה (כל הבה­מה ועוף השמים וחית השדה), שמתחלה נבראו באופן כזה שהם מובדלים ונפ­רדים ממקורם; משא\"כ<sup data-n=\"47\">43</sup> בדגים שבים שלא נבראו להיות מציאות בפ\"ע אלא תמיד מכוסים ומובלעים במים, וכל מציאותם היא המים<sup data-n=\"48\">44</sup> [וכמודגש בדין דכל שבים טהור<sup data-n=\"49\">45</sup>, כיון שעיקר מצי­אותם הוא המים<sup data-n=\"50\">46</sup> (ועד שלדעת רשב\"ג<sup data-n=\"51\">47</sup> כל שהוא מבריאת המים אינו חוצץ, דאמיתית מציאותם היא המים)]<sup data-n=\"52\">48</sup> — אין מקום לקריאת שמות<sup data-n=\"53\">49</sup> להפרידם ממקו­",[["43","40","שער היחוד והאמונה שם (פ\"א)."],["44","41","לשון הכתוב — עקב ח, ג."],["32","30","אבות רפ\"ה."],["46","42","נשא כו, ב (וראה גם שם כז, א). וראה מאמרי אדה\"ז — אתהלך לאזניא ע' נט. ובכ\"מ. וראה בארוכה בכללות ביאור ענין קריאת שמות דאדה\"ר — לקו\"ש חט\"ו ע' 13 ואילך."],["47","43","כי כל הנבראים שבעולם שלמטה שרשם מעולמות שלמעלה, וב' סוגים אלה (נבראים ש­ביבשה ונבראים שבים) בשרשם \"הם שני מיני עולמות עלמין סתימין דלא אתגליין (הקדמת תקו\"ז פתח אלי') הם המתהוים וחיים וקיימים מכחות והמשכות נעלמות כמו אותיו' המחשבה שבנשמת האדם עד\"מ ועלמין דאתגליין (תקו\"ז שם) נבראו וחיים מהתגלות שנתגלו כחות והמשכות הנעלמות הנקראות בשם אותיו' המחשב' וכשהן בבחי' הת­גלות להחיו' עלמין דאתגליין נקראות בשם מאמרות ודבר ה' ורוח פיו כמו אותיות הדבור באדם עד\"מ כו'\" (שער היחוד והאמונה פי\"א (פח, ב))."],["48","44","ראה ביאוה\"ז לאדמו\"ר האמצעי בשלח (מא, סע\"ג ואילך). תו\"ח בראשית (ח\"ב) ד\"ה ויתן לך (פי\"ז). ביאוה\"ז להצ\"צ ח\"א ע' רז ואילך. ובכ\"מ."],["49","45","כלים פי\"ז מי\"ג. רמב\"ם הל' טומאת מת רפ\"ו."],["50","46","ראה מדרש תלפיות ענף אדה\"ר (כ, ד — בהוצאת ווארשא, תרל\"ה) בשם ספר סודי רזא \"חיות המימיות אינן מקבלין טומאה כי האדם לא קרא להם שם\". והיינו, דכיון שלא נגמרה (נצטיירה) מציאותם אינם מקבלים טומאה (ראה כלי חמדה ריש פרשתנו אות ב'). וראה מאמרי אדה\"ז הקצרים ע' תנה."],["51","47","מקואות פ\"ו מ\"ז. ידים פ\"ב מ\"ב. ולהעיר שברמב\"ם הל' מקואות (פ\"ח הי\"א) ובשו\"ע (יו\"ד סר\"א סל\"ג) פסקו כוותי' דמותר להטביל בו (כ­זבחים כב, א), אף שלא פסקו כוותי' בנוגע לשיעור דשפופרת הנוד, דהרמב\"ם (שם ה\"ו) ושו\"ע (שם סנ\"ב) פסקו דהם ממעטין בהשיעור. וכבר שקו\"ט בתויו\"ט מקואות שם. ועוד. וראה בהנסמן בלקו\"ש חכ\"ז ע' 241 הערה 45."],["52","48","ולהעיר גם מהדיעה שהדגים לא מתו במבול (פרש\"י נח ז, כב. מסנהדרין קח, סע\"א. וש\"נ) כיון \"שלא היו בכי השחית כל בשר\" (מדרש לקח טוב נח שם)."],["53","49","וע\"פ המבואר בשער היחוד והאמונה שם, שחיות כל דבר הוא השם שלו שהן האותיות מעשרה מאמרות שירדו כו' להחיות נברא זה, צ\"ל לכאורה, דשמות של ברואים שבים כו' אינם בהתגלות כ\"כ. ולהעיר דשם של דגים המפורש בכתוב (ישעי' כז, א. תהלים עד, יד. ועוד) וברז\"ל (ראה רש\"י פרשתנו א, כא. מב\"ב עד, ב. ב\"ר פ\"ז, ד. תיב\"ע עה\"פ בראשית שם) הוא רק \"לויתן\", ש\"לויתן הוא לשון התחברות כמו (ויצא כט, לד) הפעם ילוה אשי אלי\" (לקו\"ת שמיני יח, ב. וראה גם לקו\"ת פינחס עז, ג. תו\"א כג, ב). — וראה שיחת יום שמח\"ת תשמ\"ט."]]],[1301670068,"רם (יותר מן הפירוד שמצד עצם בריאתם), כי תוכן מציאותם מצד בריאת הקב\"ה<sup data-n=\"54\">50</sup> הוא לא להיות נפרדים<sup data-n=\"55\">51</sup>.\nובזה יש לבאר עומק כוונת דברי הראשונים הנ\"ל<sup data-n=\"56\">52</sup> בטעם שלא קרא אדה\"ר שמות לדגים, שא\"א שיבואו לפני האדם כי אין \"חיותם כ\"א במים וכשיוצ­אים מן המים ימותו\" — שאין זה טעם וסיבה חיצונית, שא\"א שיובאו לפני אדה\"ר שיקרא להם שמות, אלא שזהו בהתאם לתוכן ענין השמות, דכיון ש­מציאות הדגים היא התכללות במקורם ולא פירוד ויציאה חוץ למקורם, לכן אין מקום לקריאת שמות לדגים.\nאבל לפי הביאור הפנימי הנ\"ל דענין קריאת שמות הוא להשלים מטרת בריאת כל הנבראים, לקרוא ולהמשיך בהם החיות ממקורם ושרשם, שעי\"ז יוכללו ב\"מוצא פי ה'\"<sup data-n=\"44\">41</sup> מקור ושורש התהוותם כנ\"ל — ה\"ז בכל הנבראים, לא רק ברואים שביבשה, שבגלוי הם נפרדים ממקורם, אלא גם בדגים שבים<sup data-n=\"42\">*39</sup>, כי, מציאותם כפי שהיא למטה היא מציאות נברא, אלא שאמיתת מציאותם היא מי הים<sup data-n=\"59\">53</sup>, ועבודת האדם היא לפעול בהם ביטול והתכללות במקורם, ביטול ל­מעלה מזה.\nוי\"ל שזהו בהתאם לתוכן בריאת ויצירת חוה המבואר בפרשה זו: בחי­צוניות הדברים (יצירתה של) חוה הביאה לידי ירידה באדה\"ר, כפשוטו לחטא עה\"ד שגרם ירידה באדם ובכל הבריאה כולה; ולאידך — מטרת בריאתה היתה לפעול עלי' בהבריאה כמ\"ש<sup data-n=\"60\">54</sup> \"פרו ורבו ומלאו את הארץ וכבשה ורדו בדגת הים ובעוף השמים ובכל החי' הרומשת על הארץ\", וע\"י שהאדם ממלא שליחותו בעולם ומלאו את הארץ ה\"ז פועל עלי' שלא בערך בהאדם עצמו.\n<span data-k=\"q\">(משיחות ש\"פ בראשית תשל\"ז, תשמ\"ו)</span>",[["54","50","ואולי י\"ל שלכן לא נאמר בפסוק שקרא שמות לרמשים כו' וכיו\"ב, כי כיון \"שהם נמוכים ורומשים על הארץ ונראים כאילו נגררים שאין הילוכן ניכר\" (לשון רש\"י פרשתנו א, כד), הרי בריאתם מתחילה היא באופן כזה שאין ניכרת (כ\"כ) הבדלתם מן הארץ. ובמדרש הנ\"ל הערה 5 — שבו נאמר שקרא שמות גם לדגים — הובא גם \"ולשרצים וליתושים וכו' ולכל בריות שבעולם\"."],["55","51","ראה לקו\"ת בלק (סז, ג) דהשמות הוא רק להנבראים דעלמא דאתגליין, משא\"כ בנבראים דעלמא דאתכסיא. וראה לקו\"ת בהר מא, ג."],["56","52","ראה לעיל ס\"א ובהנסמן שם."],["44","41","לשון הכתוב — עקב ח, ג."],["42","*39","ראה לקו\"ת נצבים (מז, ב) בפי' \"וירדו ב­דגת הים ובעוף השמים\"."],["59","53","וראה ד\"ה וראיתי אני תרס\"ב (סה\"מ תר\"ס­ס\"ב ע' שנ ואילך), שגם דגים אף שהם בטלים הם מציאות נבראים. וע\"ש שעד\"ז הוא בנבראים דעלמא דאתכסייא."],["60","54","פרשתנו א, כח."]]],[1301670069,"<h3>שיחה ב</h3>\nא. לאחר סיפור בריאת העולם ואדם וכו', מסופר בפ' בראשית אודות צאצאי­הם ותולדותם של שני בניו של אדם, קין<sup data-n=\"61\">1</sup> ושת<sup data-n=\"62\">2</sup>. ובפשטות, הרי הם חלוקים זה מזה מן הקצה אל הקצה, דקין מורה על היפך בנין העולם, שהרג את הבל<sup data-n=\"63\">3</sup>, והי' נע ונד בארץ<sup data-n=\"64\">4</sup>, ואילו שת הרי ממנו הושתת העולם<sup data-n=\"65\">5</sup>, דלאחר המבול הי' בנין העולם ע\"י נח<sup data-n=\"66\">6</sup>, מזרע שת.\nומצינו בזה דבר פלא, שלשניהם הי' צאצא בשם חנוך<sup data-n=\"67\">7</sup> — בנו של קין ואחד מצאצאי שת<sup data-n=\"68\">8</sup> — ובשניהם מודגש תוכן הפכי משל אביהם: בקשר לחנוך בנו של קין נאמר<sup data-n=\"69\">9</sup> \"ויהי (קין) בונה עיר ויקרא שם העיר כשם בנו חנוך\", ובחנוך מצאצאי שת נאמר<sup data-n=\"70\">10</sup> \"ויתהלך חנוך את האלקים ואיננו כי לקח אותו אלקים\", והיינו דבנוגע לחנוך בנו של קין מודגש בתורה ענין של \"בנין\" וקיום (היפך ענינו של קין), ואילו בנוגע לחנוך שבא משת, מפורש בו היפך ענין של קיום (הושתת העולם), \"ואיננו\"<sup data-n=\"71\">11</sup>.\nגם צ\"ב, דהנה זה פשוט שכל הפרטים שנאמרו ונתפרשו בתורה בסיפור \"תול­דות אדם\"<sup data-n=\"72\">12</sup> נוגעים להמשך תולדות אדם במשך הדורות שלאח\"ז. וכמובן בפש­טות, דמזה שהתורה מספרת רק פרטים אלו ממה שאירע במשך יותר מאלף שנה, אף שהיו הרבה מאורעות במשך הזמן ההוא, מובן, שרק בפרטים אלו יש ענין להמשך הדורות<sup data-n=\"73\">13</sup>. ועפ\"ז צ\"ע: מזה שהתורה מפרטת בחנוך שמבני בניו של שת, \"ויתהלך חנוך את האלקים ואיננו כי לקח אותו האלקים\", הרי זה מובן בפשטות (נוסף על דרשת רז\"ל<sup data-n=\"74\">14</sup>), כי זהו",[["61","1","ד, יז ואילך."],["62","2","ד, כה­כו. ה, ו ואילך."],["63","3","ד, ח."],["64","4","ד, יב ואילך ובמדרשי רז\"ל ופרש\"י שם. וראה פרש\"י (ד, כד מב\"ר — ראה שם פכ\"ג, ד): נגזרה גזירה לכלות זרעו של קין לאחר שבעה דורות. אבל במרז\"ל שני (פרש\"י ד, כב מב\"ר (פכ\"ג, ג)) א' מיוצאי חלציו של קין ניצל במבול — \"נעמה היא אשתו של נח\" (וראה מפרשי רש\"י שם (ד, כד) במה שאמרו \"למחר המבול בא ושוטף את הכל\", אם גזירת כליון זרעו של קין וגזירת המבול גזירה אחת היא). וראה רמב\"ן עה\"פ: א\"כ נשאר לקין זכר מעט בעולם."],["65","5","רמב\"ן ה, ג. וראה ת\"ז תס\"ט (קי, א). ת\"ע (קיט, סע\"ב ואילך)."],["66","6","ראה רש\"י ה, כח."],["67","7","ראה לקוטי לוי יצחק ליקוטים על פסוקי תנ\"ך ומחז\"ל ריש ע' ח: וע\"כ לומר שהב' בחי' למך שמקין ושמשת יש להם שייכות זה לזה כי הרי שמם אחד הוא ושנים מיוצאי חלצי קין ושנים מיוצאי חלצי שת שווים בשמותיהם זה לזה והם חנוך ולמך מקין וכן חנוך ולמך משת. וראה ת\"ז ת\"ע בתחלתו."],["68","8","ה, יח ואילך."],["69","9","ד, יז."],["70","10","ה, כד."],["71","11","דנלקח לפני זמנו כפרש\"י ומדרשים עה\"פ."],["72","12","ל' הכתוב ה, א.\nאבל להעיר שכתוב זה נאמר לאחר פרשת קין ותולדותיו ובהמשך הכתובים שם ואילך לא נזכר מפורש ע\"ד קין ותולדותיו. וראה ב\"ר פכ\"ד, ה­ו. ולהעיר מרמב\"ן עה\"פ: ולפי דעתי ירמוז לכל התורה."],["73","13","ראה רמב\"ן ד, יז בסופו א' הפירושים, דלקין היו יותר דורות ממה שנאמר בתורה, והכתוב לא הי' צריך לספר בהם רק באלה, להודיע מי היו המתחילים בבנין הערים וכו'."],["74","14","ראה ב\"ר פכ\"ה, א."]]],[1301670070,"חלק מסיפור המשך הדורות ההם, שבכל אחד מהם נאמר \"ויהיו כל ימי גו' וי­מות\", ולכן מפרט בחנוך שאצלו הי' ב­אופן אחר, \"ואיננו כי לקח אותו אלקים\". אבל מה שנאמר בשייכות לחנוך בנו של קין, \"ויהי בונה עיר ויקרא שם העיר כשם בנו חנוך\", אינו מובן, מה זה נוגע להמשך תולדות אדם?\n[במדרש עה\"פ<sup data-n=\"75\">15</sup> איתא, ש(גם) בזה בא הכתוב לספר בגנותו של קין (\"קרבם בתימו לעולם<sup data-n=\"76\">16</sup>. . מה סבורין הרשעים כו'\"), וכן לפי כמה מפרשי התורה הרי זה מורה על מעשיו הרעים (\"שלא אמר ויבן עיר כאשר יאמר ויבן<sup data-n=\"77\">17</sup> את נינוה כו' כי הי' כל ימיו בונה העיר כי מעשיו ארורים ובנה מעט בטורח ועמל וינוע וינוד מן המקום ההוא כו'\"<sup data-n=\"78\">18</sup>), אבל לכאורה מפשטות הכתובים לא משמע הכי, וגם מסגנון פרש\"י שסתם \"ויהי קין בונה עיר ויקרא שם העיר לזכר בנו חנוך\" (אף שבכ\"מ בפרשה מפרש הטעם לסיפור כמה פרטים וענינים<sup data-n=\"79\">19</sup>), לא משמע שהוא פרט בסיפור גנותו וחסרונו אלא אדרבא<sup data-n=\"80\">20</sup>, ענין של בנין].\nובפרט ע\"פ דברי הזהר דתורה הוא מלשון הוראה<sup data-n=\"81\">21</sup> מובן, שגם בזה הוראה לדורות.\nב. בפשטות יש לומר:\nפסוק זה \"וידע קין גו' ותלד את חנוך ויהי בונה עיר גו'\", בא בהמשך לסיפור תשובת קין שאמר<sup data-n=\"82\">22</sup> \"גדול עוני מנשוא\" ועונשו וכו' \"ויצא קין מלפני ה' גו'\"<sup data-n=\"83\">23</sup> שיצא שמח<sup data-n=\"84\">24</sup> שנתקבלה תשובתו.\nוזהו שמלמדנו הכתוב בסיפור הולדת חנוך בנו ובנין העיר, שבעבודת התשובה אינו מספיק וידוי והכרת החטא<sup data-n=\"85\">25</sup> (\"גדול עוני מנשוא\"), וגם לא העונש שנגזר עליו מאת ה', ועד לגלות \"וישב בארץ נוד — בארץ שכל הגולים נדים שם\"<sup data-n=\"86\">26</sup>, \"שגלות מכפרת עון מפני שגורמת לו להכנע ולהיות עניו ושפל רוח\"<sup data-n=\"87\">27</sup> — אלא צריך לעשות פעולה \"לעשות איזו מצוה הפ­כית אל העבירה שעשה. . כי בזה יתוקן עוותו\"<sup data-n=\"88\">28</sup>, שלאחרי שאיבד נפש אחת — הוליד נפש אחרת \"וידע קין את אשתו ותהר ותלד את חנוך\".\nויתירה מזו, שהולך ובונה את העולם \"ויהי בונה עיר ויקרא שם העיר כשם בנו חנוך\", שהדגיש ופרסם סדר התשו­בה, שאינו מספיק ש\"צועק תמיד לפני",[["75","15","ב\"ר פכ\"ג, א. וראה גם מדרש לקח טוב עה\"פ."],["76","16","תהלים מט, יב."],["77","17","נח י, יא."],["78","18","ל' הרמב\"ן עה\"פ. וראה בארוכה כלי יקר עה\"פ."],["79","19","ראה פרש\"י ד, יט: לא הי' לו לפרש כל זה אלא כו'. וראה יפה תואר השלם לב\"ר (פכ\"ג, ב ד\"ה כולהון לשון מרדות) שמפרש הקושי' למה בכלל הוצרך לספר דורות אלו."],["80","20","וגם ברמב\"ן עה\"פ (ד, יז) מפרש \"נכתבו תולדות קין ומעשיו להודיע כי השם ארך אפים והאריך לו כי הוליד בנים ובני בנים כו'\". ע\"ש. וראה ת\"ז ת\"ע שם: ונפקו בנוי מיני' דעלו לג\"ע. ולהעיר, דגם בב\"ר (שם, ב) \"כולן לשון מרדות\" — הרי בפי' השמות מפרש כן רק בנוגע להבנים שלאח\"ז ולא בחנוך."],["81","21","זח\"ג נג, ב. רד\"ק הובא בגו\"א ריש פרשתנו."],["82","22","ד, יג — ראה ויק\"ר פ\"י, ה; פסיקתא דר\"כ פכ\"ה; ועוד, שמפסוק זה למדין \"שעשה תשובה\"."],["83","23","ד, טז."],["84","24","ב\"ר פכ\"ב, יג. ויק\"ר ופסיקתא שם."],["85","25","ראה ראב\"ע ורמב\"ן כאן. אברבנאל כאן. ועוד (והוא לא כפרש\"י — ראה בארוכה מפרשי רש\"י)."],["86","26","ד, טז ובפרש\"י."],["87","27","ל' הרמב\"ם הל' תשובה פ\"ב ה\"ד. וראה סנהדרין לז, ב ובחדא\"ג מהרש\"א שם."],["88","28","כלי יקר כאן ד, יז."]]],[1301670071,"השם בבכי ובתחנונים כו'\"<sup data-n=\"89\">29</sup>, אלא צריך לפעול \"בנין\" בעולם שמחוץ הימנו, שזה דורש תנועה הפכית מהכנעת ושפלות רוח דבע\"ת.\nוכשם שלמדים ממנו עצם ענין התשו­בה (כדאי' במדרש<sup data-n=\"84\">24</sup> שאדה\"ר למד מקין \"כחה של תשובה\"), עד\"ז הוא התוכן וההמשך דכתוב זה שממנו לומדים דרך תשובה.\nולפי זה מבואר גם הניגוד בחנוך השני (מצאצאי שת)<sup data-n=\"91\">30</sup> \"ויתהלך חנוך את האלקים גו' ויהי כל ימי חנוך גו' ויתה­לך חנוך את האלקים ואיננו כי לקח אותו אלקים\", דבזה מלמדנו הכתוב, דכאשר הנהגת האדם היא רק באופן של עבודה לעצמו, אין זו עבודה הרצוי'<sup data-n=\"92\">31</sup>, שאין מזה פעולה בעולם, ועד שימיו עצמו היו קצרים משאר בנ\"א שבזמן ההוא, שנלקח קודם זמנו<sup data-n=\"93\">32</sup>.\nג. אמנם הוראה זו היא מפירוש ה­כתובים לפי פשטות ענינם, שמדובר כאן בתשובה על חטא חמור ביותר של קין. אבל ע\"פ פנימיות הענינים<sup data-n=\"94\">33</sup> הרי (שרש) בחי' קין הוא נעלה ביותר מעת שנולד, שנקרא קין ע\"ש \"קניתי איש את ה'\"<sup data-n=\"95\">34</sup>, וכל הסיפור בנוגע לקין מעת הולדו כפי שהוא בכתוב, ש\"התורה (ש)מדברת בעצם בעליונים\"<sup data-n=\"96\">35</sup>, הוא במדריגה נעלית ביותר.\nולכן י\"ל, שההוראה מפסוקים אלה בנוגע לחנוך בנו של קין, וכן בנוגע לחנוך מיוצאי חלציו של שת, הוא לא רק בנוגע לעבודת הבע\"ת, אלא גם בנוגע לעבודת כאו\"א מבנ\"י בכל מקום ובכל זמן (ונוגע גם לזה ששם שניהם הי' חנוך), ובפרט ע\"פ מ\"ש הצפנת פענח<sup data-n=\"97\">36</sup> עה\"פ זה ספר תולדות אדם, ד\"כל המצי­אות שאירע אז הוא לעולם, כך באדם הפרטי וכמו באדם הכללי. . דכל דבר הנכתב הוא לא לשעה רק כל רגע ורגע הוא מציאות חדש\".\nד. ביאור הענין:\nבכללות הבריאה מצינו שתי תקופות — התקופה שלפני המבול, שלא הי' לה קיום, שנמחה כל היקום<sup data-n=\"98\">37</sup>, ואחרי המבול, שאז נפעל קיום בעולם באופן ד\"לא ישבותו\"<sup data-n=\"99\">38</sup>. ועד\"ז לאחרי המבול גופא — יש ב' תקופות: הדורות שלפני מ\"ת ול­אחר מ\"ת. דלפני מ\"ת הי' העולם במצב של \"ארץ יראה\"<sup data-n=\"100\">39</sup>, ולאחר מ\"ת נעשה במצב של \"ושקטה\"<sup data-n=\"100\">39</sup>.\nודוגמת ב' תקופות (ומצבים) אלו מ­צינו בעבודת בני ישראל גם לאחר מתן תורה [ועוד זאת — שכל זה חלק מ\"זה ספר תולדות אדם\"<sup data-n=\"102\">*39</sup>, המסופר בתורה, היינו שהיא הוראה נצחית לכאו\"א מ­ישראל עד סוף כל הדורות] — דבעבודת השם יש בכללות שתי דרכים<sup data-n=\"103\">40</sup> — עבו­דה בדוגמת בן עזאי שלא עסק בקיום",[["89","29","ל' הרמב\"ם הל' תשובה שם."],["84","24","ב\"ר פכ\"ב, יג. ויק\"ר ופסיקתא שם."],["91","30","ה, כב­כד."],["92","31","ראה סה\"מ תש\"ט ע' 184, ד\"צדיקים ש­עבודתם היא. . רק לעצמם, יהיו בבחי' תשובה לפעול גם בדבר שחוץ להם כו'\"."],["93","32","פרש\"י ומדרשים עה\"פ."],["94","33","ראה לקו\"ת להאריז\"ל פ' יתרו. וראה ספר הליקוטים דא\"ח צ\"צ ערך קין והבל. ועוד."],["95","34","ד, א. וראה פענח רזא שם (ד, ב): כלומר לעבוד את ה' שלא הי' לו שום אומנות זולת זה."],["96","35","ראה עש\"מ מאמר חקור דין ח\"ג פכ\"ג. של\"ה יג, ב ואילך. קסא, א ואילך. ובכ\"מ."],["97","36","עה\"ת להרגצ'ובי."],["98","37","נח ז, כג."],["99","38","שם ח, כב."],["100","39","תהלים עו, ט. שבת פח, א. וש\"נ."],["100","39","תהלים עו, ט. שבת פח, א. וש\"נ."],["102","*39","להעיר מב\"ר (פכ\"ד, ה): ראוי הי' אדה\"ר שתנתן תורה על ידו מ\"ט זה ספר תולדות אדם. רמב\"ן שבהערה 12."],["103","40","ראה אגה\"ק ס\"ה (קט, א): יש ב' מיני נשמות בישראל כו'. וראה ביאוה\"ז פ' וישב ל­אדמו\"ר האמצעי (כה, א­ב) ולהצ\"צ (ע' קלד)."]]],[1301670072,"העולם, לא נשא אשה ואמר \"מה אעשה שנפשי חשקה בתורה\"<sup data-n=\"104\">41</sup>, ועבודה של אלו העוסקים בישוב וקיום העולם. וב­סגנון תורת החסידות — העבודה ד­\"רצוא\", לצאת מגדרי העולם, והעבודה ד\"שוב\", לשוב ולעסוק בתוך עניני העולם.\nדאף שסדר עבודת השם צ\"ל לעסוק בישובו של עולם (ו\"כל מי שאינו עוסק בפרי' ורבי'. . כאילו שופך דמים ו­ממעט הדמות\"<sup data-n=\"105\">42</sup>), הרי \"אין זו אלא עצת חכמים המורים לאדם דרך ישרה שיבור לו, אבל ליכא איסורא כלל במילתא, אם חפץ ללמוד תורה כל ימיו ולא לישא אשה כלל כבן עזאי\"<sup data-n=\"106\">43</sup>, הרי שגם הנהגה זו היא ע\"פ תורה.\nובפרטיות יותר הרי עבודת השם בכלל יש בה שני קוים ותנועות אלו, וכפי שמצינו בכל ג' העמודים<sup data-n=\"107\">44</sup> דתורה עבודה (תפלה) וגמילות חסדים (מצות):\nבתורה: בלימוד התורה ב' אופנים: הלימוד באופן ד\"יגדיל תורה ויאדיר<sup data-n=\"108\">45</sup> — דרוש וקבל שכר\"<sup data-n=\"109\">46</sup>, ולימוד לאסוקי שמעתתא אליבא דהלכתא.\nובפרטיות ובדקות יותר: לימוד ה­תורה לשמה \"שתתעצם נשמתינו בעצמות ורוחניות וקדושת מקור מוצא התורה. . דבקים בקדושתה ובשכינתו ית'\" (כפי שהאריך הב\"ח<sup data-n=\"110\">47</sup> בתוכן ענין ברכת ה­תורה), והלימוד בשביל קיום המצות, לידע את המעשה אשר יעשון.\nבתפלה: מעיקרי התפלה היא הכוונה ש\"יראה עצמו כאילו הוא עומד לפני ה­שכינה\"<sup data-n=\"111\">48</sup>, ו\"חסידים ואנשי מעשה (ש)היו מתבודדים ומכוונין בתפלתן עד שהיו מגיעים להתפשטות הגשמיות ולהתגב­רות רוח השכלית עד שהיו מגיעים קרוב למעלת הנבואה\"<sup data-n=\"112\">49</sup>; תוכן מצות תפלה בקשת צרכיו מהקב\"ה<sup data-n=\"113\">50</sup>, שימלא חסרונו ומשאלותיו, עד לצרכיו ה­גשמיים, רופא חולים מברך השנים<sup data-n=\"114\">*50</sup>.\nבמצות: קיום המצות לשמה, לעשות נחת רוח לקונו, שאמרתי ונעשה רצוני<sup data-n=\"115\">51</sup>, עד לתכלית השלימות בזה, עבודה בכל מאדך, למעלה ממדידה והגבלה; קיום המצות \"לצרף את הבריות\"<sup data-n=\"116\">52</sup>, בשביל בירור וזיכוך העולם<sup data-n=\"117\">53</sup>, שעבודה זו צריכה להעשות בסדר מסודר בהתאם לגדרי ה­עולם.\nוהמקור לב' הנהגות אלו למעליותא הוא בשני האופנים שבתולדות אדם, למעליותא — קין ושת:\nלקין ותולדותיו לא הי' קיום<sup data-n=\"118\">54</sup>, והוא השרש והכלל לכללות מצב העולם לפני מ\"ת, ולעבודת ה' בדוגמת בן עזאי ש­למעלה מסדר ויישוב העולם; ושת ו­תולדותיו שממנו הושתת העולם ע\"י נח,",[["104","41","יבמות סג, סע\"ב."],["105","42","יבמות שם. ולהעיר שזהו דברי בן עזאי."],["106","43","הל' ת\"ת לאדה\"ז פ\"ג בקו\"א סק\"א בתחלתו."],["107","44","אבות פ\"א מ\"ב."],["108","45","ישעי' מב, כא (מהפטורת פ' בראשית). חולין סו, ב."],["109","46","סוטה מד, א. וש\"נ."],["110","47","לטור או\"ח סמ\"ז."],["111","48","רמב\"ם הל' תפלה פ\"ד הט\"ז (מסנהדרין כב, א). טושו\"ע (ודאדה\"ז) או\"ח סצ\"ח ס\"א."],["112","49","טושו\"ע (ודאדה\"ז) שם."],["113","50","שהוא המ\"ע דתפלה (ראה רמב\"ם הל' תפלה פ\"א ה\"ב. נ\"כ הרמב\"ם שם ה\"א. סהמ\"צ להצ\"צ שרש מצות התפלה בתחלתו. וש\"נ)."],["114","*50","ראה לקמן ע' 126 ואילך. 194 ואילך."],["115","51","רש\"י ויקרא א, ט. פרש\"י וספרי פינחס\nכח, ח."],["116","52","תנחומא שמיני ז­ח. ב\"ר רפמ\"ד. וש\"נ (וראה מו\"נ ח\"ג פכ\"ו)."],["117","53","ראה תניא פל\"ז."],["118","54","וראה לעיל הערה 4."]]],[1301670073,"שהוא \"ינחמנו ממעשינו גו'\"<sup data-n=\"119\">55</sup>, הוא השרש והכלל ב\"תולדות אדם\" למצב העולם שלאחרי מ\"ת, ובעבודת ה' גופא — העבודה דישוב וקיום העולם.\nה. ולפי זה יש לבאר הלימוד מזה שלקין הי' בן בשם חנוך, ובנה עיר בשם זה, ובין תולדות שת הי' ג\"כ בן בשם זה חנוך, אבל \"ויתהלך חנוך את האלקים ואיננו כי לקח אותו אלקים\" — דמזה למדים, שכל אחד מב' התנועות הנ\"ל צ\"ל כלול גם מהעבודה שבסוג השני, כמו שאצל קין שענינו היציאה מגדרי העולם ישנה העבודה ד\"בונה עיר\", סדר העבודה דבנין, ובסדר דשת, שממנו הושתת העולם, ישנו גם סדר העבודה ד\"ויתהלך גו' את האלקים ואיננו\", למעלה מהעולם<sup data-n=\"120\">*55</sup>.\nוביאור הדברים — בתורה תפלה ו­מצות:\nגם מי שעיקר לימודו הוא באופן דיגדיל תורה ויאדיר, דרוש וקבל שכר, צריך להיות אצלו לימוד לאסוקי שמע­תתא אליבא דהלכתא, וכן ביחד עם עסק התורה לדבקה בקדושתה צ\"ל הלימוד בשביל לידע את המעשה אשר יעשון [וע\"ד הענין הכללי דתורה ומצות דכל האומר אין לי אלא תורה אפילו תורה אין לו<sup data-n=\"121\">56</sup> אלא צ\"ל תורה וגמ\"ח<sup data-n=\"122\">57</sup>]; וכן להיפך, בעבודה שבסדר והדרגה — בלימוד לאסוקי שמעתתא אליבא ד­הלכתא ולימוד ע\"מ לידע את המעשה — צ\"ל נרגש ענין של לימוד להגדיל תורה ולהדבק בקדושתה כו'.\nוכן בתפלה: גם בתכלית הדביקות והתפשטות הגשמיות שבתפלה צריך להיות המכוון לפעול בעולם שמחוץ ממנו, וכידוע<sup data-n=\"123\">58</sup> בפי' מרז\"ל<sup data-n=\"124\">59</sup> דהמתפלל צריך שיתן עיניו למטה ולבו למעלה, שגם בתכלית הדביקות והרצוא דתפלה, צריך להיות המכוון שיפעול בעבודתו ובכחות נפשו כפי שהוא למטה אחר התפלה — \"עיניו למטה\"; וכן בבקשת צרכיו דתפלה צריך שיורגש בו תכלית הביטול והדביקות דעומד לפני ה' \"כעבדא קמי מרי'\"<sup data-n=\"125\">60</sup>.\nואותו הדבר במצות, שגם בעסקו במצות באופן דמס\"נ ואהבה רבה ד\"בכל מאדך\" צריך לקיים המצוות בגשמיות ובסדר מסודר; ולאידך, גם בעת עסקו בעבודה מסודרת בבירור וזיכוך נפשו הבהמית ובירור העולם צ\"ל הרגש הרצוא דבכל מאדך.\nו. לפי זה יש לבאר גם הרמז בשם \"חנוך\":\n\"חנוך\" הוא מלשון \"חינוך\"<sup data-n=\"126\">61</sup>, שענין החינוך, אף שבחיצוניות אין זה עיקר ותכלית בפ\"ע, כבמצות חינוך, שהתכלית היא שהקטן יגדל ואח\"כ יקיים מצוות בתור מחוייב בדבר, הרי בפנימיות ענין החינוך הוא יסוד על כל חיי האדם, כמ\"ש \"חנוך<sup data-n=\"127\">62</sup> לנער על פי דרכו גם כי",[["119","55","ה, כט."],["120","*55","ראה תו\"א שמות (נא, ד). תו\"ח שם (ס, א). מאמרי אדה\"ז תקס\"ב (ע' נח. סג). סה\"מ תרס\"ט (ע' לט)."],["121","56","יבמות קט, ב."],["122","57","ראה לקו\"ת ויקרא ה, א. וראה הערה בסה\"מ תש\"ח ע' 266."],["123","58","ראה לקו\"ת פ' ראה כד, א. ועוד."],["124","59","יבמות קה, ב."],["125","60","שבת יו\"ד, א."],["126","61","ראה ת\"ז ת\"ע בתחלתו. וראה תוס' השלם (ירושלים, תשמ\"ב) לבראשית ד, יז. ה, יח (אות א). וראה אוה\"ת חנוכה שב, ב ואילך. ובכ\"מ."],["127","62","משלי כב, ו. וראה (בנוגע לחנוך הב') ז\"ח יתרו פה, ב. אוה\"ת שם. ועוד."]]],[1301670074,"יזקין לא יסור ממנה\". כי אמיתית ענין החינוך<sup data-n=\"128\">63</sup> הוא לא רק שהקטן ילמוד, אלא הרגילות והכניסה לקדושה<sup data-n=\"129\">64</sup>, שענינה התקשרות נפשו עם הקדושה והקב\"ה, שלכן \"גם כי יזקין\" ועולה בעבודת ה' וקיום המצות, \"לא יסור ממנה\", והרי זה נותן הקיום והחוזק בקיום התומ\"צ שלו בכל המצבים.\nוהיינו, שהעבודה דישוב ובנין הכלו­לה בעבודה דרצוא בתורה תפלה ומצות (בחי' קין), וכן להיפך, העבודה דרצוא (\"ויתהלך גו' את האלקים ואיננו\"), ה­כלולה בעבודה דישוב העולם (בחי' שת) — אין זה רק פרט וטפל לעיקר העבודה, אלא זהו יסוד עבודתו, והוא הוא הפועל הקיום בעבודתו בדוגמת ענין החינוך.\nכי אף שהן שתי תנועות הפכיות, תנועה של התייחסות לעניני וגדרי ה­עולם (לימוד כדי לידע המעשה אשר יעשון, בקשת צרכיו, בירור העולם), ותנועה של עלי' ודביקות ורצוא, שאי אפשר להיות שניהם יחד אצל האדם — הרי מכיון ששניהם תלויים זב\"ז, מובן שבפועל אפשר שיהיו ביחד, אלא שאין זה מצד הנברא, אלא מצד כח הבורא שבעבודה זו, בדוגמת החינוך שתוכנו הפנימי הוא ביטול והתקשרות עצמית להקב\"ה.\nז. והביאור בזה:\nבכדי שיכוון להלכה לאסוקי שמעת­תא אליבא דהלכתא, הוא כאשר מגיע לדרגא נעלית יותר בלימוד והבנת התו­רה<sup data-n=\"130\">65</sup>, וכן בעבודה, בכדי לכוון להלכה מוכרח שיהי' אצלו בזה הביטול ל­אלקות, כמרז\"ל<sup data-n=\"131\">66</sup> \"והוי' עמו<sup data-n=\"132\">67</sup> שהלכה כמותו\", שדוקא הוי' שלמעלה משם אלקים פועל ש\"הלכה כמותו\"<sup data-n=\"133\">68</sup>. וכמבו­אר במ\"א<sup data-n=\"134\">69</sup> שכדי לכוון להלכה למעשה בפועל צ\"ל הלימוד מתוך שלימות היראה<sup data-n=\"135\">70</sup>.\nוכן הוא בענין התפלה, דההכרח שגם כשעוסק בבקשת צרכיו יהי' בתנועה של ביטול, הוא לא משום שהביטול וכו' הוא כמו דבר אחד המסייע ומחזק דבר שני, אלא מפני שבעומק ובפנימיות הענין ה\"ז דבר אחד, וכפירוש הה\"מ<sup data-n=\"136\">71</sup> ב\"אין עומ­דין להתפלל אלא מתוך כובד ראש\"<sup data-n=\"137\">72</sup>, \"אף שמבקש בקשת צרכי עצמו יהי' כוונתו שלא יחסר הדבר לעילא ח\"ו כי הנשמה היא חלק אלוה ממעל והיא אבר מאברי השכינה וזהו עיקר הבקשה שי­מולא ויושפע לעילא\". וכמבואר במ\"א<sup data-n=\"138\">73</sup>, דזה דבבקשת צרכיו צריך שיורגש ש­המכוון בזה הוא שיתמלא רצון השם ויתמלא חסרון דשכינה, אין הם ב' דברים, אלא כי מילוי בקשת צרכיו הוא מצד מילוי החסר למעלה כביכול, ל­היותו חלק אלקה ממעל ממש.",[["128","63","ראה תניא ח\"ב חינוך קטן (עו, ב). ביאור הרר\"ה מפאריטש ע\"ז (פלח הרמון בראשית בסופו). ס' השיחות תשמ\"ח ח\"ב ע' 615 ואילך. לקמן ע' 23 הערה 69."],["129","64","ראה שו\"ע אדה\"ז או\"ח מהד\"ת ס\"ד סוס\"ב: תחילת כניסת נפש זו הקדושה היא בחינוך לתורה ולמצות."],["130","65","ראה בארוכה שערי אורה ש' החנוכה ד\"ה בכ\"ה בכסלו פנ\"ד ואילך."],["131","66","סנהדרין צג, ב."],["132","67","ש\"א טז, יח."],["133","68","ראה אוה\"ת יתרו ע' תתצ ואילך. ד\"ה וידבר אלקים תרכ\"ז. המשך תרס\"ו ע' תלא ואילך. ועוד."],["134","69","המשך תרס\"ו שם ע' תו וע' תכ ואילך."],["135","70","ראה בכהנ\"ל לקו\"ש חט\"ו ע' 233 ואילך."],["136","71","או\"ת ר\"פ ויגש. וראה גם שם אגדות חז\"ל ד\"ה אין עומדין (קח, סע\"ג — בהוצאת קה\"ת), ועוד. וראה בהנסמן בהערה 73."],["137","72","ברכות רפ\"ה."],["138","73","לקו\"ש חכ\"ג ע' 217 ואילך."]]],[1301670075,"וכן בקיום המצות, דהפעולה בנפשו הבהמית וחלקו בעולם בבירורם וזיכוכם היא בשלימותה כשמרגיש שמקומו ודר­גתו האמיתי הוא לא למטה אלא למעלה, כפי שהנשמה \"חבוקה ודבוקה בך\"<sup data-n=\"139\">74</sup>, ואינה שייכת לצרכי הגוף והעולם כלל<sup data-n=\"140\">75</sup> (גם לא בשביל בירורם), דדוקא אז ישנו הכח בעבודתו בקיום המצות לפעול בנפש הבהמית והעולם לבררם ולזככם.\nוכשם שהוא בהעבודה ד\"שוב\", ש­בשביל שלימותה וקיומה כדבעי צ\"ל בזה ההרגש דרצוא, עד\"ז הוא לאידך, דזה שבתנועה דרצוא, תכלית הדביקות באלקות צ\"ל גם תנועת השוב, הוא לא רק בכדי שיהי' קיום להרצוא (דבלאו הכי עלול לצאת מהכלים לגמרי להדבק בה', ולא תבוא מזה פעולה בתורה ומצות), אלא זה נוגע לעצם תנועת הרצוא. כי אבן הבוחן על כך שמרוצתו לה' הו\"ע אמיתי ואינו רק בשביל שקרבת אלקים לי טוב, לרוות נפשו הצמאה, הוא<sup data-n=\"141\">76</sup> כאשר יחד עמה ישנה התנועה דשוב, שמנתק את עצמו מגודל דביקותו בה' ויורד למטה להשלים רצונו של הקב\"ה<sup data-n=\"142\">77</sup>, בתורה — הלימוד לאסוקי שמעתתא אליבא דהלכתא, לידע את המעשה אשר יעשון, וכן בתפלה ומצות, לעבוד בגופו ונפשו הבהמית וחלקו בעולם לבררם ולזככם.\nויתירה מזו: אין זה רק אבן הבוחן על דביקות הנשמה, אלא שעי\"ז נעשה עלי' ושלימות בהרצוא ודביקותו בה', ועד גם עלי' בהנשמה למעלה יותר מכפי שהיתה קודם ירידתה למטה<sup data-n=\"143\">78</sup>.\nח. ב' ענינים אלו שייכים במיוחד לפרשת בראשית, המדברת בבריאת ו­התהוות העולם, כי גם דבר ה' המחי' את העולמות בכל רגע (כתורת הבעש\"ט הידועה<sup data-n=\"144\">79</sup> עה\"פ<sup data-n=\"145\">80</sup> לעולם ה' דברך נצב בשמים, שדברך שאמרת יהי רקיע נצ­בות ועומדות לעולם בתוך רקיע השמים כו' להחיותם וכן בכל הברואים שבכל העולמות עליונים ותחתונים), דביקותו במקורו הוא באופן דרצוא ושוב, כמבו­אר בכ\"מ<sup data-n=\"146\">81</sup>, שהכח האלקי המהווה ומחי' את הנבראים הוא בחי' כח נבדל, כי החיות האלקית שהיא בדביקות במקורה ואינה דבר בפני עצמו, אי אפשר שתהי' מזה פעולה, וכ\"ש וק\"ו להתלבש בנבראים ולהוותם, ולכן ההתהוות היא מעשרה מאמרות<sup data-n=\"147\">82</sup> דוקא, שהם כח האלקי כפי שנעשה נבדל ממקורו כביכול, אבל לאידך, אין בכחו של כח נבדל להוות יש מאין, כי בריאה יש מאין היא רק בכחו ויכולתו ית' שאין לו עילה וסיבה שקדמה לו ח\"ו<sup data-n=\"148\">83</sup>, ולכן, בכדי שיהווה ויחי' את הנבראים צריך שיורגש בו מקורו באלקות, כפי שהוא למעלה מנתינת מקום להבריאה<sup data-n=\"149\">84</sup>, והיינו דהדביקות היא",[["139","74","ל' הושענות ליום ג'."],["140","75","ראה תניא ספמ\"א."],["141","76","שלכן מהד' שנכנסו לפרדס (חגיגה יד, סע\"ב) רק רע\"ק \"יצא בשלום\" לפי ש\"נכנס ב­שלום\". ראה בהנסמן בהערה הבאה."],["142","77","ראה ד\"ה אחרי מות וד\"ה שלאחריו תרמ\"ט. לקו\"ש ח\"ג ע' 988 ואילך. ובכ\"מ."],["143","78","ראה לקו\"ש חט\"ו ע' 245 ואילך. וש\"נ."],["144","79","שער היחוד והאמונה רפ\"א."],["145","80","תהלים קיט, פט."],["146","81","ראה ד\"ה תקעו תרס\"ד. ד\"ה למען דעת תרע\"ה (המשך תער\"ב ח\"ב ס\"ע תרפ ואילך). ובכ\"מ."],["147","82","אבות רפ\"ה."],["148","83","אגה\"ק ס\"כ (קל, ב)."],["149","84","ראה לקוטי לוי יצחק לתניא (ע' כד) בביאור מ\"ש בשער היחוד והאמונה רפ\"ג \"הדברים והאמת האלה\", דה\"דברים\" הם העשרה מאמרות, \"והאמת הוא ת\"ת דז\"א הנק' אמת. . מה שדבר ה' מלובש תמיד בתוך כל הנבראים ויכולה להוותם כו' מאין ליש כפי' הבעש\"ט ז\"ל הוא ע\"י שהיא נצבת ודבוקה במקורה בת\"ת דז\"א הנק' אמת וכפירוש האריז\"ל\", ע\"ש בארוכה."]]],[1301670076,"בבחי' רצוא ושוב ועי\"ז הוא מתחדש מ­מקורו תמיד.\nוגם בענין זה אין הם שני ענינים שונים השייכים זל\"ז, דהרצוא פועל ב­דרגת השוב — אלא, זה שדבר ה' מ­עשרה מאמרות מתלבשים בכל הנבראים להוותם ולקיימם, אף שמצד אחד ענינם הוא כח נבדל להוות, הרי ביחד עם זה נרגש בהם גופא, שמקומם האמיתי אין זה כפי שהם כח נבדל ומהווים הנבראים אלא כפי שהן במקורם, וזה שהם מתלבשים למטה בנבראים הוא רק מצד כוונת העצמות, הרי נמצא שב\"מקום\" ומצב ההבדלה גופא נרגש דביקותם במקורם<sup data-n=\"150\">85</sup>.\nט. ע\"פ כל זה יובן גם הקשר דפרשת בראשית לשמחת תורה:\nבשמח\"ת נמצאים בנ\"י לאחרי העבו­דה והגילויים דראש השנה ויוהכ\"פ וחג הסוכות שאז מתעלים בעילוי אחר עילוי מלמטה למעלה, וגם ישנה המשכה מל­מעלה למטה בפנימיות ע\"י לקיחת ד' מינים בחג הסוכות.\nולכן הרי בשמע\"צ ושמח\"ת בנ\"י הם בדביקות, שבנ\"י שמחים עם התורה בשמחה וריקודים שלמעלה ממדידה והגבלה לגמרי, בחי' ישראל ומלכא בלחודוהי.\nאבל ביחד עם זה ובהמשך לזה קור­אים פ' בראשית, בראשית ברא אלקים את השמים ואת הארץ<sup data-n=\"151\">86</sup>, להורות ש­אמיתית הדביקות דבנ\"י בהקב\"ה הוא בהשוב, שבנ\"י יוצאים בהעולם, לעשות לו ית' דירה בתחתונים<sup data-n=\"152\">87</sup>, שיתגלה כבוד מלכותו ית' בכל העולם כולו, והי' ה' למלך על כל הארץ ביום ההוא יהי' ה' אחד ושמו אחד<sup data-n=\"153\">88</sup>, ונעשים שמים חדשים וארץ חדשה<sup data-n=\"154\">89</sup>, בביאת משיח צדקנו תיכף ומיד ממש.\n<span data-k=\"q\">(משיחת כ\"ף מנחם אב תשל\"ב)</span>",[["150","85","וראה גם לקו\"ש ח\"י ע' 107 ואילך (בביאור תורת הה\"מ על פרש\"י ר\"פ וישלח \"מלאכים ממש\") עד\"ז לגבי עבודת השליחות."],["151","86","בראשית א, א."],["152","87","וכידוע דלאחר שמח\"ת ושבת בראשית מתחלת העבודה ד\"ויעקב הלך לדרכו\" (ל' הכתוב ס\"פ ויצא), העבודה בעניני העולם (ראה בארוכה לקו\"ש ח\"כ בהוספות — שיחות מוצש\"ק פ' בראשית, נח ולך תשל\"ח)."],["153","88","זכרי' יד, ט."],["154","89","ישעי' סו, כב."]]]]});
